INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(442, 89, '01:08:30', 'Errori di scena / Posizione', 'Durante la sequenza del salvataggio notturno sotto la pioggia, le macchie di fango e i segni di sangue sul viso e sulla canottiera nera di Rambo variano in modo inconsistente: in alcuni stacchi appare quasi completamente pulito, per poi tornare ricoperto di fango nell''inquadratura subito successiva.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(443, 89, '01:15:45', 'Errori storici o fattuali', 'Nella battaglia finale, Rambo prende il controllo della mitragliatrice pesante calibro .50 M2 Browning montata sul camion. L''arma spara una raffica continua di centinaia di colpi senza interruzione da un unico nastro di munizioni contenuto in una scatola standard, la quale fisicamente non potrebbe contenere più di 100-200 colpi al massimo.', TRUE, '2026-09-16T10:32:34.330245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(445, 88, '00:09:40', 'Errori storici o fattuali', 'Gli elicotteri d''attacco sovietici presentati nel film come temibili Mi-24 Hind sono in realtà elicotteri di fabbricazione francese Aérospatiale SA 330 Puma, modificati con ali alari e finti lanciamissili. Poiché i velivoli militari sovietici reali erano inaccessibili per le produzioni hollywoodiane dell''epoca a causa della Guerra Fredda, si ricorse a questo camuffamento.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(446, 88, '00:15:25', 'Errori di scena / Posizione', 'Durante la sequenza iniziale del combattimento con i bastoni in Thailandia, le chiazze di sudore, sporcizia e sangue sul petto e sul volto di Rambo variano continuamente di forma, posizione e intensità tra i diversi stacchi di montaggio, rivelando che le riprese si sono svolte in giorni differenti.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(447, 88, '00:42:10', 'Troupe o microfoni visibili', 'Durante l''attacco aereo delle forze sovietiche al villaggio afghano, in una ripresa dall''alto che mostra una serie di esplosioni sul terreno, è chiaramente visibile per un istante nell''angolo inferiore sinistro dello schermo un membro della troupe cinematografica con una maglietta azzurra e un treppiede.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(448, 88, '01:08:15', 'Errori di scena / Posizione', 'Dopo che Rambo viene ferito da una scheggia al fianco, la posizione dello squarcio e la macchia di sangue sulla maglietta cambiano visibilmente: inizialmente la ferita sembra trovarsi quasi sulla schiena, ma nella famosa scena in cui Rambo estrae la scheggia e cauterizza la lesione con la polvere da sparo, la ferita si trova nettamente sulla parte anteriore destra dell''addome.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(449, 88, '01:21:50', 'Anacronismi', 'I carri armati impiegati dalle truppe sovietiche nella base non sono modelli russi originali (come i T-62 o T-72), bensì cacciacarri inglesi FV433 Abbot e carri statunitensi M41 Walker Bulldog ridipinti e camuffati con insegne sovietiche, veicoli incompatibili con l''esercito dell''URSS negli anni ''80.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3887, 158, '01:22:00', 'Troupe o microfoni visibili', 'Durante una delle sequenze d''azione in cui la Batmobile sfreccia per le strade di Gotham, in un''inquadratura ravvicinata del veicolo è possibile intravedere brevemente il riflesso della telecamera o di un operatore della troupe sulla carrozzeria lucida.', TRUE, '2026-11-02T10:09:02.233652', 'Batman Begins filming crew reflection Tumbler', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(451, 88, '01:39:40', 'Errori di scena / Posizione', 'Nel climax dello scontro finale, Rambo guida un carro armato scontrandosi frontalmente con l''elicottero del Colonnello Zaysen. Guardando la scena al rallentatore, la palla di fuoco dell''esplosione si innesca fra le cariche pirotecniche con un paio di fotogrammi di anticipo rispetto al reale impatto fisico tra la canna del carro e il muso del velivolo.', TRUE, '2026-09-16T10:34:41.919862', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(452, 87, '00:23:45', 'Errori di scena / Posizione', 'Durante il lancio col paracadute, l''imbracatura di Rambo si impiglia e il comandante Murdock ordina di tagliare i cavi. Rambo recide la cinghia perdendo la maggior parte dell''equipaggiamento pesante. Tuttavia, una volta a terra nella giungla, possiede ancora miracolosamente l''arco composito con tutte le frecce esplosive e la custodia completa.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(453, 87, '00:38:20', 'Anacronismi', 'Nelle apparecchiature di tracciamento visibili nella base americana di Murdock sono presenti schermi con grafica digitale avanzata e tecnologie di posizionamento ad alta risoluzione che risultano anacronistiche per l''epoca in cui è ambientata la vicenda.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(454, 87, '00:51:10', 'Errori storici o fattuali', 'Il temibile elicottero d''attacco sovietico identificato nel film come un Mil Mi-24 Hind è in realtà un elicottero di fabbricazione francese Aérospatiale SA 330 Puma, modificato in modo evidente con l''aggiunta di ali laterali e finti lanciamissili per simulare il velivolo russo.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(455, 87, '01:03:15', 'Errori di scena / Posizione', 'Durante la scena della tortura elettrica coordinata dal colonnello Podovsky, la posizione dei cavi con i morsetti applicati al corpo di Rambo cambia tra i primi piani e le inquadrature ampie. Inoltre, il cinturino in pelle sul suo polso destro appare ben affibbiato in una ripresa e completamente slacciato nel controcampo successivo.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(456, 87, '01:12:30', 'Troupe o microfoni visibili', 'Quando Rambo prende il controllo dell''elicottero UH-1 Huey dalla base nemica e aziona i comandi di decollo, sul vetro curvo del parabrezza si nota chiaramente il riflesso di un pannello riflettente della troupe e la sagoma del cameraman a bordo pista.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(457, 87, '01:18:05', 'Errori storici o fattuali', 'Rambo spara un colpo di lanciarazzi RPG-7 dall''interno dell''abitacolo chiuso dell''elicottero per distruggere il velivolo nemico. Nella realtà, la vampata posteriore (backblast) dell''arma all''interno di uno spazio ristretto avrebbe saturato la cabina di gas ad altissima temperatura, uccidendo gli occupanti e distruggendo la strumentazione.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(458, 87, '01:21:40', 'Errori di scena / Posizione', 'Nella scena in cui Rambo devasta la sala di comando di Murdock sparando con la mitragliatrice M60, il nastro delle munizioni inserito nell''arma cambia lunghezza in modo incoerente: passa dall''essere quasi terminato con pochissimi proiettili a essere nuovamente lungo fino a toccare il pavimento nel secondo successivo.', TRUE, '2026-09-16T10:41:21.384636', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(459, 86, '00:12:30', 'Errori di scena / Posizione', 'Durante la scena nella stazione di polizia, quando lo sceriffo Teasle e i suoi vice arrestano Rambo e lo ammanettano, i capelli del protagonista cambiano bruscamente posizione tra le diverse inquadrature: prima sono totalmente spettinati e cadono bagnati sulla fronte, mentre nel controcampo immediato risultano ordinati e pettinati all''indietro.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(460, 86, '00:23:15', 'Errori di scena / Posizione', 'Durante l''inseguimento in auto lungo la strada sterrata, quando la vettura dello sceriffo Teasle sbanda e si ribalta giù dal dirupo, si nota chiaramente la rampa di metallo montata artificialmente sotto il veicolo, usata dagli stuntman per far decollare e cappottare l''auto.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(461, 86, '00:35:40', 'Troupe o microfoni visibili', 'Nella famosa sequenza in cui Rambo si lancia dalla parete rocciosa per sfuggire ai colpi di fucile sparati dall''elicottero, in un fotogramma al rallentatore mentre sbatte contro i rami degli alberi è nettamente visibile il cavo di sicurezza in acciaio collegato all''imbracatura dello stuntman.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(462, 86, '00:48:10', 'Errori di scena / Posizione', 'Dopo che Rambo si ricuce la ferita al braccio con ago e filo improvvisati, la medicazione e la quantità di sangue presente sulla manica e sulla pelle variano continuamente nelle scene successive di caccia nella foresta, apparendo prima vistosamente insanguinata, poi quasi pulita e infine di nuovo coperta di sangue secco.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(463, 86, '01:06:50', 'Errori storici o fattuali', 'Quando Rambo si impossessa del camion militare e recupera la mitragliatrice M60, la quantità di proiettili sparati a raffica senza mai ricaricare o sostituire il nastro supera di gran lunga la capacità fisica effettivo del nastro di cartucce agganciato all''arma.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(464, 86, '01:18:25', 'Errori di scena / Posizione', 'Rambo fa esplodere la stazione di servizio per creare un diversivo in città. Subito dopo l''esplosione, il parabrezza del camion da lui guidato risulta visibilmente sfondato e ricoperto di fuliggine, ma nella sequenza immediatamente successiva in cui sfreccia lungo la via principale, il vetro appare intatto e pulito.', TRUE, '2026-09-16T10:45:07.709217', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(471, 86, '01:17:30', 'Anacronismi', 'All''interno del centralino della stazione di polizia di Hope, appare un modello di radio ricetrasmittente con display LED verde a sintesi di frequenza che non era ancora entrato in produzione nel periodo di ambientazione della pellicola.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(472, 86, '01:21:15', 'Errori storici o fattuali', 'Nella sequenza finale Rambo devasta la cittadina sparando con l''M60. Il nastro di munizioni calibro 7.62mm che porta a tracolla contiene visibilmente non più di 40-50 colpi, ma l''arma spara a raffica continua per decine di secondi senza che il nastro finisca o venga ricaricato.', TRUE, '2026-09-16T11:10:18.290089', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(483, 96, '00:58:04', 'Errori di scena / Posizione', 'Mentre i due personaggi fuggono dall''Entità nel Livello 1, le impronte di fango bagnato sulla moquette gialla scompaiono completamente nel campo controcampo quando la mdp inquadra i loro piedi da un''angolazione opposta.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(484, 96, '01:15:22', 'Troupe o microfoni visibili', 'Nella drammatica sequenza in cui la protagonista cerca di comunicare attraverso la parete, l''ombra del microfono a boom proiettata sulla carta da parati monotona è visibile nell''angolo superiore destro dell''inquadratura per circa tre secondi.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(482, 96, '00:41:12', 'Anacronismi', 'Nella scena ambientata nel 1996, un ricercatore della A-Async consulta un dispositivo di misurazione portatile sullo sfondo che mostra un display OLED a colori a matrice attiva con interfaccia USB-C, tecnologia del tutto inesistente all''epoca.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(481, 96, '00:24:30', 'Troupe o microfoni visibili', 'Durante la carrellata all''indietro lungo il corridoio infinito con le luci a fluorescenza, nella copertura di plastica dell''ottavo plafone sul soffitto si nota chiaramente il riflesso dell''operatore con la Steadycam.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(70, 30, '00:48:30', 'Crew & Equipment', 'Nell''angolo in alto a sinistra dell''inquadratura durante la galoppata di fuga, è chiaramente visibile l''ombra del microfono a giraffa e del braccio del fonico.', TRUE, '2026-09-13T15:08:13.445569', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(485, 96, '01:31:45', 'Errori storici o fattuali', 'Durante la spiegazione teorica del ''noclip'', il fisico fa riferimento all''ipotesi dei wormhole di Maldacena e alla corrispondenza AdS/CFT citando una pubblicazione del 1991, mentre in realtà il celebre articolo scientifico di Juan Maldacena è stato pubblicato solo alla fine del 1997.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(486, 96, '01:46:10', 'Errori di scena / Posizione', 'Il taglio profondo sulla spalla sinistra della giacca di jeans del protagonista cambia lato nella scena dell''ascensore, apparendo chiaramente sulla spalla destra per tutta la durata dell''inquadratura successiva.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(487, 98, '00:32:15', 'Anacronismi', 'Nelle scene in cui i soldati romani cavalcano scortando i prigionieri, si nota l''uso delle staffe agganciate alle selle. Le staffe per l''equitazione non furono introdotte nell''Impero Romano né in Europa prima di diversi secoli dopo l''epoca in cui è ambientata la vicenda.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(488, 98, '00:54:40', 'Errori di scena / Posizione', 'Quando Giuda Ben-Hur si trova al remo sulla galera romana durante l''ispezione di Quinto Arrio, la posizione delle catene ai suoi polsi e la disposizione dei suoi capelli bagnati sul viso cambia in modo incoerente nel passaggio dai primi piani ai campi medi.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(489, 98, '01:28:10', 'Anacronismi', 'Sulle bardature dei quattro cavalli bianchi dello Sceicco Ilderim è chiaramente mostrata la Stella di David. L''uso dell''esagramma come simbolo identitario religioso ebraico si è diffuso soltanto a partire dal Medioevo, risultando del tutto anacronistico per il I secolo d.C.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(490, 98, '02:12:05', 'Anacronismi', 'In diverse inquadrature ad angolo aperto durante la celebre corsa dei carri nell''arena di Gerusalemme, sul terreno sabbioso si possono notare le trincee e le nitide impronte di battistrada lasciate dagli pneumatici della camera car impiegata per le riprese dinamiche.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(491, 98, '02:24:35', 'Errori di scena / Posizione', 'Durante il duello ravvicinato tra il carro di Ben-Hur e quello di Messala, le micidiali lame dentate montate sui mozzi delle ruote del carro di Messala cambiano lunghezza, forma e stato di danneggiamento tra i controcampi consecutivi prima dell''impatto finale.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(492, 98, '02:35:50', 'Errori storici o fattuali', 'Nella drammatica scena nell''infermeria dopo l''incidente di Messala, il medico parla dell''imminente amputazione delle gambe del tribuno. Nel I secolo d.C. la chirurgia romana non eseguiva amputazioni di quel livello a causa della mancanza di emostatici e anestetici efficaci, che portava a morte certa per shock o emorragia prima del termine dell''intervento.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(493, 98, '03:18:20', 'Errori di scena / Posizione', 'Durante la sequenza della Crocifissione e del violento temporale finale, lo sporco di fango sul volto di Ben-Hur e il livello di inzuppamento delle sue vesti variano costantemente tra un''inquadratura in primo piano e il campo lungo successivo.', TRUE, '2026-09-16T12:03:22.545091', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(494, 102, '00:14:22', 'Anacronismi', 'Durante una delle inquadrature esterne nelle strade di Wisborg, sullo sfondo a sinistra è visibile un moderno pluviale di scolo in metallo zincato con giunzioni industriali, un dettaglio architettonico del tutto anacronistico per l''ambientazione del 1838.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(495, 102, '00:38:45', 'Errori di scena / Posizione', 'Durante la cena tra Thomas Hutter e il Conte Orlok nel castello, il livello del vino nel calice di Hutter cambia vistosamente tra i cambi di inquadratura. Nel piano medio il bicchiere è quasi vuoto, ma nel primo piano successivo risulta riempito a metà, senza che nessuno abbia versato altro liquido.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3888, 158, '00:45:00', 'Errori di scena / Posizione', 'Nella scena in cui Bruce Wayne si trova nel suo ufficio alla Wayne Enterprises e parla con i membri del consiglio d''amministrazione, i documenti sulla scrivania cambiano posizione e orientamento tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T10:09:02.233652', 'Batman Begins board meeting desk props continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(497, 102, '01:12:05', 'Troupe o microfoni visibili', 'Durante la sequenza ad alto contrasto nel corridoio buio in cui Ellen cammina con una candela, l''ombra della sagoma di una telecamera montata su gimbal e la punta di un microfono a giraffa vengono proiettate brevemente sulla parete di pietra a destra, a causa del posizionamento errato delle luci di scena.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(498, 102, '01:28:30', 'Errori di scena / Posizione', 'Quando la nave Empusa entra nel porto, la disposizione delle vele e delle sartiame cambia improvvisamente tra la ripresa aerea a distanza e l''inquadratura ravvicinata sul ponte. Alcune cime che prima erano visibilmente arrotolate e fissate appaiono improvvisamente sciolte e sparse sul ponte.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(499, 102, '01:45:15', 'Errori storici o fattuali', 'Il microscopio in ottone utilizzato per analizzare i campioni presenta un sistema di messa a fuoco micrometrica a slitta che fu brevettato e introdotto sul mercato solo diversi decenni dopo il 1838, rendendo lo strumento scientifico storicamente inaccurato per l''epoca.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(500, 102, '02:02:40', 'Errori di scena / Posizione', 'Nella drammatica scena finale nella camera da letto di Ellen, la posizione delle macchie di sangue sul colletto della sua camicia da notte cambia tra i tagli di montaggio: prima appaiono come due colate distinte sul lato sinistro, poi si fondono in un''unica grande macchia centrale nel primo piano successivo.', TRUE, '2026-09-16T12:05:02.470094', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(501, 100, '00:15:22', 'Errori di scena / Posizione', 'Durante il viaggio di Hutter verso il castello del Conte Orlok, la carrozza che lo trasporta cambia improvvisamente dettagli strutturali tra un''inquadratura e l''altra. In particolare, la disposizione delle lanterne esterne e la forma dei finimenti dei cavalli non coincidono nel passaggio dal campo lungo al piano medio.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(502, 100, '00:18:45', 'Troupe o microfoni visibili', 'Durante la sequenza della carrozza fantasma che corre verso il castello, nella parte inferiore destra dell''inquadratura è possibile scorgere per un breve istante l''ombra della cinepresa a manovella e dell''operatore (Fritz Arno Wagner) proiettata sui cespugli a bordo strada a causa dell''angolazione della luce solare.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3892, 160, '01:15:00', 'Errori di scena / Posizione', 'Durante la sequenza in cui la polizia di Gotham insegue il Tumbler rubato da Bane e dai suoi uomini per le strade della città, le targhe dei veicoli della polizia cambiano o scompaiono in alcune inquadrature dinamiche tra un primo piano e il campo largo.', TRUE, '2026-11-02T10:09:17.285944', 'The Dark Knight Rises police chase Tumbler continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(504, 100, '00:28:15', 'Errori di scena / Posizione', 'L''orologio del castello scocca la mezzanotte. Tuttavia, nell''inquadratura ravvicinata del quadrante dell''orologio ornamentale, le lancette non sono perfettamente allineate sulle ore 12:00, ma mostrano un''orario leggermente sfasato, nonostante il meccanismo a rintocchi sia in funzione.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(505, 100, '00:42:30', 'Errori di scena / Posizione', 'Nelle scene in cui Ellen attende Hutter sulle dune di sabbia, si nota una forte incongruenza nella direzione del vento. Tra un''inquadratura e l''altra, i capelli di Ellen e il suo scialle ondeggiano in direzioni opposte, rivelando che le riprese sono state effettuate in giorni diversi o con ventilatori di scena posizionati diversamente.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(506, 100, '00:45:12', 'Anacronismi', 'Il microscopio utilizzato dal Professor Sievers durante le sue lezioni per analizzare i polipi e le piante carnivore è un modello con fusto in ottone e regolazione micrometrica tipico della fine del XIX secolo (circa 1880-1890). Poiché il film è ambientato nel 1838, l''uso di questo specifico strumento scientifico rappresenta un anacronismo di circa cinquant''anni.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(507, 100, '01:02:05', 'Errori storici o fattuali', 'Quando le bare del Conte Orlok vengono aperte e ne fuoriescono i topi che diffonderanno la peste, si può chiaramente notare che gli animali utilizzati per la scena non sono ratti delle chiaviche (Rattus norvegicus), bensì porcellini d''India (cavie domestiche) a cui sono state applicate finte code, o ratti domestici addomesticati che si muovono in modo estremamente docile e innaturale per dei vettori selvatici di epidemie.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(508, 100, '01:12:40', 'Errori di scena / Posizione', 'Nella celebre sequenza in cui il Conte Orlok trasporta la propria bara attraverso le strade di Wisborg, la scena dovrebbe svolgersi nel cuore della notte o alle primissime luci dell''alba. Tuttavia, a causa delle riprese effettuate in pieno giorno (day-for-night), si proiettano sui muri degli edifici ombre cortissime, nette e intensamente definite, tipiche del sole di mezzogiorno.', TRUE, '2026-09-16T12:06:47.641971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(4263, 335, '00:42:10', 'Errori di scena / Posizione', 'Nel confronto tra Mort e John Shooter davanti alla cabina, i tagli di montaggio mostrano il cappello di Shooter posizionato in modo differente sulla sua testa tra i primi piani e i campi medi.', TRUE, '2026-11-02T14:50:53.821885', 'Secret Window Shooter hat continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(513, 103, '01:22:40', 'Errori di scena / Posizione', 'Nella scena all''interno della grotta dietro la cascata, i capelli di Cora Munro cambiano continuamente stato: sono completamente bagnati e appiccicati al viso in un''inquadratura, per poi apparire quasi asciutti, vaporosi e perfettamente acconciati nel controcampo successivo, per poi tornare bagnati subito dopo.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(514, 103, '01:31:10', 'Anacronismi', 'Durante l''inseguimento e la battaglia finale sulle scogliere, uno dei guerrieri uroni che corre sullo sfondo indossa chiaramente delle scarpe da ginnastica moderne di colore scuro con suola chiara in gomma, invece dei tradizionali mocassini di pelle dell''epoca.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(515, 103, '01:42:15', 'Errori di scena / Posizione', 'Nello scontro finale tra Chingachgook e Magua, Chingachgook colpisce Magua con la sua mazza da guerra sul lato sinistro del corpo. Tuttavia, nell''inquadratura successiva che mostra l''impatto e la reazione al dolore, Magua si tiene il fianco destro, e le ferite da taglio visibili sul suo corpo cambiano posizione tra i tagli di montaggio.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(516, 95, '00:14:32', 'Errori di scena / Posizione', 'Durante la scena in cui il personaggio di Cooper Koch affronta Charithra Chandran nella cucina, la tazza di caffè sul bancone cambia posizione tra i tagli di inquadratura: prima è vicina al bordo sinistro con il manico rivolto a destra, poi appare improvvisamente al centro del tavolo con il manico girato dall''altra parte.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(517, 95, '00:32:15', 'Troupe o microfoni visibili', 'Nella sequenza in cui la protagonista cammina frettolosamente lungo il corridoio del suo appartamento, si può chiaramente notare l''ombra del microfono a giraffa (boom mic) proiettata sulla parete bianca in alto a destra per circa tre secondi, mentre la telecamera indietreggia.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(518, 95, '00:48:50', 'Errori di scena / Posizione', 'Durante la drammatica telefonata sotto la pioggia, i capelli di Charithra Chandran appaiono completamente bagnati e incollati al viso nelle inquadrature ravvicinate, ma risultano quasi asciutti e in piega nei campi medi successivi, rivelando una mancata continuità tra i diversi ciak.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(519, 95, '01:05:12', 'Errori storici o fattuali', 'Quando Cooper Koch sblocca il suo smartphone per mostrare i messaggi, l''interfaccia del sistema operativo mostra l''orario ''14:30'', ma nella scena immediatamente precedente e in quella successiva gli orologi da parete nella stanza e la luce solare esterna indicano chiaramente che si tratta di notte fonda.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(520, 95, '01:18:45', 'Troupe o microfoni visibili', 'Nella scena del confronto nel soggiorno, quando la telecamera compie un movimento circolare attorno ai due attori, sul vetro della finestra sullo sfondo si riflette nitidamente la sagoma di un operatore di ripresa che indossa una maglietta scura.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(521, 95, '01:29:05', 'Errori di scena / Posizione', 'Durante la colluttazione fisica sul pavimento, la ferita da taglio sulla guancia sinistra del personaggio di Cooper Koch sanguina vistosamente. Tuttavia, nell''inquadratura successiva da dietro la sua spalla, la guancia appare pulita e priva di sangue, per poi tornare a sanguinare nel primo piano finale.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(522, 95, '01:35:22', 'Anacronismi', 'Nonostante il film sia ambientato nel 2026, in una scena di flashback che la didascalia dichiara essere ambientata ''dieci anni prima'' (quindi nel 2016), si vede chiaramente sullo sfondo un cartellone pubblicitario di un modello di auto elettrica commercializzato solo a partire dal 2023.', TRUE, '2026-09-16T16:09:24.728092', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(523, 104, '00:14:22', 'Errori di scena / Posizione', 'Durante il primo incontro nell''ufficio di Kevin (Will Forte) con Wile E. Coyote, la pila di cataloghi della Acme Corporation sulla scrivania cambia disposizione tra le inquadrature. Nel piano medio il catalogo del 1996 è in cima, ma nel primo piano successivo si vede chiaramente l''edizione del 2004, per poi ritornare a quella del 1996 nell''inquadratura larga.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3889, 159, '01:22:00', 'Troupe o microfoni visibili', 'Durante la sequenza in cui il camion guidato dal Joker viene ribaltato da Batman con la Batpod, in alcune inquadrature ad altezza strada è possibile intravedere brevemente l''ombra della telecamera o dell''operatore sull''asfalto o sul fianco del veicolo in movimento.', TRUE, '2026-11-02T10:09:10.32456', 'The Dark Knight truck flip camera shadow', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(1023, 231, '00:58:15', 'Errori di scena / Posizione', 'Durante la sequenza delle trappole nello scantinato, la posizione e l''altezza del barattolo sospeso cambiano visibilmente tra il totale dell''ambiente e il primo piano del ladro che cerca di schivarlo.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(525, 104, '00:48:10', 'Errori storici o fattuali', 'Nella sequenza di flashback che illustra l''incidente dei pattini a razzo Acme, datata esplicitamente ''Ottobre 1982'', sulla scatola del prodotto è stampato un codice a barre QR e l''indirizzo web ''www.acme-corp.com/warning''. Nel 1982 né i codici QR né il World Wide Web erano ancora stati inventati o commercializzati.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(526, 104, '00:55:12', 'Troupe o microfoni visibili', 'Nella scena all''aperto nel deserto in cui Kevin parla con Wile E. Coyote vicino a un cartellone pubblicitario, l''ombra di una gru cinematografica con relativa telecamera è chiaramente visibile sulla sabbia nell''angolo inferiore destro dello schermo durante un movimento di camera a scendere.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(527, 104, '01:02:15', 'Errori di scena / Posizione', 'Mentre il personaggio di Lana Condor esamina i progetti del magnete gigante Acme, tiene una penna rossa nella mano destra. Nell''inquadratura ravvicinata sul progetto, la mano stringe improvvisamente un evidenziatore blu, per poi tornare a mostrare la penna rossa nel controcampo successivo.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3890, 159, '00:35:00', 'Errori di scena / Posizione', 'Nella scena in cui il Joker irrompe alla festa di Bruce Wayne, minaccia Rachel Dawes e poi la lascia cadere dal balcone, la posizione dei capelli di Rachel e il modo in cui ha le mani legate o tese cambiano repentinamente tra il campo medio e il primo piano.', TRUE, '2026-11-02T10:09:10.32456', 'The Dark Knight Joker party scene Rachel mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(529, 104, '01:29:05', 'Errori di scena / Posizione', 'Durante la dimostrazione finale in aula con la fionda gigante Acme, la fasciatura sull''orecchio di Wile E. Coyote cambia lato. Nelle inquadrature frontali la benda è posizionata sull''orecchio sinistro, mentre nei raccordi da dietro (alle spalle della giuria) la fasciatura appare sull''orecchio destro.', TRUE, '2026-09-16T16:28:52.963282', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(530, 104, '00:14:22', 'Errori di scena / Posizione', 'Durante la scena nell''ufficio dell''avvocato Kevin Clay, quando Wile E. Coyote mostra i faldoni dei brevetti difettosi ACME, la pila di documenti sul tavolo cambia altezza e disposizione tra i cambi di inquadratura. Inizialmente ci sono tre raccoglitori blu in cima, che diventano due rossi nel primo piano successivo.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(550, 109, '01:19:40', 'Errori di scena / Posizione', 'Durante la folle corsa a bordo del fuoristrada Land Rover attraverso la vegetazione, il veicolo subisce gravi danni al parabrezza e alla carrozzeria laterale dopo un ribaltamento. Nell''inquadratura immediatamente successiva, il parabrezza torna ad essere intatto e privo di crepe.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(531, 104, '00:22:10', 'Anacronismi', 'Sullo sfondo dell''ufficio postale da cui Wile E. Coyote ritira i pacchi ACME, è visibile un poster promozionale del servizio postale statunitense (USPS) che mostra il logo moderno introdotto solo nel 1993, nonostante la scena cerchi di ricreare un''atmosfera vintage da ufficio postale rurale degli anni ''70/''80 con vecchi schedari e arredi d''epoca.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(532, 104, '00:32:15', 'Errori storici o fattuali', 'Nella scena del tribunale, viene citato il ''Federal Tort Claims Act'' come base legale per la giurisdizione contro una multinazionale privata come la ACME Corporation. Tuttavia, tale legge si applica esclusivamente alle richieste di risarcimento danni contro il governo federale degli Stati Uniti, non contro entità commerciali private.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(533, 104, '00:45:10', 'Troupe o microfoni visibili', 'Durante l''inseguimento nel deserto del New Mexico, quando la telecamera esegue una panoramica rapida dal basso verso l''alto per seguire il volo di un razzo ACME difettoso, nell''angolo inferiore destro dello schermo è visibile per pochi fotogrammi l''ombra del braccio meccanico della telecamera (technocrane) riflessa sulla superficie lucida di una roccia.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(534, 104, '00:58:35', 'Anacronismi', 'Nella sequenza flashback ambientata negli anni ''60 che mostra la fondazione di una delle sussidiarie della ACME, si vede un personaggio utilizzare una calcolatrice scientifica tascabile a cristalli liquidi (LCD). Le calcolatrici LCD commerciali non sono apparse sul mercato prima della metà degli anni ''70.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(535, 104, '01:03:18', 'Troupe o microfoni visibili', 'Nella scena in cui l''avvocato difensore della ACME cammina lungo il corridoio del tribunale parlando ai giornalisti, si può notare nella riflessione delle porte a vetri sullo sfondo la sagoma di un fonico di linea che regge un microfono a giraffa (boom mic), parzialmente coperto da un pannello riflettente.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3891, 159, '02:15:00', 'Errori di scena / Posizione', 'Nel finale sul cantiere del grattacielo in costruzione, quando Batman appende il Joker a testa in giù, la posizione del cappotto del Joker e il modo in cui penzola variano visibilmente da un''inquadratura all''altra.', TRUE, '2026-11-02T10:09:10.32456', 'The Dark Knight Batman and Joker final fight building', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(537, 104, '01:21:40', 'Errori storici o fattuali', 'Nel cartello stradale visibile sullo sfondo durante la scena del viaggio verso il quartier generale della ACME, viene indicata la distanza per Albuquerque in ''chilometri'' anziché in ''miglia''. Trattandosi di una strada statale del New Mexico (USA), la segnaletica ufficiale utilizza esclusivamente il sistema imperiale.', TRUE, '2026-09-16T16:46:40.944956', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(538, 108, '00:14:32', 'Errori di scena / Posizione', 'Durante la discussione in cucina tra il personaggio interpretato da Anne Hathaway e quello di Ewan McGregor, il bicchiere d''acqua sul tavolo passa dall''essere quasi vuoto nel campo largo a essere completamente pieno nel controcampo, senza che nessuno si sia avvicinato alla caraffa.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(539, 108, '00:32:15', 'Troupe o microfoni visibili', 'Nella scena notturna in cui la macchina da presa compie una rapida panoramica lungo il porticato della casa su Oak Street, sul vetro laterale del SUV scuro parcheggiato nel vialetto si nota chiaramente il riflesso del fonico con il microfono panoramico (boom).', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(540, 108, '00:54:10', 'Errori storici o fattuali', 'Quando il personaggio di Ewan McGregor analizza il tracciato delle frequenze al computer, l''interfaccia mostra un sistema di coordinate geografiche con valori di latitudine superiori a 90 gradi (94° 12'' N), un errore concettuale impossibile per qualsiasi sistema di navigazione reale.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(704, 63, '00:35:10', 'Anacronismi', 'Nella sala del banchetto del castello, la struttura degli archi gotici e i dettagli delle vetrate mostrano elementi stilistici tipici del XIV secolo, anacronistici per l''ambientazione storica della Terza Crociata (1190 circa).', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(541, 108, '01:12:45', 'Errori di scena / Posizione', 'Mentre Anne Hathaway corre verso il garage per aprirne la basculante, la sua giacca di pelle è completamente chiusa fino al collo. Nell''inquadratura immediatamente successiva dall''interno del garage, la giacca è completamente sbottonata ed aperta.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(543, 108, '01:51:22', 'Troupe o microfoni visibili', 'Durante il momento di massima tensione lungo il viale alberato, l''inquadratura dall''alto verso il basso rivela l''ombra proiettata sull''asfalto della camera rig con lo stabilizzatore e l''operatore che segue gli attori.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(544, 108, '02:08:40', 'Errori di scena / Posizione', 'Dopo il ferimento nello scontro finale, il personaggio di Anne Hathaway presenta un evidente taglio insanguinato sulla guancia sinistra. Nella scena successiva all''interno dell''ambulanza, la medicazione e la ferita si trovano sulla guancia destra.', TRUE, '2026-09-17T11:16:35.811481', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(545, 109, '00:04:15', 'Errori di scena / Posizione', 'Nella sequenza d''apertura sulle montagne dell''Himalaya, quando Ace tenta disperatamente di salvare il procione sospeso nel vuoto, la quantità di neve fresca accumulata sulle sue spalle e sul collo del giubbotto varia costantemente ad ogni cambio di inquadratura tra i primi piani e i campi larghi.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(546, 109, '00:22:10', 'Troupe o microfoni visibili', 'Durante il ricevimento formale alla residenza del console Vincent Cadby, mentre Ace si muove tra gli ospiti infastidendo l''uomo vestito da mascotte del Monopoly, nella parte superiore dell''inquadratura è visibile l''ombra del microfono a giraffa (boom mic) rifratta sulla parete dello sfondo.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(547, 109, '00:38:45', 'Errori di scena / Posizione', 'Durante la prova di coraggio al villaggio Wachati, Ace viene colpito alle cosce da due freccette avvelenate sparate con una cerbottana. L''inclinazione e la distanza reciproca delle due freccette piantate sulle sue gambe cambiano nettamente quando la ripresa passa dal primo piano alla visuale frontale mentre prova a camminare.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(548, 109, '00:52:30', 'Errori di scena / Posizione', 'Nella celebre scena in cui Ace rimane bloccato all''interno del rinoceronte meccanico ed è costretto a uscire dal posteriore dell''animale, la quantità di sostanza vischiosa e sudore artificiale sul suo viso e sul corpo varia visibilmente tra il momento del contorcimento interno e l''uscita completa sul terreno.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(549, 109, '01:08:15', 'Errori storici o fattuali', 'Nel santuario degli animali e nelle aree circostanti della giungla africana compaiono diverse specie animali completamente estranee alla fauna del continente africano, tra cui capibara e ara macao, tipici invece dell''America meridionale.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(4820, 90, '00:15:30', 'Errori di scena / Posizione', 'Durante la conversazione tra Rambo e Maria alla cucina del ranch, la tazza di caffè tenuta da Maria cambia mano e livello di riempimento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:40:24.467847', 'Rambo Last Blood kitchen scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(551, 109, '01:25:50', 'Anacronismi', 'Durante lo scontro finale tra le tribù Wachati e Wachootoo, viene impiegato un dispositivo di proiezione di diapositive perfettamente funzionante e ad alta luminosità nel mezzo della giungla incontaminata, in assenza totale di qualsiasi generatore o fonte di alimentazione elettrica visibile.', TRUE, '2026-09-17T12:48:04.037056', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(552, 110, '00:15:30', 'Anacronismi', 'L''uso del kilt (philibeg o belted plaid) da parte di William Wallace e dei clan scozzesi è un evidente anacronismo. Questo tipo di abbigliamento fu introdotto in Scozia solo a partire dal XVI-XVII secolo, mentre le vicende del film si svolgono alla fine del XIII secolo (circa 1297). All''epoca i guerrieri scozzesi indossavano tuniche gialle zafferano (leine) o semplici camicie di lana e armature di cuoio.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(553, 110, '01:08:15', 'Errori storici o fattuali', 'La celebre ''Battaglia di Stirling Bridge'' viene combattuta nel film su una vasta pianura erbosa senza che si veda alcuna traccia del ponte (''bridge'') che dà il nome allo scontro. Storicamente, il ponte di legno fu l''elemento tattico cruciale che permise agli scozzesi di intrappolare e sconfiggere l''esercito inglese che lo stava attraversando. Il regista Mel Gibson decise di escluderlo per facilitare le riprese delle cariche di cavalleria.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(554, 110, '01:11:50', 'Errori di scena / Posizione', 'Durante lo scontro ravvicinato a Stirling, quando un soldato scozzese colpisce un cavaliere inglese con un''ascia da battaglia, l''arma si piega visibilmente in modo innaturale come se fosse di gomma flessibile, rivelando la natura di ''prop'' di sicurezza utilizzato dagli stuntman per evitare infortuni sul set.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(555, 110, '01:14:05', 'Errori di scena / Posizione', 'Durante i vari tagli di inquadratura della battaglia di Stirling, la pittura facciale blu (woad) sul volto di William Wallace cambia continuamente forma, densità e livello di sbavatura. In alcune inquadrature ravvicinate copre perfettamente metà del viso, mentre in quelle immediatamente successive appare sbiadita o con pattern leggermente diversi, rivelando molteplici sessioni di trucco tra i ciak.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(556, 110, '01:22:10', 'Errori storici o fattuali', 'La principessa Isabella di Francia, interpretata da Sophie Marceau, viene mostrata come una donna adulta che ha una relazione romantica con William Wallace. Nella realtà storica, all''epoca della battaglia di Falkirk (1298), Isabella aveva circa tre anni e viveva in Francia. Sposò Edoardo II solo nel 1308, tre anni dopo la morte di Wallace, rendendo la loro storia d''amore e la gravidanza di lei storicamente impossibili.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(557, 110, '01:28:45', 'Troupe o microfoni visibili', 'Durante la concitata sequenza della battaglia di Stirling, sullo sfondo dietro i cavalieri inglesi in carica, è possibile scorgere per una frazione di secondo un veicolo moderno di colore bianco (un furgone o un''automobile della troupe) parcheggiato tra gli alberi.', TRUE, '2026-09-17T13:04:39.959953', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3893, 164, '01:25:00', 'Errori storici o fattuali', 'Durante il film viene citata e rappresentata la pratica di bruciare una chiesa con i civili dentro da parte delle truppe britanniche. Questo evento è ispirato ai crimini nazisti di Oradour-sur-Glane durante la seconda guerra mondiale, ma non esiste alcuna documentazione storica che attesti un simile crimine di guerra commesso dall''esercito britannico durante la guerra d''indipendenza americana.', TRUE, '2026-11-02T10:10:09.766275', 'The Patriot church scene history error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(559, 112, '00:04:15', 'Errori di scena / Posizione', 'Durante la sequenza dell''incidente d''auto iniziale, il telefono cellulare di Michelle vola via dal cruscotto. Nei fotogrammi successivi, la posizione del telefono sul tappetino e lo stato dello schermo (che passa da crepato a completamente integro tra un''inquadratura e l''altra) mostrano una chiara discrepanza di montaggio.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(66, 27, '00:58:20', 'Crew & Equipment', 'Sulle corazze metalliche e lucide dei soldati romani si rispecchiano le luci dei riflettori del set cinematografico.', TRUE, '2026-09-13T15:01:46.488694', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(560, 112, '00:09:30', 'Errori di scena / Posizione', 'Quando Michelle si sveglia per la prima volta incatenata al muro del bunker, la flebo inserita nel suo braccio cambia posizione. Nelle inquadrature ravvicinate l''ago è fissato con un cerotto bianco inclinato, mentre nei campi medi il cerotto è dritto e posizionato più in alto sul braccio.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(561, 112, '00:15:45', 'Errori storici o fattuali', 'Howard mostra a Michelle che non c''è segnale cellulare nel bunker sotterraneo a causa della profondità e della schermatura in cemento armato. Tuttavia, poco dopo, quando Michelle tenta di usare il telefono vicino alla botola, riceve brevemente una notifica di rete. Fisicamente, una schermatura del genere bloccherebbe completamente qualsiasi ponte radio senza ripetitori interni, rendendo impossibile anche una ricezione intermittente a quella profondità.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(562, 112, '00:28:40', 'Errori di scena / Posizione', 'La ferita sul lato sinistro della fronte di Michelle, causata dall''incidente stradale, cambia costantemente aspetto. In alcune scene all''interno del bunker appare come un taglio profondo e sanguinante, mentre in altre sequenze ambientate nello stesso giorno appare già quasi completamente cicatrizzata e di dimensioni ridotte, per poi tornare vistosa successivamente.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(616, 117, '01:42:30', 'Errori di scena / Posizione', 'Durante la recita teatrale di Neil Perry nel ruolo di Puck, la corona di rami e foglie che porta sul capo cambia inclinazione e altezza sulla fronte tra i primi piani stretti e le inquadrature più larghe sul palco.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(563, 112, '00:42:10', 'Errori di scena / Posizione', 'Durante la scena in cui Michelle, Howard ed Emmett giocano a un gioco da tavolo e completano un puzzle, la disposizione dei pezzi sul tavolo cambia drasticamente tra i cambi di inquadratura. In un fotogramma il puzzle è quasi completato sul lato sinistro, mentre nell''inquadratura successiva i pezzi sono sparsi in modo diverso.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(564, 112, '00:55:18', 'Troupe o microfoni visibili', 'Nella scena in cui Michelle sale sulla sedia per raggiungere il condotto dell''aria, sul riflesso della superficie metallica lucida del pannello di ventilazione adiacente è possibile scorgere per un breve istante la sagoma di un operatore della troupe con una telecamera e parte del pannello riflettente utilizzato per l''illuminazione.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(565, 112, '01:18:30', 'Errori storici o fattuali', 'La tuta protettiva improvvisata che Michelle costruisce usando una tenda da doccia, nastro adesivo e una bottiglia di plastica non potrebbe mai garantire una tenuta stagna contro gas tossici o agenti biologici. Inoltre, il filtro creato con la bottiglia non presenta alcuna valvola di espirazione o materiale filtrante attivo (come il carbone attivo), rendendo la respirazione impossibile o del tutto inefficace contro l''atmosfera contaminata descritta.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(566, 112, '01:32:15', 'Errori di scena / Posizione', 'Durante lo scontro finale con la nave aliena, Michelle lancia una bottiglia incendiaria improvvisata nella bocca della creatura/astronave. Tra l''inquadratura del lancio e quella dell''esplosione, la distanza tra Michelle e il veicolo alieno raddoppia inspiegabilmente, e la posizione del camion dietro cui si nasconde cambia orientamento rispetto alla traiettoria d''attacco dell''alieno.', TRUE, '2026-09-17T16:01:00.029488', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(567, 114, '00:02:15', 'Errori storici o fattuali', 'All''inizio del film, Drugo (The Dude) compila un assegno da 69 centesimi datato 11 settembre 1991. Sullo sfondo, la televisione trasmette il celebre discorso di George H.W. Bush ''This will not stand'' riguardo all''invasione del Kuwait. Tuttavia, quel discorso televisivo è stato pronunciato storicamente il 5 agosto 1990, creando un''incongruenza temporale di oltre un anno rispetto alla data dell''assegno.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(568, 114, '00:11:15', 'Errori di scena / Posizione', 'Nella scena in cui Bunny Lebowski mostra i suoi piedi con lo smalto verde a Drugo vicino alla piscina, la posizione delle sue gambe e l''asciugamano su cui è sdraiata cambiano visibilmente tra le inquadrature strette e quelle larghe, rivelando una discontinuità nella postura dell''attrice Tara Reid durante le diverse riprese.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(569, 114, '00:15:40', 'Anacronismi', 'Sebbene il film sia ambientato esplicitamente nel 1991, all''interno della sala da bowling si possono notare in diverse scene dei monitor per il punteggio automatico e dei loghi commerciali della Brunswick che sono stati introdotti sul mercato solo a metà degli anni ''90, diversi anni dopo il periodo in cui si svolge la narrazione.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(570, 114, '00:42:10', 'Errori di scena / Posizione', 'Durante la fallimentare consegna del riscatto, Walter lancia la borsa civetta fuori dal finestrino della Ford Torino di Drugo. Nelle inquadrature dall''interno dell''auto il finestrino del passeggero è chiaramente spalancato per permettere il lancio, ma nell''inquadratura esterna immediatamente successiva, un attimo prima del lancio, il vetro appare completamente sollevato.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(571, 114, '00:51:30', 'Troupe o microfoni visibili', 'Nella celebre sequenza in cui Drugo cerca di spegnere lo spinello che gli è caduto sul cavallo dei pantaloni e finisce per schiantarsi contro un cassonetto, per una frazione di secondo sul riflesso del finestrino laterale sinistro della Ford Torino è possibile scorgere la sagoma della telecamera montata sul braccio mobile (camera rig) e di un operatore della troupe posizionato a bordo strada.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(572, 114, '00:56:45', 'Errori di scena / Posizione', 'Durante il primo incontro ravvicinato tra Drugo e Maude Lebowski nel suo studio d''arte, il livello del White Russian nel bicchiere di Drugo oscilla vistosamente. Il bicchiere passa dall''essere quasi vuoto a essere nuovamente pieno a metà tra un controcampo e l''altro, senza che Drugo abbia avuto il tempo materiale di versare altro latte o liquore.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(573, 114, '01:18:25', 'Errori di scena / Posizione', 'Quando Walter distrugge a colpi di mazzetta la Corvette rossa credendo appartenga al giovane Larry Sellers, i danni sul parabrezza e sulla carrozzeria cambiano configurazione tra i primi piani e i campi medi. Inoltre, il sistema di allarme dell''auto inizia a suonare una frazione di secondo prima che la mazzetta di Walter colpisca effettivamente il cofano per la prima volta.', TRUE, '2026-09-17T16:07:04.999935', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(705, 63, '00:52:15', 'Troupe o microfoni visibili', 'Nella sequenza dell''agguato nella foresta di Sherwood, mentre Douglas Fairbanks esegue un''acrobazia arrampicandosi rapidamente su un grande albero, è chiaramente visibile il cavo di sicurezza in metallo teso sopra di lui.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(574, 111, '00:22:30', 'Errori di scena / Posizione', 'All''inizio del film, quando Rose osserva il Titanic dal molo prima di imbarcarsi, il neo sulla sua guancia è chiaramente visibile sul lato sinistro del viso. Tuttavia, in diverse inquadrature successive all''interno della nave, il neo appare sul lato destro. Questo è dovuto al fatto che alcune inquadrature sono state specchiate in post-produzione per esigenze di montaggio e composizione visiva.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(575, 111, '00:48:15', 'Anacronismi', 'Jack racconta a Rose di essere andato a pescare con suo padre sul lago Wissota, nel Wisconsin. Tuttavia, il lago Wissota è un bacino artificiale creato dalla costruzione di una diga, i cui lavori sono iniziati nel 1915 e completati nel 1917, ovvero diversi anni dopo il naufragio del Titanic avvenuto nell''aprile del 1912.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(576, 111, '00:55:10', 'Troupe o microfoni visibili', 'Quando Jack, indossando l''abito da sera elegante, fa il suo ingresso nel salone di prima classe per partecipare alla cena formale, il riflesso di una telecamera di ripresa e di un membro della troupe è chiaramente visibile sulla superficie di vetro scuro e lucido di una delle porte che vengono aperte per accoglierlo.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(577, 111, '01:15:35', 'Errori di scena / Posizione', 'Durante la celebre scena del ritratto in cui Rose posa per Jack, la punta della matita a carboncino di Jack si spezza visibilmente con un rumore netto mentre traccia una linea d''ombra. Nell''inquadratura immediatamente successiva, senza che il ragazzo abbia il tempo di temperarla o sostituirla, la punta della matita torna a essere perfettamente integra e affilata.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(578, 111, '01:21:40', 'Anacronismi', 'Jack promette a Rose che la porterà sulle montagne russe del molo di Santa Monica, dove saliranno fino a farsi venire la nausea. Tuttavia, il parco divertimenti sul molo di Santa Monica e le sue famose montagne russe non furono costruiti e aperti al pubblico prima del 1916, rendendo questo dialogo storicamente incoerente con l''anno 1912.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(579, 111, '02:12:05', 'Errori di scena / Posizione', 'Nella scena in cui Rose cerca di liberare Jack dalle manette nei corridoi allagati, decide di usare una scure d''emergenza. Quando colpisce il vetro della bacheca protettiva, lo manda completamente in frantumi liberando la cornice. Nell''inquadratura successiva, mentre infila la mano per afferrare la scure, gran parte dei frammenti di vetro è riapparsa miracolosamente incastrata nei bordi della bacheca.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(580, 111, '02:46:30', 'Errori storici o fattuali', 'Mentre Rose fluttua sulla porta di legno nell''oceano gelido e guarda verso l''alto in attesa dei soccorsi, la volta celeste mostra una disposizione delle stelle del tutto casuale e simmetrica. Come evidenziato dall''astrofisico Neil deGrasse Tyson, la mappa stellare mostrata è scientificamente errata e non corrisponde al vero cielo notturno visibile nel Nord Atlantico il 15 aprile 1912 alle ore 04:20.', TRUE, '2026-09-17T16:13:06.376545', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(683, 111, '00:58:20', 'Troupe o microfoni visibili', 'Mentre Jack e Rose fuggono ridendo lungo i corridoi della prima classe per scappare dal maggiordomo Lovejoy, l''ombra della telecamera e dell''operatore che si muove su un carrello è chiaramente visibile per una frazione di secondo sulle superfici di legno lucido delle porte e sui pannelli dorati della parete di destra.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(684, 111, '01:02:15', 'Errori di scena / Posizione', 'Durante la scena sul ponte di comando in cui al Capitano Smith viene servita una tazza di tè, lo si vede chiaramente girare lo zucchero con un cucchiaino. Nell''inquadratura immediatamente successiva, il cucchiaino scompare del tutto sia dalla tazza che dal piattino, e le mani del capitano si trovano in una posizione completamente diversa senza che ci sia stato il tempo fisico per posarlo.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3894, 164, '01:05:00', 'Errori di scena / Posizione', 'Nella scena in cui Gabriel Martin legge una lettera, la posizione del foglio e il modo in cui lo tiene in mano cambiano visivamente e repentinamente tra le inquadrature in primo piano e quelle a figura intera.', TRUE, '2026-11-02T10:10:09.766275', 'The Patriot Gabriel letter scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3895, 164, '02:15:00', 'Errori storici o fattuali', 'Le armi da fuoco utilizzate dai miliziani e dai soldati britannici mostrano una precisione e una velocità di ricarica irrealistiche per i normali fucili a avancarica a pietra focaia (moschetti Brown Bess e Pennsylvania/Kentucky rifles) dell''epoca.', TRUE, '2026-11-02T10:10:09.766275', 'The Patriot muskets accuracy historical error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(687, 111, '02:40:15', 'Errori di scena / Posizione', 'Quando la poppa del Titanic si solleva quasi verticalmente prima del collasso finale, Jack e Rose si aggrappano alla ringhiera di sicurezza. La distanza tra i montanti metallici della ringhiera varia vistosamente: nelle inquadrature ravvicinate i montanti sono molto distanziati per permettere agli attori di posizionarsi, mentre nei campi lunghi digitali la ringhiera appare molto più fitta e con dettagli geometrici differenti.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(688, 111, '02:51:10', 'Anacronismi', 'Durante le drammatiche ricerche dei superstiti nell''acqua gelida, l''ufficiale Harold Lowe e i marinai utilizzano delle torce elettriche portatili che emettono un fascio di luce bianca estremamente potente, nitido e focalizzato, tipico delle moderne lampadine alogene o a LED. Nel 1912, le torce elettriche erano dispositivi rudimentali che emettevano una luce giallastra, fioca e diffusa, e le cui batterie al carbonio-zinco si esaurivano nel giro di pochissimi minuti.', TRUE, '2026-09-21T20:46:10.325971', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(581, 115, '00:21:15', 'Errori di scena / Posizione', 'Nella scena dell''appartamento di Brett, quando il quarto uomo esce improvvisamente dal bagno sparando all''impazzata contro Jules e Vincent, i fori dei proiettili sulla parete alle spalle dei due protagonisti sono chiaramente visibili ancor prima che l''uomo inizi a sparare.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(582, 115, '00:36:45', 'Errori di scena / Posizione', 'Durante la cena al Jack Rabbit Slim''s, la sigaretta di Mia Wallace (Uma Thurman) cambia continuamente mano e lunghezza tra un''inquadratura e l''altra. In alcuni stacchi ravvicinati è quasi consumata, mentre nel totale successivo appare molto più lunga.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(583, 115, '00:47:30', 'Errori di scena / Posizione', 'Nella drammatica scena dell''overdose, Vincent traccia un punto rosso con un pennarello sul petto di Mia per mirare con la siringa di adrenalina. Nell''inquadratura immediatamente successiva, ravvicinata sul petto prima dell''iniezione, il segno rosso scompare completamente, per poi riapparire diverso subito dopo.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(584, 115, '01:11:40', 'Anacronismi', 'Durante la fuga di Butch in taxi dopo l''incontro di boxe, lo sfondo visibile oltre i finestrini della vettura guidata da Esmeralda Villalobos è una proiezione in bianco e nero che mostra automobili e strade degli anni ''40 e ''50, creando un evidente anacronismo con l''ambientazione anni ''90 del film.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(585, 115, '01:24:30', 'Troupe o microfoni visibili', 'Quando Butch è fermo al semaforo a bordo della Honda Civic bianca e nota Marsellus Wallace attraversare la strada con i cartoni della colazione, nel riflesso del finestrino laterale dell''auto è chiaramente visibile la sagoma della cinepresa e di un operatore della troupe.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(4264, 335, '01:05:40', 'Troupe o microfoni visibili', 'Durante la sequenza in cui Mort cammina concitato vicino al lago, in un riflesso sui vetri della portiera dell''auto è brevemente visibile l''ombra di un operatore della troupe con l''attrezzatura.', TRUE, '2026-11-02T14:50:53.821885', 'Secret Window crew reflection error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(587, 115, '01:46:20', 'Errori di scena / Posizione', 'Durante la gestione dell''emergenza a casa di Jimmie, l''orologio da cucina mostra un''incongruenza temporale. Mentre Winston Wolf dichiara che mancano pochissimi minuti all''arrivo di Bonnie (previsto per le 09:30) e la tensione sale, l''orologio da parete sullo sfondo mostra le 08:15 in un''inquadratura e le 07:40 in quella successiva.', TRUE, '2026-09-17T17:53:41.748245', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(588, 115, '00:41:15', 'Errori di scena / Posizione', 'Nella celebre scena dell''appartamento di Brett, prima ancora che il quarto uomo esca dal bagno sparando all''impazzata contro Jules e Vincent, i fori dei proiettili sono già chiaramente visibili sulla parete alle spalle dei due protagonisti.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(589, 115, '00:47:30', 'Errori di scena / Posizione', 'Prima di somministrare l''iniezione di adrenalina a Mia in overdose, Vincent traccia un cerchio rosso con un pennarello sul petto della donna per mirare al cuore. Subito dopo la miracolosa rianimazione, quando Mia si rialza ansimando, il segno rosso sul petto è completamente scomparso.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(590, 115, '01:22:10', 'Troupe o microfoni visibili', 'Durante la drammatica scena nel seminterrato del banco dei pegni, quando Butch e Marsellus sono tenuti prigionieri, è possibile scorgere il riflesso di un operatore di ripresa con la telecamera sulla superficie lucida di una delle vetrinette sullo sfondo.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(661, 129, '01:12:10', 'Errori di scena / Posizione', 'Nella scena in cui Noodles deposita la valigia con i soldi nella cassetta di sicurezza della stazione ferroviaria, la valigia viene inserita in un determinato senso. Nell''inquadratura successiva, quando la serratura viene chiusa, la valigia appare ruotata di 180 gradi, con la maniglia rivolta verso il lato opposto.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(592, 115, '01:52:40', 'Errori storici o fattuali', 'Winston Wolfe dichiara che arriverà a casa di Jimmie in 9 minuti e 37 secondi, guidando la sua Acura NSX ad altissima velocità. Tuttavia, considerando la distanza geografica reale tra la sua posizione iniziale (un hotel a Los Angeles) e la fittizia casa di Jimmie a Toluca Lake, compiere quel tragitto in quel lasso di tempo di mattina presto sarebbe fisicamente impossibile a causa del traffico e dei limiti fisici del percorso stradale urbano.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(593, 115, '00:37:15', 'Errori di scena / Posizione', 'Al locale Jack Rabbit Slim''s, quando Mia Wallace ordina il famoso frappè da 5 dollari (''Martin and Lewis''), il livello del liquido nel bicchiere sale e scende vistosamente tra un''inquadratura e l''altra, prima ancora che lei inizi a berlo con la cannuccia.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(594, 115, '01:43:50', 'Errori di scena / Posizione', 'Dopo l''accidentale uccisione di Marvin all''interno dell''auto, Jules e Vincent si rifugiano da Jimmie per ripulirsi. Quando indossano i vestiti prestati da Jimmie (le magliette e i pantaloncini da surfisti), la disposizione e la dimensione delle macchie di sangue rimaste sul collo e sulle braccia di Jules cambiano drasticamente tra le inquadrature prima e dopo la doccia improvvisata.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(595, 116, '00:12:15', 'Errori di scena / Posizione', 'Quando Theodore indossa per la prima volta l''auricolare per configurare il nuovo sistema operativo (Samantha), l''orientamento del piccolo dispositivo nel suo orecchio destro cambia visibilmente tra il primo piano e l''inquadratura successiva a mezzo busto, ruotando di circa 45 gradi.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(596, 116, '00:22:45', 'Troupe o microfoni visibili', 'Durante una ripresa notturna nell''appartamento di Theodore, mentre la telecamera compie una lenta panoramica verso la vetrata che si affaccia sulla città illuminata, nel riflesso del vetro sul lato sinistro è possibile scorgere per pochi istanti la sagoma di un operatore della troupe e parte dell''attrezzatura di ripresa coperta da un panno scuro.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(597, 116, '00:34:40', 'Errori di scena / Posizione', 'Nella scena in cui Theodore cammina sul molo e mostra il panorama a Samantha, la spilla da balia utilizzata per fissare il dispositivo mobile alla tasca della camicia (in modo che la telecamera sporga correttamente) cambia posizione. Nei primi piani è posizionata molto più in alto rispetto alle inquadrature larghe, dove il telefono appare visibilmente più affossato nella tasca.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(598, 116, '00:52:10', 'Errori di scena / Posizione', 'Durante la cena per l''appuntamento al buio con il personaggio interpretato da Olivia Wilde, il livello del vino rosso nel bicchiere della donna fluttua in modo incoerente. Tra un montaggio serrato e l''altro, il bicchiere passa dall''essere quasi vuoto a riempirsi nuovamente a metà, senza che venga mostrato nessuno intento a versare altro vino.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(599, 116, '01:12:05', 'Errori di scena / Posizione', 'Nella tesa scena del ristorante in cui Theodore incontra Catherine per firmare le carte del divorzio, la penna sul tavolo cambia continuamente posizione. Inizialmente è posizionata parallelamente al bordo del tavolo, ma nei controcampi successivi appare inclinata e poi nuovamente dritta, prima ancora che Catherine la prenda in mano per firmare.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(600, 116, '01:35:15', 'Errori di scena / Posizione', 'Quando Theodore si siede disperato sui gradini della metropolitana dopo che Samantha è temporaneamente scomparsa, la tracolla della sua borsa di pelle cambia posizione tra le inquadrature. Nella ripresa dall''alto la tracolla è perfettamente tesa sulla spalla, mentre nel primo piano successivo è attorcigliata e posizionata più vicino al collo.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(71, 30, '01:02:10', 'Anacronismo', 'Sullo sfondo di una sequenza ambientata nelle praterie selvagge si nota una recinzione con filo spinato industriale di manifattura moderna, incompatibile con l''epoca storica del racconto.', TRUE, '2026-09-13T15:08:13.543457', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(72, 31, '00:35:12', 'Crew & Equipment', 'Durante la rissa nel bar al Cairo, in sottofondo a sinistra si nota distintamente una comparsa che indossa una maglietta a maniche corte e jeans blu di taglio moderno.', TRUE, '2026-09-13T15:08:13.770472', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(73, 31, '01:14:05', 'Continuity', 'Nel celebre scontro attorno all''aereo ad elica, i tagli e le macchie di sangue sul viso di Indiana Jones cambiano forma, estensione e posizione tra una ripresa e l''altra.', TRUE, '2026-09-13T15:08:13.860739', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(74, 31, '01:28:40', 'Anacronismo', 'Nella sequenza animata con la mappa del volo di linea compare la dicitura ''Thailandia'', ma nel 1936 lo stato si chiamava ancora ufficialmente ''Siam''.', TRUE, '2026-09-13T15:08:13.954093', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(75, 32, '00:42:15', 'Anacronismo', 'Un nobile romano viene mostrato mentre legge un quotidiano stampato all''interno di un bar, sebbene la stampa a caratteri mobili e i giornali moderni siano stati inventati oltre un millennio dopo.', TRUE, '2026-09-13T15:10:37.439306', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3896, 184, '01:15:00', 'Errori di scena / Posizione', 'Durante le sequenze di combattimento, la posizione delle ferite e del sangue sul viso di Thorin Scudodiquercia cambia visibilmente tra un''inquadratura e l''altra, apparendo e scomparendo a seconda dell''angolazione della telecamera.', TRUE, '2026-11-02T10:10:17.098935', 'The Hobbit The Battle of the Five Armies continuity error Thorin face', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(77, 32, '01:38:05', 'Fattuale / Storico', 'La ricostruzione della naumachia mostra il Colosseo allagato e infestato da squali aggressivi; per quanto le battaglie navali venissero riprodotte, l''introduzione di squali in acqua dolce/salmastra all''epoca è biologicamente e storicamente inverosimile.', TRUE, '2026-09-13T15:10:37.628196', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(78, 32, '00:18:40', 'Continuity', 'Durante l''assedio iniziale a Numidia, i tagli e le macchie di sangue sul volto di Lucio cambiano forma, densità e posizione tra le inquadrature ravvicinate e i campi lunghi.', TRUE, '2026-09-13T15:10:37.723547', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(79, 33, '00:43:15', 'Anacronismo', 'Quando Frodo e Sam camminano tra i campi della Contea, sullo sfondo in alto a destra si nota chiaramente una vettura bianca in movimento lungo una strada di campagna.', TRUE, '2026-09-13T15:13:21.675286', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(80, 33, '01:25:10', 'Continuity', 'Durante la scena del Consiglio di Elrond a Gran Burrone, la posizione e l''ampiezza delle ferite sul viso di Frodo cambiano visibilmente tra una ripresa e l''altra.', TRUE, '2026-09-13T15:13:21.770342', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(81, 33, '02:15:40', 'Crew & Equipment', 'Nella battaglia finale ad Amon Hen, è visibile l''ombra di un cameraman con la propria attrezzatura proiettata su una roccia alle spalle di Aragorn.', TRUE, '2026-09-13T15:13:21.815251', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(82, 34, '00:38:22', 'Continuity', 'Quando Merry e Pipino giacciono prigionieri degli Uruk-hai, i polsi di Pipino appaiono legati; nell''inquadratura successiva la corda scompare del tutto per poi ricomparire quando taglia i legami.', TRUE, '2026-09-13T15:13:22.008909', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(710, 137, '00:24:15', 'Errori di scena / Posizione', 'Durante la scena del briefing nel magazzino, Spence (Sean Bean) illustra il piano d''imboscata disegnandolo con un pennarello su una lavagna bianca. Nel passaggio tra i campi e controcampi con Sam (Robert De Niro), le frecce, le annotazioni e i tratti del diagramma cambiano spessore, posizione e dettagli prima ancora che vengano cancellati.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(711, 137, '00:33:40', 'Errori di scena / Posizione', 'Nello scontro a fuoco sotto il ponte durante l''acquisto delle armi, il parabrezza del furgone dei trafficanti viene ripetutamente crivellato di colpi d''arma da fuoco. Nel cambio di inquadratura in cui il veicolo fa retromarcia per scappare, la ragnatela di fori di proiettile è quasi del tutto assente e il vetro appare notevolmente più integro.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(712, 137, '00:56:45', 'Errori di scena / Posizione', 'Durante l''inseguimento a Nizza, l''Audi S8 sperona la Mercedes 450 SEL riportando la frantumazione del faro anteriore sinistro e un evidente ripiegamento del cofano. In diverse inquadrature successive lungo la strada costiera, il faro dell''Audi riappare miracolosamente intatto e il cofano allineato, per poi tornare accartocciato nel montaggio seguente.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(713, 137, '01:15:30', 'Errori di scena / Posizione', 'Nel rifugio di Jean-Pierre ad Arles, mentre Sam guida Vincent nell''estrazione chirurgica del proiettile con l''aiuto di uno specchio, la quantità e la distribuzione del sangue sul torace di De Niro variano bruscamente: il tampone e la garza risultano saturi di sangue, ma nell''inquadratura immediatamente successiva sono quasi immacolati.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(714, 137, '01:31:10', 'Troupe o microfoni visibili', 'Nel corso del celebre inseguimento a Parigi tra la Peugeot 406 e la BMW Serie 5, durante una rapida virata lungo una curva stretta, sulla carrozzeria metallizzata della BMW si scorge chiaramente il riflesso della camera car e della struttura di supporto del braccio cinematografico montato a fianco della vettura.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(715, 137, '01:33:25', 'Errori di scena / Posizione', 'Durante la guida contromano nel tunnel di Parigi, il parabrezza della Peugeot 406 guidata da Sam si incrina vistosamente per l''impatto con detriti e colpi d''arma da fuoco. Nei primi piani ripresi dall''interno dell''abitacolo verso De Niro e Reno, il parabrezza torna ad essere perfettamente trasparente e privo di crepe per permettere la visibilità dei volti degli attori.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(716, 137, '01:47:10', 'Errori storici o fattuali', 'All''interno del palazzetto Le Zénith, il fucile di precisione impiegato per colpire la pattinatrice russa mostra un collimatore con un evidente fascio laser rosso visibile che viaggia dritto fino al bersaglio. Nei protocolli operativi dei tiratori scelti professionisti non si usano puntatori laser a fascio continuo a lungo raggio in ambienti illuminati, poiché disperdono la mira e rivelano all''istante l''esatta posizione del cecchino.', TRUE, '2026-09-25T20:39:52.091491', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1024, 231, '01:08:40', 'Troupe o microfoni visibili', 'Nella parte superiore dello schermo, durante la scena concitata nel corridoio della casa, si nota per qualche istante l''estremità del microfono a calza (boom mic) che entra dall''alto nell''inquadratura.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(601, 116, '01:58:30', 'Errori di scena / Posizione', 'Sulla scena finale del tetto con Amy, la disposizione dei capelli di Theodore e i fiocchi di neve/fuliggine depositati sulla sua giacca cambiano tra i tagli di montaggio. In particolare, una vistosa macchia chiara sulla spalla sinistra scompare completamente nel cambio di inquadratura per poi riapparire subito dopo.', TRUE, '2026-09-17T18:14:01.31731', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(734, 140, '00:12:45', 'Anacronismo / Scenografia', 'Durante la sequenza dell''arrivo degli immigrati a Ellis Island, sullo sfondo di una parete dell''edificio principale è visibile per pochi secondi una placca elettrica per interruttori di concezione moderna, non compatibile con il 1921.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(735, 140, '00:28:10', 'Errore di continuità', 'Quando Bruno (Joaquin Phoenix) parla con Ewa (Marion Cotillard) all''interno del teatro, la posizione dello scialle della donna cambia tra il campo e il controcampo: prima è avvolto saldamente intorno alle spalle, poi scivola lungo le braccia nel taglio successivo.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(736, 140, '00:45:15', 'Attrezzatura visibile', 'Nella parte superiore dell''inquadratura, durante l''accesa discussione tra Bruno e i suoi collaboratori nel retrobottega, è possibile notare la parte inferiore del microfono a giraffa (boom mic) che entra brevemente nel campo.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(737, 140, '01:02:30', 'Oggetti di scena / Continuità', 'Durante l''esibizione di magia di Orlando (Jeremy Renner), la posizione del mazzo di carte sul tavolo cambia vistosamente tra due inquadrature ravvicinate: prima si trova alla destra del calice d''acqua, poi alla sua sinistra senza che l''illusionista lo abbia spostato.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(738, 140, '01:18:05', 'Anacronismo', 'Nella ripresa esterna a livello stradale di una via di Manhattan, si scorge nell''angolo inferiore sinistro un tombino in ghisa recante una sigla di codifica industriale adottata dalla città di New York solo a partire dagli anni ''50.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(602, 83, '00:17:45', 'Errori di scena / Posizione', 'Durante il viaggio in pick-up verso le coordinate segrete della NASA, il pattern e lo spessore della polvere accumulata sul parabrezza e sul cofano del veicolo cambiano notevolmente tra l''inquadratura esterna e le riprese dall''interno dell''abitacolo.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(603, 83, '00:48:15', 'Troupe o microfoni visibili', 'Nella sequenza in cui l''equipaggio si muove in assenza di gravità all''interno della nave Endurance, nel riflesso del vetro del portello e sulla visiera della tuta di Doyle è brevemente visibile la sagoma di un pannello luce della troupe e un cavo di sospensione.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(604, 83, '00:58:20', 'Errori di scena / Posizione', 'Durante la conversazione tra l''equipaggio prima di scendere sul pianeta di Miller, la cinghia dell''imbracatura sulla spalla sinistra di Amelia Brand cambia posizione più volte, passando da perfettamente stesa a ritorta tra un controcampo e l''altro.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(605, 83, '01:12:10', 'Errori storici o fattuali', 'Sul pianeta di Miller, la dilatazione temporale estrema (1 ora pari a 7 anni terrestri) richiederebbe una vicinanza al buco nero Gargantua tale che le imponenti forze di marea ne disintegrerebbero la struttura rocciosa, superando di gran lunga il limite di Roche.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(606, 83, '01:42:35', 'Errori storici o fattuali', 'Durante l''esplorazione del pianeta del Dr. Mann, l''equipaggio cammina sotto ''nuvole di ghiaccio'' solide sospese nell''aria. Fisicamente, il ghiaccio d''acqua o di anidride carbonica non può formare strutture rigide galleggianti in atmosfera senza precipitare al suolo a causa della gravità.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(607, 83, '02:09:15', 'Errori di scena / Posizione', 'Nella celebre scena dell''aggancio alla stazione Endurance in rotazione incontrollata, la velocità angolare di rotazione del mozzo centrale e l''inclinazione visiva del Ranger variano in modo incoerente tra le inquadrature soggettive del quadro comandi e le ampie riprese esterne.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(608, 83, '02:28:40', 'Errori di scena / Posizione', 'All''interno della struttura del Tesseract, quando Cooper spinge i libri dalla libreria della cameretta di Murph, l''ordine dei volumi rimasti sugli scaffali e la posizione esatta di quelli caduti a terra cambiano nettamente tra i primi piani delle mani e i campi lunghi della stanza.', TRUE, '2026-09-17T20:55:55.596861', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(609, 117, '00:03:15', 'Errori di scena / Posizione', 'Durante la cerimonia d''apertura della Welton Academy, la candela che simboleggia la ''luce della conoscenza'' passata tra gli studenti cambia vistosamente altezza e intensità della fiamma tra un''inquadratura e l''altra, rivelando l''uso di candele diverse durante i vari ciak.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(3897, 196, '00:09:00', 'Troupe o microfoni visibili', 'Durante le sequenze iniziali di inseguimento nel deserto, in alcune inquadrature ravvicinate sui finestrini della V8 Interceptor è possibile intravedere il riflesso della telecamera e della troupe.', TRUE, '2026-11-02T10:10:29.638517', 'Mad Max 2 camera reflection crew visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(610, 117, '00:12:40', 'Errori di scena / Posizione', 'Nella celebre scena del corridoio in cui il professor Keating raduna gli studenti davanti alle foto d''epoca (''Carpe Diem''), i capelli di Robin Williams cambiano continuamente posizionamento: in alcune inquadrature ravvicinate sono spettinati sulla fronte, mentre nei campi medi sono perfettamente pettinati all''indietro.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(611, 117, '00:18:50', 'Anacronismi', 'L''antologia di poesia utilizzata dagli studenti, ''Understanding Poetry'' di Brooks e Warren, mostra una veste grafica e una copertina rigida che corrispondono a un''edizione scolastica pubblicata solo a partire dalla metà degli anni ''70, mentre il film è rigorosamente ambientato nel 1959.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(612, 117, '00:22:15', 'Troupe o microfoni visibili', 'Durante una delle prime lezioni di Keating in aula, mentre si muove tra i banchi spiegando la poesia, sul vetro dell''armadietto dei libri posizionato sul fondo della stanza si può notare per un breve istante il riflesso di un pannello riflettente della troupe e la sagoma di un operatore.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(741, 141, '00:04:10', 'Continuità', 'Durante la scena dell''attacco notturno iniziale a Chrissie, la posizione dei suoi vestiti lasciati sulla spiaggia e lo stato dei suoi capelli (da completamente bagnati a parzialmente asciutti) cambiano in modo incoerente tra un''inquadratura e l''altra.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(739, 140, '01:34:40', 'Continuità / Trucco', 'Dopo il confronto fisico tra Bruno e Orlando, la ferita da taglio sul labbro di quest''ultimo cambia forma ed estensione: nella prima inquadratura è un piccolo taglio con poco sangue, mentre nell''inquadratura successiva il sangue copre gran parte del mento.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(740, 140, '01:48:20', 'Riflesso / Attrezzatura', 'Nel riflesso del lucido finestrino dell''automobile d''epoca che si allontana lungo la strada, si distinguono chiaramente i pannelli riflettenti bianchi usati dalla troupe per illuminare il volto degli attori.', TRUE, '2026-09-27T17:50:13.295344', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(591, 115, '01:12:05', 'Troupe o microfoni visibili', 'Durante la fuga in taxi di Butch con la guidatrice Esmeralda, i finestrini del veicolo mostrano chiaramente che lo sfondo è una proiezione posteriore (back-projection). In un paio di inquadrature ravvicinate, si nota il riflesso delle luci del set cinematografico e delle attrezzature della troupe sul parabrezza e sul finestrino laterale.', TRUE, '2026-09-17T18:00:05.719359', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(613, 117, '00:48:10', 'Errori di scena / Posizione', 'Nella scena in cui Knox Overstreet scende in bicicletta lungo la collina erbosa spaventando uno stormo di oche, sul prato sono chiaramente visibili i solchi lasciati dalle ruote della bicicletta nei passaggi e nei ciak precedenti, indicando che la scena è stata ripetuta più volte.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(614, 117, '01:15:05', 'Errori di scena / Posizione', 'Quando Todd riceve il set da scrivania per il compleanno e decide di lanciarlo giù dal ponte insieme a Neil, l''oggetto si rompe a mezz''aria in un determinato modo. Tuttavia, nell''inquadratura successiva che mostra i pezzi al suolo, la disposizione e lo stato dei componenti distrutti non corrispondono alla dinamica di caduta appena mostrata.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(615, 117, '01:35:10', 'Errori storici o fattuali', 'Nel programma di sala distribuito per la recita teatrale di ''Sogno di una notte di mezza estate'' a cui assistono i protagonisti, sono stati utilizzati caratteri tipografici digitali moderni (tra cui varianti di Helvetica e font simili) che non erano ancora stati progettati o commercializzati nel 1959.', TRUE, '2026-09-18T06:40:36.627653', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(617, 118, '00:22:15', 'Errori di scena / Posizione', 'Quando John Ruth e Daisy entrano nell''emporio di Minnie per sfuggire alla tormenta, i loro abiti e cappelli sono completamente ricoperti di neve fresca. Al cambio di inquadratura, un secondo dopo all''interno del locale, la quantità di neve sui vestiti di Kurt Russell è drasticamente diminuita e disposta in modo diverso, prima ancora che possa essersi sciolta o che lui possa averla scrollata via.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1025, 231, '01:15:05', 'Errori storici o fattuali', 'Quando viene inquadrato lo schermo del videogioco online giocato da Finn, l''interfaccia di rete e la simulazione della chat multiplayer mostrano dinamiche e schermate prive di senso tecnico rispetto alle reali funzionalità delle console disponibili nel 2012.', TRUE, '2026-10-24T15:36:29.469711', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(618, 118, '00:25:40', 'Errori di scena / Posizione', 'La porta dell''emporio è rotta e deve essere inchiodata ogni volta che qualcuno entra o esce. Quando O.B. inchioda le assi di legno per sigillare la porta dopo l''ingresso di Warren e Ruth, la disposizione delle assi e la posizione dei chiodi cambiano visibilmente nelle inquadrature successive, mostrando una chiara discrepanza di montaggio tra i vari ciak.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(619, 118, '01:02:45', 'Errori di scena / Posizione', 'Durante la scena in cui i personaggi mangiano lo stufato preparato da Minnie, il livello del cibo all''interno della ciotola di Major Warren sale e scende in modo incoerente. In un''inquadratura la ciotola è quasi vuota, mentre nel taglio successivo è nuovamente piena a metà, senza che il personaggio si sia servito nuovamente dal calderone.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(620, 118, '01:15:15', 'Anacronismi', 'Il film è ambientato circa sei-otto anni dopo la fine della Guerra Civile Americana (quindi intorno al 1871-1873). Tuttavia, in diverse scene si vede chiaramente l''utilizzo di un revolver Remington Modello 1890. Questa pistola non era ancora stata progettata né prodotta all''epoca in cui si svolgono gli eventi del film, rappresentando un evidente anacronismo tecnologico.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(621, 118, '01:32:20', 'Errori di scena / Posizione', 'Nella celebre scena in cui Daisy suona la chitarra e John Ruth gliela strappa di mano per distruggerla (dove venne accidentalmente distrutto un pezzo autentico da museo del 1870 anziché la copia di scena), si nota un salto di montaggio. La transizione tra l''inquadratura in cui Jennifer Jason Leigh suona lo strumento reale e quella in cui Kurt Russell lo distrugge mostra un repentino cambio di postura dell''attrice e una sfasatura nella reazione di shock reale di quest''ultima.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(622, 118, '01:48:30', 'Errori di scena / Posizione', 'Durante la spiegazione di Major Warren riguardo alla sparatoria avvenuta nell''emporio, sul pavimento ci sono delle caramelle gommose (jellybeans) sparse vicino al bancone. Il numero di caramelle e la loro esatta disposizione sul pavimento di legno cambiano sensibilmente tra un''inquadratura e l''altra, rivelando che la scena è stata girata in più riprese senza riposizionare accuratamente gli elementi di scena.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(623, 118, '02:12:10', 'Errori di scena / Posizione', 'Dopo che John Ruth viene avvelenato e vomita sangue addosso a Daisy Domergue, il volto di Jennifer Jason Leigh appare coperto di sangue. Nelle scene successive, mentre è incatenata al cadavere di Ruth, la disposizione, la densità e le macchie di sangue sul suo viso cambiano continuamente forma, consistenza e posizione tra i primi piani e i campi medi.', TRUE, '2026-09-18T10:36:10.375501', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(693, 65, '01:12:05', 'Anacronismi', 'Le armature e gli elmi indossati da Sir Ranulf e da alcuni soldati dello Sceriffo presentano dettagli metallici e finiture tipiche del XIV e XV secolo, decisamente troppo avanzati per il periodo storico del regno di Re Giovanni (inizio XIII secolo).', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(695, 65, '01:41:50', 'Errori storici o fattuali', 'Il veleno somministrato da Marian a se stessa e a Robin agisce in modo quasi istantaneo e indolore, permettendo loro un ultimo dialogo sereno. Dal punto di vista medico e storico, i veleni accessibili all''epoca (come derivati della belladonna o cicuta) avrebbero provocato spasmi violenti, vomito e agonia, incompatibili con la fine romantica mostrata.', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(689, 65, '00:04:30', 'Errori di scena / Posizione', 'Durante l''assedio iniziale del castello di Châlus, la disposizione delle pietre e delle macerie ai piedi delle mura cambia visibilmente tra l''inquadratura in cui il vecchio difensore lancia i sassi e quella successiva in cui i soldati di Re Riccardo si avvicinano.', TRUE, '2026-09-22T20:36:28.422194', NULL, 0, 0, 'mrtlsn07@gmail.com', 'ia', NULL),
(624, 125, '00:15:45', 'Errori di scena / Posizione', 'Nel bar ''Simulatte'', durante la prima conversazione tra Thomas Anderson e Tiffany, la posizione degli oggetti sul tavolino cambia continuamente: la tazza da caffè di Tiffany e il tovagliolo con i dolci si spostano e ruotano visibilmente nei raccordi tra i controcampi senza che nessuno dei personaggi li abbia toccati.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(625, 125, '00:28:12', 'Errori di scena / Posizione', 'Nella sequenza del bagno dell''ufficio in cui il nuovo Morpheus offre la pillola rossa a Neo, l''orientamento della capsula e l''apertura delle dita della mano di Morpheus cambiano tra l''inquadratura ravvicinata del palmo e il piano medio successivo.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(626, 125, '00:54:30', 'Errori di scena / Posizione', 'Durante lo scontro a bordo del treno proiettile giapponese, i graffi e la scia di sangue sulla tempia destra di Neo cambiano forma ed estensione tra le inquadrature ravvicinate e quelle a figura intera, risultando prima più marcati e poi quasi asciutti o ridotti.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(627, 125, '01:15:20', 'Errori di scena / Posizione', 'Nello scontro all''interno del magazzino tra Neo e Smith, quando Smith scaglia Neo contro una struttura in ceramica spaccandola, la disposizione dei frammenti a terra e l''entità della rottura della parete variano visibilmente tra il momento dell''impatto e il controcampo seguente.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(628, 125, '01:35:10', 'Errori di scena / Posizione', 'Nel confronto al Simulatte in cui l''Analista attiva il Bullet Time, il proiettile sospeso a mezz''aria e la traiettoria rispetto al volto di Trinity e alla mano dell''Analista cambiano leggermente angolazione e distanza relativa tra i cambi di prospettiva della macchina da presa.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(629, 125, '02:05:40', 'Troupe o microfoni visibili', 'Durante l''inseguimento notturno in motocicletta per le strade di San Francisco, nel riflesso lucido del serbatoio della moto e negli specchietti retrovisori cromati è possibile scorgere in alcuni fotogrammi l''intelaiatura del carrello di ripresa montato sul veicolo d''inseguimento della troupe.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(630, 125, '02:12:15', 'Errori di scena / Posizione', 'Sulla cima del grattacielo prima del salto, l''illuminazione dell''alba e la direzione delle ombre sui volti di Neo e Trinity mostrano una forte incongruenza di continuità: nelle inquadrature strette la luce del sole è radente e calda sul lato sinistro, mentre nei piani larghi la luce è diffusa e il cielo appare con un livello di chiarore differente.', TRUE, '2026-09-18T18:43:22.751693', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(668, 133, '00:55:10', 'Errori di scena / Posizione', 'Mentre Cliff prepara la cena per il suo cane Brandy nella roulotte, apre una lattina di cibo ''Wolf''s Tooth''. La quantità di cibo che fuoriesce dalla lattina e la posizione del coperchio metallico tagliato cambiano vistosamente tra i primi piani e i campi medi.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(631, 122, '00:27:15', 'Troupe o microfoni visibili', 'Nella celebre scena in cui Morpheus offre a Neo la scelta tra la pillola rossa e la pillola blu, nel pomello dorato della porta è nettamente visibile il riflesso della telecamera da presa, che è stata parzialmente nascosta con un pezzo di stoffa per farla coincidere con la giacca di Morpheus.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(632, 122, '00:17:40', 'Errori di scena / Posizione', 'Durante l''interrogatorio condotto dall''Agente Smith, quando la bocca di Neo si fonde e si sigilla, Neo cade all''indietro contro la sedia. La posizione delle sue mani e le pieghe del colletto della camicia cambiano vistosamente tra il primo piano strettissimo e il campo medio subito successivo.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(633, 122, '01:14:10', 'Errori di scena / Posizione', 'Nella scena del déjà vu con il gatto nero, il felino cammina lungo la porta e si scuote. Nel momento in cui la scena si ripete immediatamente dopo, la posizione delle ombre sulla parete di mattoni e la postura di Trinity sullo sfondo non coincidono con la prima inquadratura.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(634, 122, '01:41:35', 'Errori di scena / Posizione', 'Durante la sequenza dello scontro a fuoco nell''atrio del palazzo, molte colonne di marmo vengono quasi totalmente distrutte dai proiettili. Tuttavia, in diversi controcampi successivi durante la medesima sparatoria, alcune colonne sullo sfondo appaiono di nuovo integre o con danni visibilmente differenti.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(47, 14, '00:34:12', 'Continuity', 'Nella famosa scena in cui Michele mangia il gigantesco barattolo di Nutella, il livello della crema all''interno del vaso varia vistosamente da un''inquadratura all''altra.', TRUE, '2026-09-13T14:58:31.314737', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(635, 122, '01:45:50', 'Errori di scena / Posizione', 'Quando Neo spara con il cannone minigun dall''elicottero per coprire la fuga di Morpheus, una pioggia incessante di bossoli cade sul pavimento dell''ufficio. Nell''inquadratura dall''alto subito successiva, la quantità di bossoli a terra attorno agli Agenti è nettamente inferiore a quella mostrata durante la raffica.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(636, 122, '01:48:20', 'Troupe o microfoni visibili', 'Nella scena in cui l''elicottero perde quota e si schianta contro il grattacielo di vetro, quando Neo sbalza fuori tenendo la corda per afferrare Trinity, sono chiaramente visibili i cavi di sicurezza del cordame di supporto collegati all''imbracatura dello stuntman.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(5184, 230, '00:48:10', 'Errori di scena / Posizione', 'Il cappotto indossato da Natalie varia la posizione della sciarpa e il modo in cui è abbottonato mentre cammina verso l''ingresso principale della villa.', TRUE, '2026-11-02T15:47:47.476965', 'Home Alone 4 Natalie coat continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(637, 122, '01:52:45', 'Errori di scena / Posizione', 'Durante il combattimento nella metropolitana tra Neo e l''Agente Smith, Smith scaraventa Neo contro una colonna di cemento. Nei fotogrammi immediatamente precedenti all''impatto di Neo, si nota chiaramente la linea di giunzione pre-tagliata sul pannello della colonna, predisposta per cedere al momento del contatto.', TRUE, '2026-09-18T18:45:37.070374', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(638, 126, '00:18:45', 'Anacronismi', 'In diverse scene della pellicola viene fatto largo uso di candelotti di dinamite. Tuttavia, la dinamite fu brevettata da Alfred Nobel solo nel 1867, mentre gli eventi del film si svolgono con precisione nel 1862, durante la Campagna del Nuovo Messico della Guerra di Secessione Americana.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(639, 126, '00:48:10', 'Errori di scena / Posizione', 'Durante la sequenza nel deserto in cui Tuco costringe il Biondo a camminare sotto il sole battente, le macchie di sudore sul poncho del Biondo e la quantità di polvere sul suo volto variano bruscamente da un''inquadratura all''altra, alternandosi tra primi piani e campi lunghi.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(640, 126, '01:24:15', 'Errori storici o fattuali', 'Lungo la linea ferroviaria su cui viaggia il treno dei prigionieri guidato dai nordisti, i binari sono posati su traverse moderne in calcestruzzo ed evidenziano piastre d''acciaio con bulloneria standard moderna, del tutto inesistenti nell''infrastruttura ferroviaria statunitense del 1862.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(641, 126, '01:52:30', 'Troupe o microfoni visibili', 'Durante la sequenza in cui la colonna militare muove vicino alle rovine del campo, nell''angolo superiore sinistro dell''inquadratura panoramica si intravede brevemente l''ombra del braccio del microfono (boom operator) proiettata sul bordo del ponte in legno.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(642, 126, '02:18:05', 'Errori di scena / Posizione', 'Durante la scena del posizionamento dell''esplosivo al ponte di Langstone, il Biondo e Tuco collegano una miccia che, nel campo largo iniziale, appare tesa e lunga diversi metri, ma nel primissimo piano successivo di accensione risulta quasi consumata e collocata a ridosso delle cariche.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(643, 126, '02:35:40', 'Anacronismi', 'Nella famosa scena del negozio d''armi, Tuco assembla un revolver personalizzato combinando pezzi di varie armi e inserisce cartucce metalliche per retrocarica. Nel 1862 la maggior parte delle armi corte dell''esercito usava ancora la carica ad avancarica con polvere e capsula a percussione; le conversioni a cartuccia metallica diventarono comuni solo a guerra finita.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(644, 126, '02:48:50', 'Errori di scena / Posizione', 'Nel celebre triello finale all''interno del cimitero di Sad Hill, la posizione delle ombre proiettate dalle pietre tombali e dai tre protagonisti cambia drasticamente tra i primi piani sui volti e le inquadrature a figura intera, rivelando che la sequenza è stata girata in momenti diversi della giornata con il sole a diverse altezze.', TRUE, '2026-09-18T18:52:12.025785', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(645, 132, '00:14:32', 'Errori di scena / Posizione', 'Durante la scena del primo scontro sul ponte di Brooklyn, quando Spider-Man si rialza da terra dopo aver schivato un attacco, la lacerazione sul costume cambia lato: nell''inquadratura frontale lo strappo è ben visibile sulla guancia destra della maschera, mentre nel controcampo immediato si sposta sulla guancia sinistra.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(646, 132, '00:38:15', 'Troupe o microfoni visibili', 'Mentre Peter Parker ed MJ parlano all''esterno del bar a Manhattan, nell''angolo superiore destro dello schermo si nota chiaramente la punta del microfono a giraffa (boom mic) con il peluche antivento nero che si abbassa per circa tre secondi all''interno del riquadro.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(647, 132, '00:52:40', 'Anacronismi', 'In una sequenza di flashback ambientata visibilmente durante il primo anno di liceo dei protagonisti (circostanziata intorno al 2017), un passante sullo sfondo della strada sta chiaramente utilizzando un modello di iPhone 15 Pro, uscito sul mercato solo diversi anni dopo.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(677, 136, '01:18:20', 'Troupe o microfoni visibili', 'Durante una carica di cavalleria ad ampie riprese nelle praterie, sul terreno brullo davanti ai cavalli sono distintamente visibili i solchi e le tracce degli pneumatici lasciati dalla vettura della macchina da presa (camera car).', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(678, 136, '01:35:05', 'Errori storici o fattuali', 'Viene mostrato un incontro formale e un negoziato privato faccia a faccia tra Custer e il capo nativo Cavallo Pazzo (Anthony Quinn). Storicamente, Cavallo Pazzo e Custer non si incontrarono né trattarono mai di persona.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(679, 136, '02:10:15', 'Anacronismi', 'Durante l''epica carica finale al Little Bighorn, i cavalleggeri del 7° Cavalleria sguainano e usano le sciabole d''ordinanza. Nella realtà, le sciabole furono lasciate nei depositi del forte prima dell''inizio della campagna per alleggerire l''equipaggiamento.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1026, 225, '02:01:25', 'Errori di scena / Posizione', 'Mentre Nathan Algren (Tom Cruise) smonta da cavallo arrivando al villaggio prima della battaglia, lo stallone sferra un involontario calcio all''inguine di una comparsa vestita da samurai sullo sfondo a destra, la quale si piega in due dal dolore tentando di rimanere in parte nell''inquadratura.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(663, 129, '02:22:15', 'Errori di scena / Posizione', 'Durante la lussuosa cena romantica tra Noodles e Deborah nel ristorante sul mare, il livello dello champagne nei calici dei due personaggi sale e scende in modo del tutto incoerente tra i vari controcampi, senza che nessuno dei due abbia effettivamente bevuto o che il cameriere abbia versato nuovamente la bevanda.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(665, 129, '03:15:40', 'Errori storici o fattuali', 'Nella sezione del film ambientata nel 1968, quando Noodles visita il sontuoso mausoleo, viene mostrata una targa commemorativa. Le date di nascita e morte riportate per alcuni personaggi non coincidono temporalmente con la cronologia degli eventi narrati nella prima parte del film, creando una discrepanza storica interna alla narrazione di Leone.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(666, 133, '02:12:15', 'Anacronismi', 'Durante il volo di ritorno di Rick e Cliff dall''Italia su un aereo della Pan Am, viene mostrato un Boeing 747. Tuttavia, la tratta si svolge nell''agosto del 1969, mentre il Boeing 747 è entrato in servizio commerciale per la Pan Am solo nel gennaio del 1970.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(667, 133, '00:28:40', 'Errori di scena / Posizione', 'Nella scena in cui Cliff Booth guida la Cadillac di Rick Dalton di giorno, i suoi occhiali da sole a goccia cambiano posizione tra le inquadrature: in un frame sono calzati sul viso, mentre nel taglio successivo si trovano appesi al colletto della camicia, per poi tornare sul viso senza che lui compia il movimento di indossarli.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(5185, 230, '01:02:15', 'Audio / Doppiaggio / Sync', 'In una conversazione tra Marv e Peter, il movimento delle labbra di Marv non coincide perfettamente con l''audio delle battute pronunciate durante un primo piano stretto.', TRUE, '2026-11-02T15:47:47.476965', 'Home Alone 4 Marv lip sync error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3898, 196, '00:32:00', 'Errori di scena / Posizione', 'Quando Max esamina il camion cisterna nella base, la posizione delle taniche e degli attrezzi sul retro cambia visibilmente tra un''inquadratura e l''altra senza che nessuno li abbia toccati.', TRUE, '2026-11-02T10:10:29.638517', 'Mad Max 2 tanker continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(342, 59, '02:41:05', 'Errori di scena / Posizione', 'Nella scena post-credits ambientata 10 anni dopo, Elizabeth e suo figlio sono sulla scogliera ad attendere il ritorno di Will. L''ombra proiettata dai due personaggi sul terreno cambia angolazione di oltre 45 gradi tra il primo piano e la panoramica finale verso il tramonto, rivelando che le riprese sono state effettuate in momenti della giornata molto differenti.', TRUE, '2026-09-14T14:15:12.32037', 'Pirati dei Caraibi - Ai confini del mondo Nella scena postcredits ambientata 10 anni dopo Elizabeth mistake error', 0, 0, 'IA (Sistema)', 'ia', NULL),
(674, 136, '00:12:30', 'Errori storici o fattuali', 'La pellicola mostra George Armstrong Custer che arriva all''Accademia Militare di West Point nel 1861, in concomitanza con lo scoppio della Guerra di Secessione. Nella realtà storica, Custer entrò a West Point nel 1857 e si diplomò nel giugno del 1861.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(675, 136, '00:28:45', 'Anacronismi', 'Durante le sequenze di battaglia ambientate nella Guerra Civile (1861-1865), molti soldati dell''Unione impugnano revolver Colt Single Action Army ''Peacemaker'' e fucili Springfield Trapdoor, armi introdotte solo nel 1873.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(676, 136, '00:45:10', 'Errori di scena / Posizione', 'Nella scena del dialogo romantico tra Custer e Libbie nel salotto, la sciarpa di Libbie cambia posizione tra le inquadrature: prima si trova sulla spalla destra, poi nei primi piani appare posizionata centralmente sul petto, per poi tornare indietro.', TRUE, '2026-09-21T20:36:15.565218', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(14, 2, '02:27:00', 'Fattuale / Storico', 'Commodo muore nel Colosseo ucciso da Massimo. Storicamente, Commodo governò per 12 anni e morì nel 192 d.C. strangolato nel suo bagno dal lottatore Narciso a seguito di una congiura di palazzo.', TRUE, '2026-09-13T14:42:52.709705', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(51, 16, '00:18:22', 'Fattuale / Storico', 'L''aquila gigante Marahute presenta caratteristiche anatomiche ed etologiche tipiche delle aquile calve americane, del tutto assenti nella fauna selvatica australiana.', TRUE, '2026-09-13T14:58:32.129787', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(83, 34, '02:05:12', 'Continuity', 'Durante la carica al Fosso di Helm, la spada nella faretra di Aragorn scompare momentaneamente durante la corsa lungo la rampa per poi riapparire nella ripresa seguente.', TRUE, '2026-09-13T15:13:22.085534', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(20, 3, '01:14:05', 'Continuity', 'Quando l''elicottero precipita a Central Park, le pale del rotore principale appaiono completamente spezzate nell''inquadratura dall''interno, ma ritornano parzialmente integre e piegate nell''inquadratura successiva esterna.', TRUE, '2026-09-13T14:43:24.75352', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(660, 129, '00:38:40', 'Anacronismi', 'Nelle scene ambientate nel 1918 nel Lower East Side di New York, sui tetti di alcuni edifici sullo sfondo sono chiaramente visibili diverse antenne televisive e cavi telefonici moderni, elementi del tutto inesistenti all''epoca in cui è ambientata l''infanzia dei protagonisti.', TRUE, '2026-09-19T19:44:18.773942', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(761, 143, '01:31:10', 'Attrezzatura visibile', 'Durante la sequenza di panico nei tunnel subacquei, in un''inquadratura grandangolare si possono notare i riflessi delle luci di produzione e di parte della troupe cinematografica sulle pareti curve in plexiglass che simulano il tunnel sommerso.', TRUE, '2026-09-28T06:24:16.525723', NULL, 0, 0, 'lrscrm73@gmail.com', 'utente', NULL),
(510, 103, '00:38:20', 'Errori storici o fattuali', 'La bandiera britannica (Union Jack) che sventola su Forte William Henry include la croce rossa diagonale di San Patrizio. Questo disegno della bandiera è stato adottato solo nel 1801 con l''Atto di Unione, mentre le vicende del film si svolgono nel 1757 durante la guerra franco-indiana.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'utente', NULL),
(509, 103, '00:14:35', 'Errori di scena / Posizione', 'Durante la cena a casa di Jack Winthrop, la posizione delle candele sul tavolo e il livello della loro cera cambiano vistosamente tra i primi piani e i campi medi, tornando ad essere più lunghe in alcune inquadrature successive.', TRUE, '2026-09-16T13:02:08.462231', NULL, 0, 0, 'IA (Sistema)', 'utente', NULL),
(719, 6, '2', 'Errori di scena / Posizione', 'asdsasddsadasasd', TRUE, '2026-09-26T12:20:09.059413', NULL, 0, 0, 'mrtrrt67@gmail.com', 'utente', NULL),
(1027, 225, '00:06:15', 'Anacronismi', 'All''inizio del film, durante l''esibizione dei fucili negli Stati Uniti ambientata nel 1876, viene mostrata una bandiera americana con 43 stelle. Nel 1876 gli Stati Uniti avevano 38 stati (la bandiera a 43 stelle fu adottata solo nel 1890).', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1028, 225, '01:08:40', 'Errori di scena / Posizione', 'Durante il duro allenamento con le spade di legno sotto la pioggia battente tra Algren e Ujiio, la quantità e la disposizione del fango sul viso e sulla tunica di Tom Cruise cambiano visibilmente ad ogni stacco di montaggio tra i primi piani e i campi medi.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1029, 225, '02:14:10', 'Errori storici o fattuali', 'Nella scontro finale ambientato durante la ribellione di Satsuma (1877), l''esercito imperiale impiega mitragliatrici Gatling Modello 1883 con caricatore circolare superiore, armi che non esistevano ancora all''epoca degli avvenimenti.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1030, 225, '00:46:20', 'Troupe o microfoni visibili', 'Durante la prima battaglia nella foresta avvolta dalla nebbia, nei dettagli lucidi dell''armatura di un samurai in prima fila è chiaramente visibile il riflesso di uno schermo riflettente bianco della troupe utilizzato per illuminare gli attori.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1031, 225, '02:19:50', 'Errori di scena / Posizione', 'Nel momento in cui Katsumoto compie il rituale del seppuku assistito da Algren, la posizione della lama del tantō e l''estensione delle macchie di sangue sul petto del samurai variano visibilmente nel passaggio dalle inquadrature ampie al primo piano.', TRUE, '2026-10-24T15:38:16.555456', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(672, 133, '02:18:45', 'Errori storici o fattuali', 'La notte del 9 agosto 1969 (la notte degli omicidi Manson nella realtà), il cielo nel film mostra una luna quasi piena e molto luminosa. Storicamente, quella notte la luna era in fase di calante avanzata (circa il 18% di visibilità), rendendo la notte estremamente buia.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(673, 133, '00:32:15', 'Troupe o microfoni visibili', 'Durante la scena in cui Cliff Booth guida la Cadillac di Rick Dalton di sera e passa davanti ai cinema al neon, sul parabrezza lucido e sulla carrozzeria della vettura si riflette chiaramente la sagoma della telecamera montata sul veicolo di ripresa (camera car) che precede l''auto.', TRUE, '2026-09-19T19:47:51.941973', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1038, 236, '00:24:15', 'Troupe o microfoni visibili', 'Nella scena dell''ospedale psichiatrico, mentre la telecamera ruota attorno a Jeffrey Goines (Brad Pitt) che parla freneticamente, sul vetro divisorio sbarrato è possibile scorgere per un istante il riflesso dell''operatore della mdp e dell''attrezzatura d''illuminazione della troupe.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1039, 236, '00:48:30', 'Errori di scena / Posizione', 'Quando Cole viene catapultato erroneamente nella trincea della Prima Guerra Mondiale nel 1917 e viene ferito, la chiazza di sangue sui suoi pantaloni cambia estensione e posizione esatta tra il momento del fendente e la ripresa successiva in cui viene trascinato.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1040, 236, '01:12:40', 'Errori di scena / Posizione', 'Nella drammatica scena della stanza d''albergo dove Cole si strappa da solo un dente con le pinze, le sbavature di sangue sul mento e sulle mani cambiano completamente disposizione tra il primo piano e il controcampo.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1041, 236, '01:34:10', 'Anacronismi', 'Durante le riprese esterne ambientate nel 1990, in sottofondo nel traffico urbano è visibile un modello di automobile (un restyling della Ford Taurus) commercializzato solo a partire dalla fine del 1991.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1042, 236, '01:45:15', 'Errori storici o fattuali', 'Quando la dottoressa Kathryn Railly estrae la pallottola dalla gamba di Cole, afferma che si tratta di un proiettile risalente alla Prima Guerra Mondiale (1917). Tuttavia, la forma della ogiva mostrata in primo piano è quella di un proiettile camiciato di concezione moderna, incompatibile con la munizione d''epoca citata.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1043, 236, '02:02:50', 'Errori di scena / Posizione', 'Nella sequenza finale all''aeroporto, quando Cole indossa la parrucca e i baffi finti per integrarsi tra i passeggeri, l''inclinazione e la simmetria dei baffi finti cambiano visibilmente tra un''inquadratura e l''altra mentre corre.', TRUE, '2026-10-24T15:59:46.407659', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(742, 141, '00:14:25', 'Errori nei testi', 'Quando il capo Brody sta battendo a macchina il rapporto sulla morte della prima vittima, digita erroneamente ''CORNER''S OFFICE'' anziché ''CORONER''S OFFICE''.', TRUE, '2026-09-27T20:43:10.736812', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(706, 63, '01:14:30', 'Errori di scena / Posizione', 'Durante la scena sentimentale al balcone con Lady Marian, il velo del suo elaborato copricapo cade lungo la spalla sinistra nel campo medio, ma nel controcampo ravvicinato si trova completamente spostato dietro la schiena.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(707, 63, '01:32:05', 'Anacronismi', 'Durante la zuffa tra le guardie e i fuorilegge, uno degli stuntman che cade all''indietro mostra distintamente la suola di gomma stampata con scanalature moderne sotto gli stivali di pelle.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(708, 63, '01:48:50', 'Troupe o microfoni visibili', 'Nella celebre scena in cui Robin Hood scivola lungo la gigantesca tenda della sala del trono, per diversi fotogrammi è visibile la carrucola di supporto e il cavo di guida nascosto nella piega superiore del tessuto.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(709, 63, '02:03:15', 'Errori storici o fattuali', 'Sugli stendardi del Principe Giovanni e sulle tuniche dei soldati compare lo stemma reale con i tre leoni passanti, simboleggiamento che venne introdotto ufficialmente da Riccardo Cuor di Leone solo nel 1198, cioè anni dopo gli eventi narrati nel film.', TRUE, '2026-09-25T19:09:14.246576', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(19, 3, '01:05:12', 'Crew & Equipment', 'Nella sequenza d''azione all''interno del tunnel della metropolitana, in un fotogramma illuminato dal visore notturno è visibile sulla parete sinistra l''ombra dell''operatore di ripresa con il supporto per la telecamera.', TRUE, '2026-09-13T14:43:24.654587', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1044, 235, '00:12:35', 'Errori di scena / Posizione', 'Durante la scena del licenziamento di Noah in ufficio, la cravatta del protagonista cambia posizione tra un''inquadratura e l''altra: prima è leggermente allentata e storta, poi nei controcampi appare perfettamente dritta e allacciata fino al colletto.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1045, 235, '00:28:40', 'Troupe o microfoni visibili', 'Mentre Marilyn (Diane Keaton) scarica le valigie dall''auto per trasferirsi a casa del figlio, nell''angolo superiore sinistro dello schermo è chiaramente visibile la punta del microfono a boom che scende nel campo visivo per un paio di secondi.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1046, 235, '00:41:15', 'Errori di scena / Posizione', 'Nella cucina della casa, durante la discussione a colazione, il livello del succo d''arancia nel bicchiere di Clare (Liv Tyler) varia continuamente: è quasi vuoto quando parla Noah, ma torna pieno nella ripresa successiva a piano medio.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1047, 235, '00:55:02', 'Errori di scena / Posizione', 'Durante la scena in cui i cani di Marilyn corrono nel soggiorno, un cuscino decorativo rosso sul divano scompare e riappare improvvisamente nei vari stacchi di montaggio.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1048, 235, '01:08:20', 'Troupe o microfoni visibili', 'Quando Noah sale in macchina per andare a un colloquio di lavoro, nel riflesso del finestrino laterale del guidatore si distingue nettamente la sagoma di un operatore della troupe con un pannello riflettente.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1049, 235, '01:19:45', 'Errori storici o fattuali', 'Sulla domanda di assunzione che Noah sta compilando a penna, la data visibile nel modulo indica il mese di marzo, ma nell''inquadratura subito successiva sul calendario appeso al muro della stanza viene mostrato chiaramente il mese di novembre.', TRUE, '2026-10-24T16:37:16.320661', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(648, 132, '01:12:05', 'Errori storici o fattuali', 'Durante la lezione universitaria a cui assiste Peter, il professore proietta una diapositiva indicando che la Costituzione della Repubblica Italiana è entrata in vigore nel 1946 anziché il 1° gennaio 1948, commettendo un errore concettuale non corretto dal dialogo.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(649, 132, '01:35:50', 'Errori di scena / Posizione', 'Nel corso di un concitato inseguimento tra i tetti della città, l''orologio da polso di Peter Parker segna le 14:15. Nell''inquadratura immediatamente successiva, mentre l''eroe scaglia una ragnatela in primo piano, il quadrante segna improvvisamente le 16:40, nonostante la scena si svolga in tempo reale.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(650, 132, '01:51:18', 'Troupe o microfoni visibili', 'Durante il combattimento decisivo all''interno del capannone industriale, nel riflesso dell''ampia vetrata posta dietro il villain si distingue nettamente la sagoma di un operatore della troupe con maglietta chiara che manovra una telecamera su stabilizzatore Gimbal.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(651, 132, '02:08:45', 'Errori di scena / Posizione', 'Nella scena di chiusura al parco, la tazza di caffè d''asporto presa da MJ cambia aspetto tra i tagli di montaggio: inizialmente presenta un coperchio di plastica bianca con la linguetta aperta, ma nell''inquadratura seguente il coperchio diventa di colore marrone scuro e completamente sigillato.', TRUE, '2026-09-19T18:06:28.766949', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(652, 127, '00:08:24', 'Errori di scena / Posizione', 'Durante la celebre sequenza iniziale alla stazione di Cattle Corner, Stony (Woody Strode) raccoglie le gocce d''acqua che cadono dal serbatoio sulla tesa del cappello. Tra le inquadrature ravvicinate e i campi medi, la quantità d''acqua accumulata e la macchia d''umidità sul feltro cambiano visibilmente di forma e consistenza senza logica temporale.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(653, 127, '00:22:40', 'Anacronismi', 'Durante il massacro della famiglia McBain a Sweetwater, gli scagnozzi guidati da Frank impugnano fucili a ripetizione Winchester modello 1892 con leva a passante largo, modificati per sembrare modelli precedenti. L''ambientazione storica della ferrovia transcontinentale colloca tuttavia la vicenda attorno al 1868-1869, rendendo l''uso di tali armi anacronistico di oltre vent''anni.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(654, 127, '00:32:10', 'Errori di scena / Posizione', 'All''arrivo di Jill McBain (Claudia Cardinale) alla stazione di Flagstone, la posizione della veletta nera e delle ciocche di capelli che le scendono sulla spalla sinistra varia continuamente a ogni stacco di montaggio tra il primo piano e la figura intera, passando da ordinata a parzialmente sciolta.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(655, 127, '01:14:45', 'Troupe o microfoni visibili', 'All''interno della lussuosa carrozza ferroviaria privata del magnate Morton, durante il dialogo ravvicinato tra quest''ultimo e Frank, sulle superfici laccate in mogano lucido e sui vetri delle vetrinette si distinguono chiaramente i riflessi dei pannelli riflettenti bianchi e di una lampada dell''impianto di illuminazione di scena.', TRUE, '2026-09-19T18:08:29.015384', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1051, 186, '00:14:20', 'Errori di scena / Posizione', 'Durante la sequenza iniziale dell''incendio boschivo, Pete effettua una picchiata per scaricare il ritardante chimico rosso sul motore in fiamme dell''aereo di Al. Nella ripresa esterna il liquido colpisce in pieno la cabina di pilotaggio oscurando quasi totalmente il parabrezza, ma nello stacco successivo dall''interno dell''abitacolo i finestrini risultano incredibilmente puliti, consentendo ad Al una visibilità quasi perfetta.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1052, 186, '00:24:10', 'Errori di scena / Posizione', 'Nella celebre scena in cui Pete e Dorinda ballano nel capannone al suono di ''Smoke Gets in Your Eyes'', l''acconciatura di Holly Hunter cambia continuamente: nei campi lunghi i suoi capelli sono sciolti e ordinati dietro le spalle, mentre nei primi piani diverse ciocche le ricadono disordinate sul viso e sulla clavicola a seconda dell''inquadratura.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1053, 186, '00:32:05', 'Errori di scena / Posizione', 'Nel momento culminante in cui l''aereo A-26 Invader di Pete prende fuoco e vira verso l''alto prima di esplodere, è chiaramente visibile all''interno dell''abitacolo un manichino rigido e inanimato al posto di Richard Dreyfuss, posizionato con le braccia fisse sulla cloche senza alcun movimento naturale.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1054, 186, '00:38:40', 'Errori di scena / Posizione', 'Nell''incontro ultraterreno tra Pete e l''angelo Hap (Audrey Hepburn) nella radura, Hap usa le forbici per tagliare i capelli a Pete. La quantità di ciocche di capelli visibili sul colletto e sulle spalle della camicia di Pete varia ripetutamente da un''inquadratura all''altra: in alcuni controcampi il tessuto è cosparso di capelli tagliati, mentre nei piani stretti successivi è perfettamente pulito.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1055, 186, '01:13:25', 'Troupe o microfoni visibili', 'Durante le sequenze di addestramento aereo di Ted Baker guidato dallo spirito di Pete, in un''inquadratura laterale che riprende il cockpit dall''esterno si nota, sul plexiglas della cappottina e sul bordo metallico della fusoliera, il riflesso netto del supporto della macchina da presa cinematografica e di un pannello riflettente montato sulla struttura di ripresa.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1056, 186, '01:47:30', 'Errori storici o fattuali', 'Nella sequenza finale in cui Dorinda decolla per salvare la squadra di vigili del fuoco intrappolata, il lancio del ritardante chimico rosso estingue all''istante l''intero fronte di fiamma alta come alberi. Nella realtà operativa degli incendi boschivi, i ritardanti a base di fosfato d''ammonio non soffocano istantaneamente incendi di quelle proporzioni, ma servono a impregnare la vegetazione non ancora bruciata per rallentare l''avanzata delle fiamme.', TRUE, '2026-10-24T17:15:05.956821', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1057, 217, '00:18:45', 'Errori di scena / Posizione', 'Nel primo episodio, durante la prigionia di Boba Fett presso il campo dei Sabbipodi, le catene che legano i suoi polsi al palo cambiano disposizione: nel campo largo sono incrociate l''una sull''altra, mentre nel primo piano successivo risultano posizionate in parallelo senza che il personaggio si sia mosso.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1058, 217, '00:24:12', 'Troupe o microfoni visibili', 'Nel terzo episodio, durante la sequenza dell''inseguimento sugli speeder bike colorati della banda di ragazzi mod per le vie di Mos Espa, sulle superfici cromate e negli specchietti di uno dei veicoli si intravede chiaramente il riflesso del rig della telecamera e dell''operatore di ripresa.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(1059, 217, '00:32:05', 'Errori di scena / Posizione', 'Nel terzo episodio, durante l''imboscata notturna di Black Krrsantan nella stanza della vasca di bacta, le ferite e le macchie di sporco sul petto e sul volto di Boba Fett variano vistosamente di intensità e posizione da un''inquadratura all''altra mentre viene trascinato sul pavimento.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1060, 217, '00:41:10', 'Errori di scena / Posizione', 'Nel secondo episodio, durante l''assalto al treno dei Pyke nel deserto di Tatooine, la posizione delle ombre proiettate dai veicoli sulla sabbia cambia istantaneamente da sinistra a destra tra due stacchi di montaggio consecutivi, rivelando che la scena è stata girata in momenti della giornata completamente differenti.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1061, 217, '00:15:30', 'Errori di scena / Posizione', 'Nel quinto episodio, quando il Mandaloriano impugna la Darksaber all''interno della macelleria della stazione spaziale, la posizione della lama rispetto alla sua elsa e l''orientamento dell''impugnatura cambiano angolazione tra il piano d''ascolto frontale e il controcampo da dietro le spalle.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1062, 217, '00:48:15', 'Errori di scena / Posizione', 'Nel finale di stagione (Capitolo 7), mentre Boba Fett cavalca il Rancor lungo le rovine della città, il bastone Gaffi agganciato sulla sua schiena cambia orientamento: la punta ricurva è rivolta verso destra nelle riprese da lontano, ma appare orientata a sinistra nei primi piani a mezzobusto.', TRUE, '2026-10-24T18:58:42.581832', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1065, 161, '00:29:50', 'Errori storici o fattuali', 'Quando il medico spiega a Lucy la natura della sostanza CPH4, la descrive come un prodotto sintetico basato su una molecola naturale prodotta dalle donne alla sesta settimana di gravidanza. In realtà, la CPH4 (6-carbossitetraidropterina) è un metabolita intermedio reale ma non ha alcuna delle proprietà chimiche o biologiche descritte nel film.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1066, 161, '00:32:40', 'Errori di scena / Posizione', 'Nella scena dell''ospedale in cui Lucy si fa operare all''addome per rimuovere il pacchetto di droga, la quantità e l''estensione delle macchie di sangue sulla sua maglietta bianca variano vistosamente da un''inquadratura all''altra.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1067, 161, '00:43:50', 'Troupe o microfoni visibili', 'All''interno del bagno dell''aereo, quando Lucy inizia a perdere la forma fisica e a disintegrarsi, sulle superfici metalliche e lucide del lavello si nota chiaramente il riflesso dell''attrezzatura di illuminazione del set e la sagoma dell''operatore di ripresa.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1068, 161, '00:54:15', 'Errori di scena / Posizione', 'Durante il rocambolesco inseguimento in auto a Parigi a bordo della Peugeot 308 blu, lo specchietto retrovisore sinistro della vettura si spezza dopo un impatto, ma nelle inquadrature successive torna a essere perfettamente integro e montato sulla carrozzeria.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1063, 161, '00:22:40', 'Errori storici o fattuali', 'L''intera premessa del film e la lezione tenuta dal Professor Norman (Morgan Freeman) si basano sul celebre mito secondo cui gli esseri umani utilizzerebbero solo il 10% del proprio cervello. In ambito neuroscientifico si tratta di un falso fattuale ampiamente smentito, poiché le tecniche di neuroimaging mostrano che l''uomo utilizza praticamente tutte le parti del cervello.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1064, 161, '00:17:15', 'Errori di scena / Posizione', 'Nella stanza in cui Lucy viene tenuta prigioniera prima del pestaggio, la posizione delle sue mani ammanettate e le ciocche di capelli che le ricadono sul viso cambiano radicalmente posizione ad ogni stacco di montaggio tra il primo piano e la figura intera.', TRUE, '2026-10-24T19:39:37.558157', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(480, 96, '00:09:15', 'Errori di scena / Posizione', 'Quando il protagonista cade attraverso il pavimento ed entra per la prima volta nel Livello 0, la macchia di umidità sulla carta da parati gialla dietro di lui cambia forma e dimensione tra l''inquadratura panoramica e il primo piano successivo.', TRUE, '2026-09-16T11:56:08.67314', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1070, 151, '00:48:30', 'Errori di scena / Posizione', 'Quando Paul cavalca il Verme delle Sabbie per la prima volta, la sabbia accumulata sulla parte anteriore del suo mantello compare e scompare improvvisamente nelle inquadrature ravvicinate rispetto ai campi lunghi da lontano.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1071, 151, '01:12:10', 'Errori di scena / Posizione', 'Durante l''attacco al mietitore di spezia Harkonnen, la macchia di fuliggine e polvere sulla guancia sinistra di Gurney Halleck varia visibilmente per forma e densità nel passaggio da un piano medio a un primo piano.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1072, 151, '01:35:45', 'Errori di scena / Posizione', 'Nella sequenza dell''arena monocromatica su Giedi Prime, la posizione del sangue sul pugnale di Feyd-Rautha cambia visibilmente direzione e quantità tra due stacchi di montaggio consecutivi.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1073, 151, '02:05:15', 'Errori di scena / Posizione', 'Nel confronto finale nella sala del trono, le mani dell''Imperatore Shaddam IV cambiano posizione sul bastone: nell''inquadratura frontale la mano destra copre la sinistra, mentre nel controcampo la sinistra è posizionata sopra la destra.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1074, 151, '02:22:10', 'Errori di scena / Posizione', 'Nel duello all''ultimo sangue tra Paul e Feyd-Rautha, la ferita da taglio sul fianco di Paul appare visibilmente insanguinata nei primi piani, ma torna ad essere del tutto pulita nelle inquadrature a figura intera.', TRUE, '2026-10-24T21:20:30.061684', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(193, 46, '01:22:40', 'Errori di scena / Posizione', 'Durante la discussione accesa nell''hotel, la sigaretta accesa tenuta da Ginger passa istantaneamente dalla mano destra alla mano sinistra tra due stacchi di montaggio consecutivi.', TRUE, '2026-09-14T13:49:14.103711', NULL, 0, 0, 'IA (Sistema)', 'ia', NULL),
(1075, 170, '00:45:10', 'Errori di scena / Posizione', 'Durante l''esplosione del tunnel di New York, Jasmine si rifugia in una nicchia di servizio insieme al figlio e al cane Boomer. Sebbene le fiamme avvolgano completamente l''esterno e la porta dell''intercapedine, nella scena immediatamente successiva la porta di legno e i personaggi risultano totalmente privi di bruciature o segni di fuliggine.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1076, 170, '00:48:30', 'Errori storici o fattuali', 'Nella celebre sequenza della distruzione dell''Empire State Building, l''edificio viene mostrato posizionato direttamente al centro del viale prospettico. Nella realtà geografica di New York, l''Empire State Building sorge all''angolo tra la 34ª strada e la Fifth Avenue e non al termine di una strada rettilinea.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1077, 170, '01:02:15', 'Errori di scena / Posizione', 'Mentre Steven Hiller (Will Smith) trascina il corpo dell''alieno avvolto nel paracadute attraverso il deserto, la fune di traino cambia visibilmente posizione e tensione tra i primi piani e i campi lunghi, risultando prima tesa sulle spalle e subito dopo allentata a terra.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1078, 170, '01:04:05', 'Errori di scena / Posizione', 'Dopo aver colpito l''alieno con un pugno dicendo la celebre battuta ''Benvenuto sulla Terra!'', Steven Hiller ha un sigaro tra i denti. Al cambio di inquadratura, il sigaro scompare dalla sua bocca per riapparire istantaneamente nella sua mano destra.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1079, 170, '01:24:40', 'Troupe o microfoni visibili', 'All''interno del laboratorio dell''Area 51, durante la scena in cui David Levinson (Jeff Goldblum) si sfoga frustrato facendo cadere i cestini della spazzatura, nel riflesso del pannello di vetro sulla destra della stanza si nota chiaramente l''ombra di un cameraman della troupe in movimento.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1080, 170, '02:08:15', 'Anacronismi', 'Durante il caricamento del virus informatico sulla nave madre aliena, il laptop Apple PowerBook 5300 di David mostra un''interfaccia grafica avanzata con conteggio alla rovescia personalizzato. Per la tecnologia del 1996, era del tutto anacronistico e impossibile compilare un software dotato di GUI complessa e interamente compatibile con un''architettura aliena sconosciuta in poche ore.', TRUE, '2026-10-24T21:24:19.042577', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1081, 170, '00:18:40', 'Errori storici o fattuali', 'Quando le navi aliene entrano simultaneamente nell''atmosfera posizionandosi sopra le principali metropoli del pianeta (tra cui Washington, New York, Los Angeles, Mosca e il Golfo Persico), la piena luce del giorno splende indistintamente su tutte le località, ignorando del tutto i fusi orari e l''alternanza giorno-notte del pianeta Terra.', TRUE, '2026-10-24T21:24:37.773434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(1082, 170, '00:46:15', 'Errori di scena / Posizione', 'Nella sequenza del tunnel di Los Angeles in cui Jasmine cerca salvezza prima dell''esplosione, la porta del locale tecnico di sicurezza cambia stato: nell''inquadratura ravvicinata la donna la spalanca a fatica e vi trascina dentro il cane Boomer lasciando lo spiraglio aperto, ma nello stacco successivo grandangolare, un istante prima dell''impatto del muro di fuoco, la porta risulta completamente chiusa e serrata.', TRUE, '2026-10-24T21:24:37.773434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'ia', NULL),
(3899, 196, '01:15:00', 'Errori di scena / Posizione', 'Durante il grande inseguimento finale, i danni subiti dalla cabina del camion cisterna (ammaccature e parabrezza rotto) variano in modo incoerente da un''inquadratura all''altra.', TRUE, '2026-11-02T10:10:29.638517', 'Mad Max 2 truck damage continuity goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(3900, 198, '01:21:00', 'Errori di scena / Posizione', 'Durante la sequenza della battaglia nel canyon, la posizione dei corpi e dei veicoli sullo sfondo cambia in modo incoerente tra le inquadrature successive, in particolare per quanto riguarda i predatori che attaccano l''autocisterna.', TRUE, '2026-11-02T10:10:36.963319', 'Mad Max Fury Road continuity error canyon battle', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4265, 335, '00:00:00', 'Errori di scena / Posizione', 'Quando Mort Rainey si trova nella sua baita e guarda fuori dalla finestra, il manico della tazza che tiene in mano cambia orientamento tra un''inquadratura e l''altra senza che l''attore abbia cambiato presa.', TRUE, '2026-11-02T14:50:53.821885', 'Secret Window continuity error cup', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4266, 335, '00:00:00', 'Troupe o microfoni visibili', 'In una delle sequenze in cui Mort guida la sua auto lungo la strada di campagna, sul finestrino laterale si intravede per un istante il riflesso dell''attrezzatura di illuminazione della troupe.', TRUE, '2026-11-02T14:50:53.821885', 'Secret Window crew reflection car', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
