(4762, 72, '01:12:15', 'Errori di scena / Posizione', 'All''interno del centro di comando della seconda Morte Nera, la posizione dei pannelli di controllo e lo stato dei bottoni illuminati variano in modo incoerente durante le conversazioni tra l''Imperatore, Darth Vader e gli ufficiali imperiali.', TRUE, '2026-11-02T15:39:05.104963', 'Star Wars Return of the Jedi Death Star control panel continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4821, 90, '00:42:10', 'Errori storici o fattuali', 'Quando Rambo attraversa il confine per entrare in Messico, le indicazioni stradali e la conformazione del valico di frontiera non corrispondono alla geografia reale tra Arizona e Sonora.', TRUE, '2026-11-02T15:40:24.467847', 'Rambo Last Blood Mexico border scene geography', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4626, 6, '01:22:00', 'Errori di scena / Posizione', 'Nella scena in cui Don Vito Corleone viene ferito mentre compra della frutta, la quantità e la disposizione dei frutti nelle cassette e per terra cambiano vistosamente tra un''inquadratura e l''altra mentre il padrino cade a terra.', TRUE, '2026-11-02T15:35:43.903665', 'The Godfather Don Corleone shooting scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4627, 6, '02:15:00', 'Anacronismi', 'Durante la sequenza finale dell''ascesa di Michael Corleone e del regolamento di conti, alcuni dei veicoli che transitano sullo sfondo presentano targhe o dettagli estetici non conformi al periodo storico del 1955.', TRUE, '2026-11-02T15:35:43.903665', 'The Godfather 1955 car anachronism goofs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4628, 6, '00:45:00', 'Errori storici o fattuali', 'La celebre sequenza dell''uccisione di Luca Brasi presenta alcune inesattezze nelle procedure con cui viene tesa l''imboscata all''interno del locale di Sollozzo rispetto alle reali dinamiche della malavita dell''epoca.', TRUE, '2026-11-02T15:35:43.903665', 'The Godfather Luca Brasi garrote scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4629, 6, '01:50:00', 'Troupe o microfoni visibili', 'In una delle inquadrature larghe della sequenza in Sicilia, sulla sinistra dello schermo si intravede per un istante l''ombra di un''asta del microfono boom proiettata contro il muro di pietra.', TRUE, '2026-11-02T15:35:43.903665', 'The Godfather boom mic shadow visible sicily', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4635, 8, '00:15:20', 'Errori di scena / Posizione', 'Durante la festa in onore di Michael Corleone a New York, la posizione del bicchiere di vino tenuto da uno degli ospiti cambia drasticamente tra un''inquadratura in primo piano e il successivo campo medio.', TRUE, '2026-11-02T15:35:53.192048', 'The Godfather Part III party scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4636, 8, '00:42:10', 'Anacronismi', 'Il film è ambientato nel 1979, ma in alcune sequenze di sfondo a New York si notano automobili e modelli di veicoli immatricolati nei primi anni ''80.', TRUE, '2026-11-02T15:35:53.192048', 'The Godfather Part III car anachronism 1979', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4637, 8, '01:22:45', 'Errori storici o fattuali', 'Le procedure e le dinamiche finanziarie legate allo IOR (Istituto per le Opere di Religione) e al Banco Ambrosiano presentano semplificazioni e inesattezze rispetto alla reale cronaca finanziaria italiana dell''epoca a cui la trama si ispira.', TRUE, '2026-11-02T15:35:53.192048', 'The Godfather Part III Vatican bank historical accuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4638, 8, '02:05:30', 'Errori di scena / Posizione', 'Nella scena in cui Michael si sente male e viene soccorso, la disposizione dei farmaci e dei bicchieri sul comodino muta visibilmente da un''angolazione all''altra.', TRUE, '2026-11-02T15:35:53.192048', 'The Godfather Part III Michael health scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4639, 8, '02:40:15', 'Audio / Doppiaggio / Sync', 'Durante i preparativi fuori dal Teatro Massimo a Palermo, il movimento delle labbra di alcuni attori secondari non coincide perfettamente con le battute pronunciate nella traccia audio in lingua inglese.', TRUE, '2026-11-02T15:35:53.192048', 'The Godfather Part III Palermo opera scene lip sync', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4649, 15, '00:12:45', 'Errori di scena / Posizione', 'Quando Orville il velivolo decolla precipitosamente dall''aeroporto improvvisato dei topi, la valigia di Bernie si trova saldamente legata sul dorso dell''albatros, ma nell''inquadratura immediatamente successiva in volo il bagaglio scompare momentaneamente per poi riapparire.', TRUE, '2026-11-02T15:36:13.972335', 'The Rescuers Orville take off scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4650, 15, '00:35:20', 'Errori di scena / Posizione', 'Nella scena in cui Madame Medusa rimprovera Snoops nella sua stanza, il bicchiere sul tavolo cambia posizione e livello di liquido tra un''inquadratura in primo piano e quella a figura intera.', TRUE, '2026-11-02T15:36:13.972335', 'The Rescuers Madame Medusa and Snoops scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4651, 15, '00:52:10', 'Errori di scena / Posizione', 'All''interno della caverna della Baia del Diavolo, quando Penny si china per raccogliere il grande diamante ''L''Occhio del Diavolo'', la pietra preziosa cambia leggermente forma e proporzioni geometriche rispetto alla scena in cui era custodita nello scrigno.', TRUE, '2026-11-02T15:36:13.972335', 'The Rescuers Penny finds the big diamond', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4661, 31, '00:08:45', 'Errori di scena / Posizione', 'Quando Indiana Jones si trova nel tempio nella giungla e prende l''idolo d''oro, la sabbia che versa nel sacchetto per compensare il peso scompare e riappare in quantità differenti tra le inquadrature ravvicinate e quelle a figura intera.', TRUE, '2026-11-02T15:36:31.75119', 'Raiders of the Lost Ark idol sand bag continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4662, 31, '00:22:15', 'Errori di scena / Posizione', 'Nella scena in cui Marion Ravenwood beve a gara nel suo bar in Nepal, il bicchiere che tiene in mano cambia livello di liquido e impugnatura bruscamente tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T15:36:31.75119', 'Raiders of the Lost Ark Marion drinking contest continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
