(4731, 60, '01:45:10', 'Errori di scena / Posizione', 'All''interno della grotta della Fonte della Giovinezza, quando Barbossa estrae la spada avvelenata di Barbanera dal corpo di quest''ultimo, la quantità di sangue sulla lama e sull''impugnatura varia drasticamente tra il primo piano e il campo medio.', TRUE, '2026-11-02T15:38:15.323226', 'Pirates of the Caribbean On Stranger Tides fountain of youth sword scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4742, 65, '00:15:20', 'Errori di scena / Posizione', 'Quando Robin Hood e Little John arrivano al convento di Kirklees, la borsa di cuoio che Robin porta a tracolla cambia spalla tra un''inquadratura a figura intera e il successivo primo piano.', TRUE, '2026-11-02T15:38:36.782657', 'Robin and Marian 1976 convent scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4743, 65, '00:42:10', 'Anacronismi', 'Le spade e le daghe brandite da alcuni dei cavalieri dello Sceriffo di Nottingham presentano else e pomoli stilisticamente più vicini al tardo Medioevo che alla fine del XII secolo.', TRUE, '2026-11-02T15:38:36.782657', 'Robin and Marian sword fight mistakes', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4744, 65, '01:10:45', 'Errori storici o fattuali', 'Il viaggio a cavallo tra la foresta di Sherwood e il mare o i luoghi costieri avviene in tempi cinematograficamente immediati, sebbene le distanze geografiche reali nel nord dell''Inghilterra richiedessero giorni di cammino.', TRUE, '2026-11-02T15:38:36.782657', 'Robin and Marian travel geography error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4745, 65, '01:25:30', 'Errori di scena / Posizione', 'Durante il combattimento finale con le spade tra Robin e lo Sceriffo, la quantità di fango e polvere sui costumi dei due attori varia notevolmente da un''inquadratura larga ai primi piani stretti.', TRUE, '2026-11-02T15:38:36.782657', 'Robin and Marian final duel Sean Connery Robert Shaw', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4787, 79, '01:22:00', 'Troupe o microfoni visibili', 'Durante la scena in cui lo Stormtrooper sbatte la testa contro la porta della sala di controllo della Morte Nera, esaminando attentamente la sequenza e dietro le quinte si può notare brevemente il riflesso dell''attrezzatura di set e dei movimenti della troupe sulla corazza lucida di alcuni soldati imperiali.', TRUE, '2026-11-02T15:39:34.28944', 'Star Wars stormtrooper hits head reflection blooper', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4788, 79, '01:55:00', 'Errori di scena / Posizione', 'Nella sequenza finale della battaglia della Morte Nera, quando Luke guarda fuori dall''abitacolo del suo X-wing, i capelli biondi cambiano visibilmente stile e lunghezza tra un''inquadratura in primo piano e quella successiva con il casco.', TRUE, '2026-11-02T15:39:34.28944', 'Star Wars trench run Luke hair continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4789, 79, '01:05:00', 'Errori di scena / Posizione', 'Quando Obi-Wan Kenobi disattiva il raggio trattore della Morte Nera e viene intercettato da Darth Vader, la spada laser di Vader cambia leggermente lunghezza della lama e impugnatura in alcune inquadrature ravvicinate a causa dell''uso di prop differenti.', TRUE, '2026-11-02T15:39:34.28944', 'Star Wars Obi Wan vs Darth Vader lightsaber prop continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4790, 79, '00:48:00', 'Errori di scena / Posizione', 'Nel momento in cui Han Solo spara al pannello di controllo per impedire agli stormtrooper di entrare nella stanza delle comunicazioni della prigione, il buco provocato dal blaster sul pannello scompare e cambia posizione nelle inquadrature successive.', TRUE, '2026-11-02T15:39:34.28944', 'Star Wars detention block Han Solo shoots control panel error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4791, 79, '00:28:00', 'Troupe o microfoni visibili', 'Nella scena in cui Luke e Obi-Wan incontrano Han Solo e Chewbacca nella cantina di Mos Eisley, in un angolo dello sfondo in basso a destra è visibile per un fotogramma il piede di un operatore di ripresa o di un membro della troupe fuori posto.', TRUE, '2026-11-02T15:39:34.28944', 'Star Wars Mos Eisley cantina crew error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4709, 50, '00:15:30', 'Errori di scena / Posizione', 'Durante la scena del laboratorio in cui Tony Stark e Bruce Banner lavorano sullo scettro di Loki, lo schermo olografico mostra una riga di codice che scompare e riappare tra un cambio d''inquadratura e l''altra.', TRUE, '2026-11-02T15:37:31.61738', 'Avengers Age of Ultron lab scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4710, 50, '00:42:15', 'Troupe o microfoni visibili', 'Nella sequenza dell''attacco al compound di Ulysses Klaue, in un''inquadratura ravvicinata di un mercenario che cade a terra dopo essere stato colpito, si intravede per un istante l''ombra della telecamera sul terreno.', TRUE, '2026-11-02T15:37:31.61738', 'Avengers Age of Ultron camera shadow error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4711, 50, '01:10:00', 'Errori storici o fattuali', 'Durante il flashback di Natasha Romanoff legato al programma della Stanza Rossa, gli strumenti medici mostrati sullo sfondo appartengono a una tecnologia di monitoraggio digitale ben più moderna rispetto agli anni in cui si dovrebbero svolgere gli eventi dell''addestramento.', TRUE, '2026-11-02T15:37:31.61738', 'Avengers Age of Ultron Black Widow flashback error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5042, 179, '00:45:12', 'Errori di scena / Posizione', 'Quando Fred Wilson (Charles Grodin) si avvicina alla gabbia di King Kong sulla nave, la bottiglia che tiene in mano cambia posizione e livello di riempimento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:45:17.982446', 'King Kong 1976 Charles Grodin bottle continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5043, 179, '01:12:30', 'Troupe o microfoni visibili', 'Durante la sequenza nella giungla in cui Jack Prescott (Jeff Bridges) e Dwan (Jessica Lange) scappano dagli indigeni, in basso a destra dell''inquadratura è possibile intravedere brevemente l''ombra di un operatore di macchina sulla vegetazione.', TRUE, '2026-11-02T15:45:17.982446', 'King Kong 1976 crew shadow jungle scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
