(5044, 179, '01:35:45', 'Errori storici o fattuali', 'Nella scena dell''arrivo della nave da carico con King Kong a New York, le manovre di attracco e i rimorchiatori visibili sullo sfondo non corrispondono alle procedure portuali reali dell''epoca per quel tipo di imbarcazione.', TRUE, '2026-11-02T15:45:17.982446', 'King Kong 1976 New York arrival port error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5045, 179, '02:04:10', 'Errori di scena / Posizione', 'Durante il climax sul World Trade Center, le ferite e i graffi sul petto e sulle braccia di King Kong variano in modo evidente per forma e intensità tra le inquadrature in studio con il pupazzo meccanico e quelle con l''attore nel costume.', TRUE, '2026-11-02T15:45:17.982446', 'King Kong 1976 World Trade Center wounds continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5046, 179, '00:22:15', 'Anacronismi', 'Nella sala comando della nave della Petrox, alcuni strumenti di navigazione e monitor sullo sfondo mostrano componenti elettroniche e display digitali non ancora esistenti o diffusi nel periodo in cui è ambientata la storia.', TRUE, '2026-11-02T15:45:17.982446', 'King Kong 1976 ship bridge equipment anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5080, 195, '00:04:15', 'Errori di scena / Posizione', 'Durante la sequenza in cui la polizia interroga il Nightrider dopo l''incidente iniziale, la quantità di sangue sulla faccia del criminale varia visibilmente tra un primo piano e l''inquadratura larga.', TRUE, '2026-11-02T15:46:04.122324', 'Mad Max 1979 Nightrider scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5081, 195, '00:18:30', 'Errori di scena / Posizione', 'Quando Max guida la sua auto di famiglia con Jessie e Sprog, la posizione del peluche appeso allo specchietto retrovisore cambia ripetutamente tra le riprese interne e quelle esterne.', TRUE, '2026-11-02T15:46:04.122324', 'Mad Max 1979 car interior continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5082, 195, '00:26:00', 'Troupe o microfoni visibili', 'In una delle inquadrature ampie lungo la strada desertica, è possibile intravedere brevemente il riflesso della telecamera o del mezzo di supporto sulla carrozzeria lucida di un veicolo della polizia.', TRUE, '2026-11-02T15:46:04.122324', 'Mad Max 1979 camera reflection error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5083, 195, '00:41:10', 'Errori di scena / Posizione', 'Durante il saccheggio della cittadina da parte della gang di Toecutter, un vetro di una finestra viene distrutto ma, nell''inquadratura immediatamente successiva da angolazione diversa, il vetro appare nuovamente intatto prima di rompersi di nuovo.', TRUE, '2026-11-02T15:46:04.122324', 'Mad Max 1979 town scene window break continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5084, 195, '00:52:45', 'Errori di scena / Posizione', 'Quando Goose cade con la moto dopo il sabotaggio della sua ruota, il casco che indossa a terra differisce leggermente per dettagli e finiture rispetto a quello indossato durante la corsa precedente.', TRUE, '2026-11-02T15:46:04.122324', 'Mad Max 1979 Goose crash motorcycle continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5085, 195, '01:05:20', 'Errori storici o fattuali', 'Le ferite e le bende sul corpo di Goose all''ospedale cambiano posizione e consistenza estetica tra la scena in cui Max va a trovarlo e le inquadrature successive.', TRUE, '2026-11-02T15:46:04.122324', 'Mad Max 1979 hospital scene continuity Goose', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5086, 195, '01:18:00', 'Errori di scena / Posizione', 'Nella scena in cui Max indossa la sua uniforme di pelle nera e si prepara nella base della MFP, gli stivali cambiano tipo di fibbia e suola tra un primo piano e la figura intera.', TRUE, '2026-11-02T15:46:04.122324', 'Mad Max 1979 Max getting dressed leather suit continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5117, 202, '00:15:20', 'Troupe o microfoni visibili', 'Durante la sequenza del treno che trasporta Katniss e Peeta verso Capitol City, in un''inquadratura in cui si riflettono i finestrini, è possibile intravedere brevemente l''ombra di un operatore della troupe con una cinepresa.', TRUE, '2026-11-02T15:46:36.954654', 'The Hunger Games crew reflection train scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5118, 202, '00:48:12', 'Errori di scena / Posizione', 'Durante la sessione di addestramento in cui Katniss si esercita a lanciare i coltelli, i bersagli colpiti mostrano i coltelli conficcati con inclinazioni differenti tra l''inquadratura larga e il primo piano ravvicinato dell''arma.', TRUE, '2026-11-02T15:46:36.954654', 'The Hunger Games knife throwing training scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5119, 202, '01:12:45', 'Errori di scena / Posizione', 'Nel momento in cui Katniss si arrampica sull''albero per sfuggire ai Tributi Favoriti che la braccano, lo zaino che indossa scompare e riappare o cambia la disposizione delle cinghie tra una ripresa dal basso e la vista dall''alto.', TRUE, '2026-11-02T15:46:36.954654', 'The Hunger Games Katniss tree climbing backpack continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5120, 202, '01:35:10', 'Errori di scena / Posizione', 'Quando Katniss si trova all''interno della Cornucopia per recuperare la medicina per Peeta, il numero e la posizione delle sacche e delle attrezzature mediche intorno a lei variano visibilmente quando la telecamera cambia angolazione.', TRUE, '2026-11-02T15:46:36.954654', 'The Hunger Games feast at the cornucopia scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5134, 207, '00:15:32', 'Errori di scena / Posizione', 'Quando Gru entra nel suo ufficio e parla con il Dr. Nefario, la tazza di caffè sulla scrivania cambia posizione e inclinazione tra le inquadrature successive.', TRUE, '2026-11-02T15:46:54.895349', 'Despicable Me Gru office scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4738, 64, '00:25:12', 'Troupe o microfoni visibili', 'Durante la sequenza in cui i fuorilegge catturano il carretto con le provviste nella foresta, in un campo medio si intravede brevemente l''ombra di un operatore di ripresa proiettata sul fogliame a sinistra.', TRUE, '2026-11-02T15:38:32.342815', 'The Adventures of Robin Hood crew shadow goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4739, 64, '00:48:30', 'Errori di scena / Posizione', 'Nel banchetto al castello di Nottingham, il boccale di vino tenuto in mano da Sir Guy di Gisborne cambia continuamente di livello e posizione tra un''inquadratura ravvicinata e il campo lungo successivo.', TRUE, '2026-11-02T15:38:32.342815', 'The Adventures of Robin Hood continuity goblet', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4740, 64, '01:12:05', 'Errori storici o fattuali', 'I cavalli utilizzati nelle cariche della cavalleria normanna sono in parte razze moderne (come il Quarter Horse e incroci selezionati nel XX secolo), facilmente riconoscibili per corporatura rispetto ai destrieri pesanti medievali.', TRUE, '2026-11-02T15:38:32.342815', 'The Adventures of Robin Hood historical horse breed error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4741, 64, '01:35:40', 'Errori di scena / Posizione', 'Durante il duello finale con le spade tra Robin Hood e Sir Guy di Gisborne, la spada di Robin perde la guardia in un dettaglio ravvicinato per poi riapparire integra nell''inquadratura successiva.', TRUE, '2026-11-02T15:38:32.342815', 'The Adventures of Robin Hood sword duel continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4775, 75, '00:15:20', 'Errori di scena / Posizione', 'Nel momento in cui Palpatine viene liberato dalle catene sulla nave di Grievous, Anakin taglia i vincoli metallici; nell''inquadratura successiva i pezzi di metallo tagliati cambiano forma e posizione sul pavimento.', TRUE, '2026-11-02T15:39:19.419087', 'Star Wars Episode III Anakin cuts Palpatine restraints goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4776, 75, '00:42:10', 'Errori di scena / Posizione', 'Nel tempio Jedi, durante il colloquio tra Yoda e Anakin in cui si parla della premonizione di Padmé, la ciocca di capelli di Anakin cambia visibilmente posizione sulla sua fronte tra un taglio di montaggio e l''altro.', TRUE, '2026-11-02T15:39:19.419087', 'Star Wars Episode III Yoda Anakin temple continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4777, 75, '01:05:40', 'Errori di scena / Posizione', 'Durante l''incontro nel corridoio in cui Obi-Wan Kenobi informa Padmé della caduta di Anakin al lato oscuro, le pieghe e la posizione del mantello di Padmé variano notevolmente tra un''inquadratura e il controcampo.', TRUE, '2026-11-02T15:39:19.419087', 'Star Wars Episode III Obi Wan Padme Mustafar preparation goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4778, 75, '01:22:15', 'Errori di scena / Posizione', 'Su Mustafar, mentre Anakin e Obi-Wan combattono spostandosi all''interno della struttura mineraria, i tubi di vapore sullo sfondo che vengono danneggiati cambiano stato di integrità nei cambi d''inquadratura.', TRUE, '2026-11-02T15:39:19.419087', 'Star Wars Episode III Anakin vs Obi Wan industrial interior continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4779, 75, '01:38:50', 'Errori di scena / Posizione', 'Sulle rive del fiume di lava di Mustafar, quando Obi-Wan si posiziona sulla riva elevata dicendo di avere la posizione di vantaggio (''I have the high ground''), la quantità di cenere e detriti vulcanici sugli stivali di Anakin varia tra i primi piani e i campi lunghi.', TRUE, '2026-11-02T15:39:19.419087', 'Star Wars Episode III I have the high ground boot ash continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5047, 180, '00:15:42', 'Errori di scena / Posizione', 'Quando la troupe sale a bordo della Venture, la quantità di bagagli e casse sul ponte cambia visibilmente di posizione e numero tra l''inquadratura larga d''insieme e i primi piani sui singoli attori.', TRUE, '2026-11-02T15:45:21.976539', 'King Kong 2005 board the Venture continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5048, 180, '00:48:20', 'Anacronismi', 'Durante le scene ambientate nel 1933 sull''isola, alcune delle attrezzature fotografiche e di illuminazione di Carl Denham mostrano dettagli di componenti meccaniche e finiture che sarebbero state introdotte solo decenni più tardi.', TRUE, '2026-11-02T15:45:21.976539', 'King Kong 2005 equipment anachronism Skull Island', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5049, 180, '01:12:05', 'Errori di scena / Posizione', 'Durante la fuga dagli insetti giganti nella fossa dei财 (The Pit), la torcia elettrica in mano a uno dei marinai si accende e si spegne alternativamente tra un cambio di inquadratura e l''altro senza che il personaggio prema l''interruttore.', TRUE, '2026-11-02T15:45:21.976539', 'King Kong 2005 the pit bug attack flashlight continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5050, 180, '01:35:50', 'Troupe o microfoni visibili', 'Nelle sequenze della giungla in cui i personaggi corrono inseguiti dai dinosauri, in un fotogramma riflesso nell''acqua fangosa è possibile intravedere brevemente la sagoma di un operatore di ripresa con attrezzatura moderna.', TRUE, '2026-11-02T15:45:21.976539', 'King Kong 2005 crew visible reflection jungle', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5051, 180, '02:22:15', 'Errori storici o fattuali', 'Durante la sequenza in cui Kong viene esposto a Broadway nel 1933, le locandine e i cartelloni promozionali all''esterno del teatro utilizzano font tipografici e impostazioni grafiche tipiche della fine degli anni ''40 anziché dell''epoca della Depressione.', TRUE, '2026-11-02T15:45:21.976539', 'King Kong 2005 Broadway theater poster font error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5087, 196, '00:12:45', 'Troupe o microfoni visibili', 'Durante una delle sequenze all''interno del compound, in un''inquadratura ravvicinata su uno dei personaggi secondari, si intravede brevemente il braccio di un microfono a boom riflettersi sulla carrozzeria lucida di un veicolo parcheggiato sullo sfondo.', TRUE, '2026-11-02T15:46:09.120198', 'Mad Max 2 boom mic reflection error scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5088, 196, '00:35:20', 'Errori di scena / Posizione', 'Quando Max riceve la benzina e i proiettili dalla comunità, il fucile a canne mozze che tiene in mano cambia angolazione e posizione della cinghia tra un''inquadratura frontale e il controcampo.', TRUE, '2026-11-02T15:46:09.120198', 'Mad Max 2 shotgun continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5089, 196, '00:54:10', 'Errori di scena / Posizione', 'Durante l''attacco dei predoni al perimetro della raffineria, un motociclista cade rovinosamente a terra sollevando molta polvere; nell''inquadratura immediatamente successiva, la moto scivola via ma la posizione del corpo dello stuntman è visibilmente diversa e più avanzata rispetto all''impatto.', TRUE, '2026-11-02T15:46:09.120198', 'Mad Max 2 motorcycle stunt continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5090, 196, '01:12:30', 'Troupe o microfoni visibili', 'In una delle inquadrature ampie nel deserto durante l''inseguimento della petroliera, si nota brevemente sulla sabbia l''ombra del veicolo con la cinepresa utilizzata per le riprese in movimento.', TRUE, '2026-11-02T15:46:09.120198', 'Mad Max 2 camera shadow visible error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5091, 196, '01:25:15', 'Errori di scena / Posizione', 'Nelle scene finali dell''inseguimento, il trucco sul viso di Max (ferite e sangue finto) varia in modo evidente per intensità e posizione della crosta sulla guancia sinistra tra i vari cambi di inquadratura.', TRUE, '2026-11-02T15:46:09.120198', 'Mad Max 2 Mel Gibson makeup continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4746, 66, '00:00:00', 'Troupe o microfoni visibili', 'Durante una delle scene di battaglia nella foresta, in un''inquadratura ampia, è possibile intravedere brevemente l''ombra di un microfono a boom sul terreno o su un tronco d''albero.', TRUE, '2026-11-02T15:38:42.017806', 'Robin Hood Prince of Thieves crew boom mic visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4747, 66, '00:00:00', 'Errori di scena / Posizione', 'Nella scena in cui Robin scappa dalle segrete di Gerusalemme all''inizio del film, le catene ai suoi polsi cambiano lunghezza e modo di essere legate tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:38:42.017806', 'Robin Hood Prince of Thieves Jerusalem escape continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4748, 66, '00:00:00', 'Errori storici o fattuali', 'La mappa dell''Inghilterra mostrata nel film presenta confini e divisioni amministrative (come contee o nomi di località) che risalgono a epoche storiche molto posteriori al XII secolo.', TRUE, '2026-11-02T15:38:42.017806', 'Robin Hood Prince of Thieves historical map error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
