(4823, 90, '00:15:20', 'Errori di scena / Posizione', 'Quando Rambo si trova nel laboratorio sotterraneo a saldare e preparare i suoi strumenti, la posizione degli attrezzi sul bancone cambia visibilmente tra un''inquadratura ravvicinata e il campo medio.', TRUE, '2026-11-02T15:40:24.467847', 'Rambo Last Blood continuity error workbench', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4824, 90, '00:42:10', 'Errori storici o fattuali', 'Le targhe delle automobili della polizia messicana e dei veicoli locali non seguono il formato reale dello stato di Sonora in cui la scena è presumibilmente ambientata.', TRUE, '2026-11-02T15:40:24.467847', 'Rambo Last Blood Mexico license plate error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4825, 90, '01:05:45', 'Errori di scena / Posizione', 'Durante la sequenza in cui Rambo guida il suo pick-up verso il ranch dopo l''attacco iniziale, i danni alla carrozzeria e ai fari subiti durante la fuga variano da un''inquadratura all''altra.', TRUE, '2026-11-02T15:40:24.467847', 'Rambo Last Blood truck damage continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4826, 90, '01:22:30', 'Errori storici o fattuali', 'Il modo in cui vengono descritte e rappresentate le rotte di transito e i controlli doganali tra Stati Uniti e Messico presenta notevoli inesattezze rispetto alle procedure reali di confine.', TRUE, '2026-11-02T15:40:24.467847', 'Rambo Last Blood border crossing error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4858, 117, '00:15:32', 'Errori di scena / Posizione', 'Durante la scena in cui il professor Keating cammina sui banchi dell''aula per mostrare ai ragazzi come cambiare prospettiva, i libri e i quaderni sul banco di Charlie Dalton cambiano disposizione e apertura tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:41:37.050692', 'Dead Poets Society Keating desk scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4859, 117, '00:42:15', 'Errori di scena / Posizione', 'Nel dormitorio, mentre i ragazzi parlano di nascosto ascoltando la radio e fumando, il bicchiere tenuto in mano da Neil Perry si svuota e si riempie parzialmente o cambia posizione tra i vari cambi di inquadratura.', TRUE, '2026-11-02T15:41:37.050692', 'Dead Poets Society dorm room scene goofs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4860, 117, '01:10:20', 'Anacronismi', 'Ambientato nel 1959, in alcune scene all''aperto nei pressi del collegio si possono intravedere nel traffico di sfondo o parcheggiate automobili con targhe e dettagli di anni successivi, sebbene la produzione abbia cercato di mantenere il rigore storico.', TRUE, '2026-11-02T15:41:37.050692', 'Dead Poets Society historical inaccuracies cars', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(4861, 117, '01:28:40', 'Errori storici o fattuali', 'Durante la discussione sulla poesia nel cortile della scuola, l''edizione e le rilegature di alcuni libri tenuti in mano dagli studenti riflettono standard editoriali tipici degli anni ''70 e ''80 piuttosto che del periodo fine anni ''50.', TRUE, '2026-11-02T15:41:37.050692', 'Dead Poets Society book props mistakes', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4877, 122, '01:21:00', 'Errori di scena / Posizione', 'Durante la sparatoria sul tetto del palazzo, l''Agente Jones spara contro Neo da distanza ravvicinata. In un''inquadratura in cui Neo schiva i proiettili piegandosi all''indietro, la giacca lunga di Neo si apre mostrando chiaramente l''imbracatura e i cavi di sostegno utilizzati per la sequenza di stunt, modificando la forma e il drappeggio del cappotto tra un taglio e l''altro.', TRUE, '2026-11-02T15:41:58.969074', 'Matrix rooftop bullet dodge goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4878, 122, '00:43:15', 'Errori di scena / Posizione', 'Nella scena in cui Tank carica il programma di addestramento al combattimento nel cervello di Neo, la tastiera del computer usata da Tank mostra il cavo disconnesso o inserito in porte differenti nelle diverse inquadrature ravvicinate e a campo largo.', TRUE, '2026-11-02T15:41:58.969074', 'Matrix training program computer keyboard continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4879, 122, '00:15:30', 'Audio / Doppiaggio / Sync', 'Durante la sequenza nel cubicolo dell''ufficio della Metacortex, quando Neo riceve il pacchetto con il telefono cellulare dalla FedEx, l''audio del coperchio della scatola che si apre e della carta che si stropiccia non coincide perfettamente con i movimenti delle mani di Keanu Reeves nelle riprese da angolazioni diverse.', TRUE, '2026-11-02T15:41:58.969074', 'Matrix office delivery phone scene sync error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4880, 122, '01:34:00', 'Troupe o microfoni visibili', 'Nella scena finale in cui Neo si allontana camminando tra la folla e indossa gli occhiali da sole prima di sollevarsi in volo, riflettersi sulle lenti degli occhiali dei passanti o sulla carrozzeria di alcune auto in sosta si intravedono brevemente sagome di membri della troupe con attrezzatura di illuminazione.', TRUE, '2026-11-02T15:41:58.969074', 'Matrix ending scene reflection crew error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4894, 127, '01:15:00', 'Errori di scena / Posizione', 'Durante la sequenza in cui Jill si trova all''interno del saloon a Flagstone e suona il pianoforte, il bicchiere posizionato sul bordo dello strumento cambia posizione e livello di liquido tra un''inquadratura e l''altra del montaggio alternato.', TRUE, '2026-11-02T15:42:24.863084', 'C''era una volta il West saloon piano scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4895, 127, '02:10:00', 'Troupe o microfoni visibili', 'Nel corso della sparatoria finale tra i pistoleri di Frank e Armonica presso la struttura in costruzione a Sweetwater, in un campo medio si intravede per un istante l''ombra della giraffa del microfono boom proiettata sulla parete di legno.', TRUE, '2026-11-02T15:42:24.863084', 'Once Upon a Time in the West boom mic shadow error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4896, 127, '00:45:00', 'Anacronismi', 'In alcune inquadrature esterne ambientate nel deserto, sullo sfondo si notano linee di trasmissione elettrica moderna o pali telefonici che non appartengono al periodo storico in cui è ambientato il western.', TRUE, '2026-11-02T15:42:24.863084', 'C''era una volta il West anachronism power lines', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4897, 127, '00:05:12', 'Errori di scena / Posizione', 'Durante l''attesa alla stazione ferroviaria di Cattle Corner, i tre pistoleri appostati passano il tempo in modi diversi. La posizione delle mani e del fucile imbracciato da uno di essi cambia nettamente tra un''inquadratura e il rispettivo controcampo.', TRUE, '2026-11-02T15:42:24.863084', 'Once Upon a Time in the West train station opening scene mistake continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4898, 127, '00:32:45', 'Errori di scena / Posizione', 'Quando Jill McBain scende dal treno a Flagstone e cerca un mezzo per raggiungere Sweetwater, la valigia che trasporta cambia di mano e orientamento tra un primo piano e l''inquadratura a figura intera.', TRUE, '2026-11-02T15:42:24.863084', 'Once Upon a Time in the West Claudia Cardinale train arrival scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4899, 127, '01:15:20', 'Anacronismi', 'In alcune scene ambientate nelle zone brulle del West e nei pressi dei cantieri ferroviari, si possono scorgere sullo sfondo tracce di strade sterrate moderne o solchi lasciati da pneumatici di autoveicoli contemporanei estranei al periodo storico.', TRUE, '2026-11-02T15:42:24.863084', 'Once Upon a Time in the West anachronism background mistakes', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4835, 97, '01:25:00', 'Errori di scena / Posizione', 'Durante le riprese della sequenza della crocifissione, in un campo medio che mostra la folla e le croci sullo sfondo, il cielo passa bruscamente da una forte luce solare a un cielo coperto e cupo per poi tornare luminoso nell''inquadratura successiva, evidenziando le riprese effettuate in giorni diversi senza un corretto raccordo di luce.', TRUE, '2026-11-02T15:40:35.362694', 'Ben-Hur 1925 crucifixion scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4836, 98, '01:25:00', 'Errori di scena / Posizione', 'Durante la sequenza in cui Quinto Arrio viene salvato da Ben-Hur in mare dopo lo speronamento della nave, la posizione del console romano in acqua e il modo in cui galleggia variano visibilmente tra un''inquadratura e l''altra, alternando momenti in cui affonda ad altri in cui è perfettamente a galla.', TRUE, '2026-11-02T15:40:39.02014', 'Ben-Hur naval battle sinking scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4837, 98, '02:10:00', 'Errori di scena / Posizione', 'Nella scena in cui Ben-Hur incontra sua madre e sua sorella dopo che sono state liberate dalla valle dei lebbrosi, la quantità di sporco e le macchie di fango sui loro volti e abiti cambiano drasticamente nei cambi di inquadratura tra i primi piani e i campi medi.', TRUE, '2026-11-02T15:40:39.02014', 'Ben-Hur lepers mother and sister scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4838, 98, '03:20:00', 'Anacronismi', 'Nei titoli di coda iniziali e in alcune sequenze di massa, vengono impiegate tecniche di stampa e caratteri tipografici che richiamano stili moderni non coerenti con i metodi di scrittura o incisione in pietra dell''epoca romana del I secolo.', TRUE, '2026-11-02T15:40:39.02014', 'Ben-Hur opening credits historical anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4839, 98, '00:45:00', 'Errori storici o fattuali', 'Durante le scene delle galere, i rematori sono incatenati ai banchi in modo tale che, se la nave fosse affondata come poi accade, sarebbe stato totalmente impossibile per loro liberarsi in tempo, sebbene nel film molti riescano a salvarsi o a essere slegati in pochi secondi.', TRUE, '2026-11-02T15:40:39.02014', 'Ben-Hur galley slaves chained under deck error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4840, 98, '01:50:00', 'Troupe o microfoni visibili', 'Nella sequenza della corsa delle bighe, in un''inquadratura ravvicinata sullo sfondo sabbioso e tra le tribune, si intravede brevemente l''ombra di un operatore di ripresa con la cinepresa montata su un braccio mobile.', TRUE, '2026-11-02T15:40:39.02014', 'Ben-Hur chariot race crew shadow visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4841, 101, '00:00:00', 'Errori di scena / Posizione', 'Durante le sequenze iniziali in cui Jonathan Harker saluta Lucy prima di partire per la Transilvania, la sciarpa indossata da Isabelle Adjani cambia leggermente posizione e nodi tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:40:53.26694', 'Nosferatu Phantom der Nacht 1979 continuity error Jonathan Lucy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4857, 115, '01:05:00', 'Errori di scena / Posizione', 'Nel negozio di pegni, quando Zed e Maynard scelgono la mazza da baseball e lo sfollagente prima di abusare di Marsellus Wallace, gli oggetti impugnati e la loro posizione cambiano leggermente tra i diversi stacchi di inquadratura.', TRUE, '2026-11-02T15:41:28.544778', 'Pulp Fiction pawn shop scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4913, 139, '01:22:15', 'Errori di scena / Posizione', 'Durante la sequenza in cui il treno deraglia e attraversa le strade di Kyoto, la posizione del cappello e della sciarpa indossati da Ladybug variano visibilmente tra un''inquadratura e l''altra, passando dall''essere perfettamente sistemati a completamente bagnati e disordinati senza soluzione di continuità logica.', TRUE, '2026-11-02T15:42:58.375311', 'Bullet Train crash scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4914, 139, '00:45:30', 'Troupe o microfoni visibili', 'Nella scena in cui Lemon e Tangerine discutono nei corridoi dello Shinkansen, in un riflesso sul finestrino laterale è possibile scorgere brevemente la sagoma di un operatore della troupe con una telecamera di supporto.', TRUE, '2026-11-02T15:42:58.375311', 'Bullet Train crew reflection visible goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4915, 140, '00:00:00', 'Anacronismi', 'Nel film ambientato nel 1921, in alcune inquadrature esterne delle strade di New York compaiono modelli di automobili con targhe e dettagli di immatricolazione appartenenti a un''epoca successiva.', TRUE, '2026-11-02T15:43:01.895719', 'The Immigrant 2013 car anachronism scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4965, 153, '00:03:15', 'Errori di scena / Posizione', 'Durante la riunione nella stanza di Andy, il calendario appeso alla parete cambia il mese visualizzato o la disposizione dei giorni tra un cambio di inquadratura e l''altra.', TRUE, '2026-11-02T15:43:58.238009', 'Toy Story Andy''s room meeting calendar continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4966, 153, '00:25:40', 'Errori di scena / Posizione', 'Alla stazione di servizio Pizza Planet, quando Buzz sale sul retro del camion, la posizione degli attrezzi nella cassetta sul pianale cambia leggermente tra l''inquadratura larga e il primo piano.', TRUE, '2026-11-02T15:43:58.238009', 'Toy Story Pizza Planet truck scene continuity goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4967, 153, '00:48:10', 'Errori di scena / Posizione', 'Nella camera di Sid, mentre Woody cerca di farsi notare dalla finestra con la lente d''ingrandimento, la posizione degli oggetti sul tavolo da lavoro di Sid varia inspiegabilmente nei diversi stacchi di montaggio.', TRUE, '2026-11-02T15:43:58.238009', 'Toy Story Sid''s room desk objects continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4968, 153, '00:03:15', 'Errori di scena / Posizione', 'Durante la riunione di compleanno nella stanza di Andy, il disegno del dinosauro attaccato all''armadio cambia leggermente posizione e inclinazione tra l''inquadratura generale dei giocattoli e i primi piani sui singoli personaggi.', TRUE, '2026-11-02T15:43:58.238009', 'Toy Story Andy''s room meeting scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4969, 153, '00:25:40', 'Errori di scena / Posizione', 'Nella stazione di servizio Dinoco, quando Woody e Buzz lottano sul pavimento prima dell''arrivo del camion della Pizza Planet, i cartelli pubblicitari sullo sfondo cambiano posizione tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:43:58.238009', 'Toy Story gas station fight scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4970, 153, '00:52:10', 'Errori di scena / Posizione', 'Nella camera degli orrori di Sid, quando Woody parla con i giocattoli mutanti nel cortile illuminato dalla luce della torcia, gli attrezzi da giardino appoggiati al muro cambiano disposizione nei vari cambi di inquadratura.', TRUE, '2026-11-02T15:43:58.238009', 'Toy Story Sid''s room mutants scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4971, 153, '01:10:05', 'Errori di scena / Posizione', 'Durante l''inseguimento finale al camion in movimento, le scatole di cartone che cadono dal retro del furgone cambiano forma, dimensione e quantità a seconda che vengano inquadrate frontalmente o di profilo.', TRUE, '2026-11-02T15:43:58.238009', 'Toy Story moving truck chase scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4972, 154, '00:03:15', 'Errori di scena / Posizione', 'Quando Woody cerca il cappello nella stanza di Andy, la scatola sulla mensola cambia posizione tra l''inquadratura in cui Woody guarda in alto e quella successiva in primo piano.', TRUE, '2026-11-02T15:44:03.541647', 'Toy Story 2 Woody looking for hat continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4842, 103, '00:15:20', 'Errori di scena / Posizione', 'Durante l''imboscata nella foresta all''inizio del film, il modo in cui i soldati britannici cadono e tengono i loro moschetti cambia visibilmente tra un''inquadratura e l''altra, con le armi che appaiono e scompaiono accanto ai corpi caduti nei cambi di campo.', TRUE, '2026-11-02T15:41:00.370913', 'The Last of the Mohicans ambush scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4843, 103, '00:48:10', 'Errori di scena / Posizione', 'Nella scena in cui il maggiore Heyward parla all''interno dell''accampamento britannico, la tazza che tiene in mano passa continuamente dalla mano destra alla sinistra e viceversa tra i tagli di montaggio dei primi piani.', TRUE, '2026-11-02T15:41:00.370913', 'The Last of the Mohicans Heyward cup continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4844, 103, '01:12:45', 'Errori storici o fattuali', 'La resa di Fort William Henry e i successivi eventi storici vengono fortemente compressi e romanzati rispetto ai fatti reali del 1757, inclusi i tempi di marcia e la presunta vulnerabilità totale della guarnigione.', TRUE, '2026-11-02T15:41:00.370913', 'The Last of the Mohicans Fort William Henry historical inaccuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4845, 103, '01:34:00', 'Troupe o microfoni visibili', 'Durante la drammatica sequenza della marcia dei sopravvissuti fuori da Forte William Henry, in un''inquadratura grandangolare sui lati della colonna si intravede per un istante il movimento di un membro della troupe in abiti moderni ai margini della boscaglia.', TRUE, '2026-11-02T15:41:00.370913', 'The Last of the Mohicans crew member visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4846, 103, '01:52:30', 'Errori di scena / Posizione', 'Nella scena della scalata della parete rocciosa da parte dei protagonisti prima dell''epilogo, le ferite e le macchie di sangue sul viso e sui vestiti di Occhio di Falco variano di intensità e posizione da un''inquadratura all''altra.', TRUE, '2026-11-02T15:41:00.370913', 'The Last of the Mohicans cliff climb continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4847, 109, '00:12:45', 'Errori di scena / Posizione', 'Quando Ace Ventura si trova nel suo ufficio all''inizio del film e riceve la visita del rappresentante della colonia britannica, la tazza da tè che tiene in mano cambia posizione e livello di riempimento tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T15:41:06.227077', 'Ace Ventura When Nature Calls office scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4848, 109, '00:45:20', 'Troupe o microfoni visibili', 'Durante la sequenza in cui Ace esplora il mercato all''aperto alla ricerca di indizi, in alto a sinistra dello schermo è possibile intravedere brevemente l''ombra di un microfono boom che si muove lungo il muro di una bancarella.', TRUE, '2026-11-02T15:41:06.227077', 'Ace Ventura When Nature Calls boom mic visible market scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4849, 109, '01:05:10', 'Errori di scena / Posizione', 'Nel corso della discussione tra Ace e i capi delle due tribù rivali, il bastone cerimoniale retto dall''anziano Wachati passa inspiegabilmente dalla mano destra alla sinistra senza che vi sia continuità nell''azione di transizione.', TRUE, '2026-11-02T15:41:06.227077', 'Ace Ventura When Nature Calls tribal meeting continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4850, 109, '00:00:00', 'Errori di scena / Posizione', 'Durante la scena in cui Ace Ventura si trova nel bagno dell''aereo, il tovagliolo di carta che usa per asciugarsi cambia posizione e forma piegata tra le varie inquadrature ravvicinate e a campo largo.', TRUE, '2026-11-02T15:41:06.227077', 'Ace Ventura When Nature Calls airplane bathroom scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4851, 109, '00:00:00', 'Troupe o microfoni visibili', 'Nella sequenza in cui Ace entra nella tenda del consulente britannico e si muove concitatamente, è possibile intravedere brevemente il riflesso della telecamera e di un operatore sulla superficie lucida di un oggetto di scena in metallo.', TRUE, '2026-11-02T15:41:06.227077', 'Ace Ventura When Nature Calls crew reflection mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4852, 109, '00:00:00', 'Errori storici o fattuali', 'Il film fa riferimento a una tribù immaginaria (i Wachati e i Wachootoo) in una regione non ben definita dell''Africa, ma la flora e la fauna mostrate mescolano specie asiatiche e sudamericane in modo geograficamente impossibile per il continente africano.', TRUE, '2026-11-02T15:41:06.227077', 'Ace Ventura When Nature Calls geographical errors Africa', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4853, 110, '01:23:45', 'Troupe o microfoni visibili', 'Durante una delle sequenze di battaglia, in basso a destra dello schermo, è possibile intravedere brevemente l''ombra di un operatore di ripresa e del braccio di un microfono boom proiettata sul terreno fangoso.', TRUE, '2026-11-02T15:41:11.749083', 'Braveheart crew microphone visible goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4854, 110, '02:10:15', 'Errori di scena / Posizione', 'Nel corso della scena in cui William Wallace viene torturato prima dell''esecuzione, le ferite e i tagli sul suo viso cambiano visibilmente posizione e intensità di sangue tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:41:11.749083', 'Braveheart execution scene continuity error makeup', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4855, 110, '00:45:20', 'Errori di scena / Posizione', 'Durante un dialogo all''interno di una tenda, il boccale di idromele tenuto da un nobile scozzese passa inspiegabilmente dalla mano destra alla mano sinistra e viceversa a ogni cambio di inquadratura.', TRUE, '2026-11-02T15:41:11.749083', 'Braveheart cup continuity error scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
