INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(4962, 152, '00:15:30', 'Errori di scena / Posizione', 'Durante i festeggiamenti di Capodanno nel salone principale, il bicchiere di champagne tenuto da un passeggero cambia mano tra un''inquadratura e l''altra senza che vi sia il tempo materiale per compiere il gesto.', TRUE, '2026-11-02T15:43:53.747306', 'Poseidon 2006 ballroom continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4963, 152, '00:42:15', 'Troupe o microfoni visibili', 'Nella scena in cui i sopravvissuti camminano lungo un corridoio inclinato della nave, si intravede brevemente l''ombra di un microfono boom sulla parete metallica a sinistra dell''inquadratura.', TRUE, '2026-11-02T15:43:53.747306', 'Poseidon 2006 boom mic visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4964, 152, '01:05:40', 'Errori storici o fattuali', 'Nel descrivere la fisica dell''onda anomala (rogue wave), i personaggi parlano di un fenomeno sismico o maremoto in mare aperto, sebbene le onde anomale oceaniche siano solitamente causate da forti correnti che incontrano onde anomale e non da terremoti sottomarini in quella specifica area.', TRUE, '2026-11-02T15:43:53.747306', 'Poseidon 2006 wave scientific error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5023, 168, '00:12:45', 'Errori di scena / Posizione', 'Quando Anton Chigurh usa il fucile da macello pneumatico per aprire la serratura della porta dell''ufficio, la bombola di gas collegata cambia leggermente posizione e orientamento rispetto al tubo tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:44:49.55669', 'No Country for Old Men Chigurh cattle gun motel scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5024, 168, '00:35:20', 'Anacronismi', 'Nella scena in cui Llewelyn Moss acquista gli stivali da un adolescente sulla strada, lo sfondo mostra vari cartelli stradali e modelli di pick-up che presentano riflettori e dettagli di omologazione stradale introdotti negli Stati Uniti solo verso la fine degli anni ''90.', TRUE, '2026-11-02T15:44:49.55669', 'No Country for Old Men Llewelyn buys boots scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5025, 168, '01:04:15', 'Errori storici o fattuali', 'Durante la sequenza dell''inseguimento nel deserto tra Moss e Chigurh, le targhe dei veicoli della polizia di frontiera e delle auto locali mostrano combinazioni di lettere e numeri e adesivi di immatricolazione annuali non conformi al sistema utilizzato nel Texas nel 1980.', TRUE, '2026-11-02T15:44:49.55669', 'No Country for Old Men desert shootout scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4881, 123, '01:15:22', 'Troupe o microfoni visibili', 'Durante la sequenza d''azione sull''autostrada, in un''inquadratura ravvicinata del camion che trasporta la torta, è possibile intravedere brevemente il riflesso della troupe e delle attrezzature di illuminazione sulla carrozzeria lucida del veicolo.', TRUE, '2026-11-02T15:42:04.5939', 'Matrix Reloaded highway truck crew reflection goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4882, 123, '00:42:10', 'Errori di scena / Posizione', 'Nella scena in cui Morpheus tiene il suo discorso infuocato ai cittadini di Zion prima della battaglia, il microfono indossato sul bavero della sua giacca cambia leggermente inclinazione e posizione tra un cambio d''inquadratura e l''altro.', TRUE, '2026-11-02T15:42:04.5939', 'Matrix Reloaded Morpheus speech microphone continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4883, 123, '02:01:45', 'Errori di scena / Posizione', 'Quando Neo si trova nella stanza dell''Architetto, i monitor alle pareti mostrano diverse reazioni di Neo in tempo reale. In un''inquadratura specifica, lo schermo alle spalle dell''Architetto mostra un fotogramma in anticipo rispetto alla sequenza temporale effettiva della conversazione.', TRUE, '2026-11-02T15:42:04.5939', 'Matrix Reloaded Architect monitors scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4884, 123, '01:48:30', 'Troupe o microfoni visibili', 'Durante il combattimento tra Neo e le centinaia di cloni dell''Agente Smith nel parco (Burly Brawl), in alcune inquadrature a campo largo si notano chiaramente i cavi di sicurezza attaccati agli stuntman per le scene di volo e rimbalzo.', TRUE, '2026-11-02T15:42:04.5939', 'Matrix Reloaded Burly Brawl visible wires stunt', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4885, 123, '00:25:15', 'Errori di scena / Posizione', 'Nel corso della festa sotterranea a Zion, la posizione della bottiglia dicolore ambrato tenuta da Trinity varia visibilmente tra la mano destra e la mano sinistra quando l''inquadratura passa da campo medio a primo piano.', TRUE, '2026-11-02T15:42:04.5939', 'Matrix Reloaded Zion party continuity error bottle', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4901, 134, '00:15:20', 'Errori di scena / Posizione', 'Nel corso della sequenza in cui Mickey accusa un malore negli spogliatoi prima del match contro Clubber Lang, la posizione del secchio e degli asciugamani sul tavolo cambia visivamente tra i vari cambi di inquadratura.', TRUE, '2026-11-02T15:42:39.57236', 'Rocky III Mickey locker room scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4902, 134, '00:42:10', 'Troupe o microfoni visibili', 'Durante la scena dell''allenamento sulla spiaggia a Los Angeles, in un campo largo ripreso dall''alto è possibile intravedere brevemente l''ombra di un operatore di ripresa con la macchina da presa sulla sabbia vicino ad Apollo e Rocky.', TRUE, '2026-11-02T15:42:39.57236', 'Rocky III beach training crew shadow visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4903, 134, '01:05:40', 'Errori di scena / Posizione', 'Durante la conferenza stampa in cui Rocky e Clubber Lang si affrontano verbalmente prima del match decisivo, il bicchiere d''acqua davanti a Paulie scompare e riappare pieno tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T15:42:39.57236', 'Rocky III press conference water glass continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4904, 134, '01:28:15', 'Errori di scena / Posizione', 'Nel corso del round finale contro Clubber Lang, la cintura da campione e la disposizione dei secondi all''angolo cambiano posizione improvvisamente quando l''arbitro separa i due pugili.', TRUE, '2026-11-02T15:42:39.57236', 'Rocky III final fight corner continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4932, 144, '00:26:00', 'Errori di scena / Posizione', 'Durante la scena nella fattoria di Perrier LaPadite, quando le SS entrano e bevono il latte, la quantità di latte rimasta nel bicchiere di Hans Landa cambia visibilmente tra un''inquadratura e l''altra mentre parla con il fattore.', TRUE, '2026-11-02T15:43:22.217257', 'Inglourious Basterds milk scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4933, 144, '01:15:00', 'Anacronismi', 'Nella scena della taverna, viene usato un gioco di società basato sui biglietti con i nomi dei personaggi celebri; tuttavia, alcune delle battute e dei riferimenti culturali inseriti dai personaggi anticipano modi di dire o dinamiche non coerenti con il periodo del 1944.', TRUE, '2026-11-02T15:43:22.217257', 'Inglourious Basterds tavern game historical accuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4934, 144, '00:45:00', 'Errori storici o fattuali', 'Nel film viene menzionato che la pellicola cinematografica infiammabile in nitrato di cellulosa brucia anche sott''acqua, un''enfatizzazione drammaturgica non del tutto corretta dal punto di vista chimico-fisico per quanto riguarda la combustione in assenza di ossigeno.', TRUE, '2026-11-02T15:43:22.217257', 'Inglourious Basterds nitrate film fire myth', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4935, 144, '00:09:42', 'Errori di scena / Posizione', 'Nella scena in cui il colonnello Hans Landa ispeziona la fattoria di Perrier LaPadite e fuma la sua caratteristica pipa di grandi dimensioni, la posizione e la quantità di fumo o il modo in cui tiene la pipa tra le dita variano vistosamente tra i primi piani e le inquadrature a figura intera durante il dialogo.', TRUE, '2026-11-02T15:43:22.217257', 'Inglourious Basterds dairy farm scene mistake pipe', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4936, 144, '00:35:15', 'Anacronismi', 'Nel campo di addestramento dei Bastardi, il tenente Aldo Raine brandisce un coltello Bowie e una pistola M1911. Sebbene la pistola fosse in uso, alcuni dettagli dell''equipaggiamento e delle fondine utilizzate da vari soldati americani in alcune inquadrature presentano specifiche varianti e modelli successivi agli anni ''40.', TRUE, '2026-11-02T15:43:22.217257', 'Inglourious Basterds historical gear anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4937, 144, '01:12:50', 'Errori di scena / Posizione', 'Durante il pranzo al ristorante francese tra Shosanna Dreyfus e il soldato tedesco Frederick Zoller, i bicchieri di vino e le posate sul tavolo si spostano leggermente di posizione tra un''inquadratura e l''altra, pur non essendoci stata alcuna interazione dei personaggi con essi.', TRUE, '2026-11-02T15:43:22.217257', 'Inglourious Basterds restaurant scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4938, 144, '01:58:20', 'Errori di scena / Posizione', 'Nella sequenza in cui i soldati britannici e tedeschi giocano a carte nella taverna, il mazzo di carte sul tavolo cambia posizione e orientamento tra i tagli di montaggio, passando da un mucchietto ordinato a carte sparse.', TRUE, '2026-11-02T15:43:22.217257', 'Inglourious Basterds tavern card game continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4939, 144, '02:15:10', 'Errori di scena / Posizione', 'Nel momento in cui Bridget vonghammersmark viene colpita alla gamba nella taverna, i fazzoletti e le bende usate per fermare il sangue cambiano improvvisamente posizione e consistenza quando la telecamera cambia angolazione.', TRUE, '2026-11-02T15:43:22.217257', 'Inglourious Basterds tavern shootout mistake Diane Kruger', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4999, 160, '00:04:15', 'Errori di scena / Posizione', 'Durante la scena del borsaio alla Borsa, la borsa con i documenti che Selina Kyle consegna cambia mano o posizione tra un''inquadratura e l''altra mentre fugge dalle guardie.', TRUE, '2026-11-02T15:44:26.529551', 'The Dark Knight Rises stock exchange scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4900, 127, '02:10:15', 'Errori di scena / Posizione', 'Durante il confronto tra Cheyenne e i suoi uomini nel covo roccioso, gli oggetti sul tavolo (bottiglie, bicchieri e carte) cambiano disposizione e livello di riempimento tra i tagli di montaggio.', TRUE, '2026-11-02T15:42:24.863084', 'Once Upon a Time in the West Cheyenne scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4916, 141, '00:15:42', 'Errori di scena / Posizione', 'Durante la riunione del consiglio comunale in cui Brody discute sulla chiusura delle spiagge, i bicchieri e i fogli di carta sui tavoli cambiano posizione e quantità tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:43:06.980208', 'Jaws town hall meeting continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4917, 141, '00:32:10', 'Errori di scena / Posizione', 'Nel momento in cui la folla si precipita in acqua dopo il falso allarme dello squalo con la pinna finta, la bottiglia di birra tenuta da uno dei ragazzi sulla spiaggia sparisce e riappare magicamente tra le mani.', TRUE, '2026-11-02T15:43:06.980208', 'Jaws fake shark beach panic continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4918, 141, '00:54:20', 'Errori di scena / Posizione', 'Mentre Brody, Hooper e Quint stanno bevendo e mostrando le cicatrici a bordo dell''Orca, la bottiglia di birra di Hooper cambia livello di liquido all''interno e posizione sul tavolo da un''inquadratura all''altra.', TRUE, '2026-11-02T15:43:06.980208', 'Jaws scar scene Orca continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4919, 141, '01:12:05', 'Errori storici o fattuali', 'Quint racconta l''affondamento della USS Indianapolis avvenuto nel luglio del 1945, ma menziona l''orario dell''attacco alle 12:15, mentre storicamente la nave fu silurata e colpita intorno alla mezzanotte.', TRUE, '2026-11-02T15:43:06.980208', 'Jaws Robert Shaw USS Indianapolis speech historical fact', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4920, 141, '01:28:40', 'Troupe o microfoni visibili', 'Durante una delle riprese in mare aperto in cui l''Orca naviga e i personaggi parlano sul ponte, si intravede brevemente l''ombra di un microfono a boom oscillare sulla spalla di Roy Scheider.', TRUE, '2026-11-02T15:43:06.980208', 'Jaws boom mic shadow visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4921, 141, '01:45:15', 'Errori di scena / Posizione', 'Nelle sequenze finali in cui l''Orca sta affondando di poppa, gli interni della cabina mostrano l''acqua che sale rapidamente, ma nell''inquadratura successiva dall''esterno il livello dell''acqua attorno allo scafo appare notevolmente inferiore.', TRUE, '2026-11-02T15:43:06.980208', 'Jaws Orca sinking water level continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4944, 146, '00:15:30', 'Errori di scena / Posizione', 'Nel laboratorio di Tyrell, quando Deckard testa Rachael con il test Voight-Kampff, la sigaretta tra le dita di Rachael cambia visibilmente la lunghezza della cenere e la posizione tra un cambio d''inquadratura e l''altro.', TRUE, '2026-11-02T15:43:30.625049', 'Blade Runner Voight Kampff scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4945, 146, '00:28:45', 'Errori di scena / Posizione', 'Quando Deckard esamina la foto di Leon usando il macchinario ESPER nel suo appartamento, l''angolazione della tastiera e il modo in cui poggia le mani sui comandi variano notevolmente tra i primi piani e i campi medi.', TRUE, '2026-11-02T15:43:30.625049', 'Blade Runner ESPER room scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4946, 146, '00:44:12', 'Troupe o microfoni visibili', 'Nella scena in cui Deckard cammina per strada sotto la pioggia dopo aver visitato il negozio di serpenti di Taffey Lewis, in un breve riflesso sulle vetrine laterali è possibile intravedere brevemente l''ombra di un operatore di macchina con l''attrezzatura.', TRUE, '2026-11-02T15:43:30.625049', 'Blade Runner crew reflection visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4947, 146, '01:02:20', 'Errori di scena / Posizione', 'Durante la sequenza in cui Zhora viene inseguita da Deckard e frantuma i manichini nelle vetrine, i pezzi di vetro e i frammenti dei manichini a terra cambiano disposizione nei tagli successivi della scena.', TRUE, '2026-11-02T15:43:30.625049', 'Blade Runner Zhora chase scene glass continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4948, 146, '01:15:10', 'Errori di scena / Posizione', 'Nel momento in cui Sebastian e Roy Batty entrano nell''appartamento, i giocattoli meccanici sul tavolo cambiano posizione e alcuni di essi risultano accesi o spenti in modo incoerente tra le inquadrature.', TRUE, '2026-11-02T15:43:30.625049', 'Blade Runner Sebastian apartment toys continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4949, 146, '01:32:00', 'Errori di scena / Posizione', 'Durante il combattimento finale tra Deckard e Roy Batty sui tetti, l''acqua che scorre copiosa sui capelli e sugli abiti di Harrison Ford varia drasticamente da inzuppati a quasi asciutti a seconda dell''inquadratura.', TRUE, '2026-11-02T15:43:30.625049', 'Blade Runner rooftop fight continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4984, 156, '00:15:20', 'Errori di scena / Posizione', 'Nel camper durante il viaggio, quando Woody parla con Forky per la prima volta, gli oggetti sul tavolino di plastica vicino al finestrino cambiano posizione e orientamento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:44:11.728303', 'Toy Story 4 RV scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
