(4986, 156, '00:48:10', 'Errori di scena / Posizione', 'Nel luna park, nei pressi della giostra e delle attrazioni, la tazza da caffè tenuta in mano da un passante sullo sfondo scompare e riappare improvvisamente tra un taglio di montaggio e il successivo.', TRUE, '2026-11-02T15:44:11.728303', 'Toy Story 4 carnival background continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4987, 156, '01:05:30', 'Errori di scena / Posizione', 'Nella sequenza del flipper nel negozio di antiquariato, le palline e gli elementi decorativi sulla plancia del gioco cambiano posizione tra l''inquadratura larga e i primi piani sui giocattoli.', TRUE, '2026-11-02T15:44:11.728303', 'Toy Story 4 pinball machine scene error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4988, 156, '01:22:15', 'Errori di scena / Posizione', 'Durante la scena del luna park in cui Buzz e gli altri pianificano il salvataggio vicino ai giochi a premi, i peluche appesi sulla griglia cambiano disposizione cromatica e posizione da un''inquadratura all''altra.', TRUE, '2026-11-02T15:44:11.728303', 'Toy Story 4 carnival prizes continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5020, 166, '00:00:00', 'Errori di scena / Posizione', 'Durante una delle scene all''aperto, il bicchiere di tè freddo tenuto da uno dei personaggi cambia livello di riempimento e posizione della cannuccia tra un''inquadratura e la successiva.', TRUE, '2026-11-02T15:44:45.750286', 'A Time to Kill continuity error cup', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5021, 166, '00:00:00', 'Errori di scena / Posizione', 'Nelle sequenze in cui i veicoli circolano per le strade del Mississippi, le auto parcheggiate sullo sfondo cambiano modello e posizione tra le inquadrature adiacenti.', TRUE, '2026-11-02T15:44:45.750286', 'A Time to Kill car continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4926, 143, '00:42:10', 'Errori storici o fattuali', 'Nel film viene mostrato l''uso di tecnologie 3D avanzate e subacquee per monitorare l''ambiente che non erano realisticamente disponibili o impiegabili in quel modo all''epoca in cui il film è stato distribuito (1983).', TRUE, '2026-11-02T15:43:16.625934', 'Jaws 3D technology factual error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4927, 143, '01:05:45', 'Errori di scena / Posizione', 'Quando l''acqua comincia a invadere i tunnel subacquei del SeaWorld, la quantità di acqua visibile sul pavimento varia drasticamente tra le inquadrature larghe e i primi piani dei personaggi intrappolati.', TRUE, '2026-11-02T15:43:16.625934', 'Jaws 3 underwater tunnel flooding continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4928, 143, '00:15:22', 'Troupe o microfoni visibili', 'Durante una sequenza all''aperto vicino alle vasche del SeaWorld, in un''inquadratura di profilo si intravede brevemente l''ombra di un microfono a boom proiettata sulla spalla di Dennis Quaid.', TRUE, '2026-11-02T15:43:16.625934', 'Jaws 3-D boom mic shadow visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4929, 143, '00:42:15', 'Errori di scena / Posizione', 'Nella sala di controllo, mentre i monitor mostrano l''avanzamento dello squalo, i fogli e i raccoglitori sulla scrivania di Kathryn cambiano posizione e orientamento in modo evidente tra un''inquadratura e la controinquadratura.', TRUE, '2026-11-02T15:43:16.625934', 'Jaws 3-D continuity error control room desk', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4930, 143, '01:05:40', 'Errori storici o fattuali', 'Viene mostrato l''uso di esplosivi subacquei per tentare di uccidere lo squalo all''interno dei tunnel; la detonazione ravvicinata dovrebbe causare gravi danni strutturali e lesioni fatali ai personaggi per pressione idrostatica, che invece rimangono illesi.', TRUE, '2026-11-02T15:43:16.625934', 'Jaws 3-D underwater explosion scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4931, 143, '01:18:10', 'Errori di scena / Posizione', 'Quando i personaggi rompono la vetrata per far defluire la pressione e l''acqua entra copiosa, nei fotogrammi successivi inquadrati dall''esterno il vetro appare inspiegabilmente intatto in alcune sezioni prima di frantumarsi di nuovo.', TRUE, '2026-11-02T15:43:16.625934', 'Jaws 3-D broken glass continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4954, 148, '00:15:22', 'Errori di scena / Posizione', 'Durante il combattimento ravvicinato e concitato contro l''Acheron, la posizione della spada di un ufficiale britannico cambia bruscamente da una mano all''altra tra un''inquadratura e la successiva.', TRUE, '2026-11-02T15:43:39.23982', 'Master and Commander Acheron attack scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4955, 148, '00:42:10', 'Anacronismi', 'In alcune inquadrature ravvicinate degli strumenti di navigazione e dei compassi utilizzati a bordo della HMS Surprise, si notano finiture e leghe metalliche di precisione tipiche di lavorazioni industriali molto successive al 1805.', TRUE, '2026-11-02T15:43:39.23982', 'Master and Commander navigation instruments historical accuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4956, 148, '01:12:45', 'Errori storici o fattuali', 'La velocità con cui la HMS Surprise riesce a doppiare Capo Horn e a compire determinate manovre di raddrizzamento dell''alberatura è altamente idealizzata rispetto alle reali capacità e ai tempi tecnici delle fregate dell''epoca napoleonica.', TRUE, '2026-11-02T15:43:39.23982', 'Master and Commander Cape Horn storm historical accuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4957, 148, '01:48:30', 'Troupe o microfoni visibili', 'Durante le sequenze notturne sul ponte della nave illuminato dalle lanterne, in un angolo dello schermo si intravede per un breve istante il riflesso dell''attrezzatura di illuminazione della troupe sui vetri delle finestre della cabina.', TRUE, '2026-11-02T15:43:39.23982', 'Master and Commander crew reflection film mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4958, 151, '00:25:40', 'Errori di scena / Posizione', 'Durante la riunione dei Fremen nella caverna, la ciotola d''acqua tenuta tra le mani da Stilgar cambia posizione e livello di riempimento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:43:50.327667', 'Dune Parte due Stilgar water scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4959, 151, '00:48:15', 'Errori di scena / Posizione', 'Nella tenda di Paul, la disposizione dei piccoli oggetti e delle mappe di proiezione olografica sul tavolo varia notevolmente tra il primo piano di Paul e l''inquadratura larga.', TRUE, '2026-11-02T15:43:50.327667', 'Dune Part Two tent scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4960, 151, '01:12:30', 'Troupe o microfoni visibili', 'In un''inquadratura grandangolare nel deserto profondo, sul bordo inferiore dello schermo è possibile intravedere brevemente l''ombra di un braccio del microfono boom sulla sabbia.', TRUE, '2026-11-02T15:43:50.327667', 'Dune Part Two boom mic shadow crew error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4961, 151, '01:35:10', 'Errori di scena / Posizione', 'Durante l''attacco alla capitale, le munizioni e le armi imbracciate dai soldati Harkonnen cambiano modello e posizione della cinghia nei diversi stacchi di montaggio delle scene d''azione.', TRUE, '2026-11-02T15:43:50.327667', 'Dune Part Two battle scene weapon continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4994, 159, '00:15:30', 'Errori di scena / Posizione', 'Durante la rapina in banca iniziale, quando il direttore della banca cerca di sparare con il fucile a pompa al primo clown, la quantità di cartucce inserite e la posizione del bossolo cambiano nei vari stacchi di montaggio prima che venga sopraffatto.', TRUE, '2026-11-02T15:44:22.144474', 'The Dark Knight bank robbery opening scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4995, 159, '00:42:15', 'Errori di scena / Posizione', 'Nella scena dell''ufficio in cui il tenente Gordon parla con Harvey Dent, i bicchieri e i documenti sulla scrivania si spostano leggermente da un''inquadratura all''altra senza che nessuno li tocchi.', TRUE, '2026-11-02T15:44:22.144474', 'The Dark Knight Gordon Dent office scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4996, 159, '01:12:40', 'Errori di scena / Posizione', 'Durante la sequenza dell''inseguimento con la Batmobile e il camion blindato, la parte anteriore della Tumbler subisce danni ingenti in un''inquadratura, per poi apparire quasi intatta nell''inquadratura immediatamente successiva.', TRUE, '2026-11-02T15:44:22.144474', 'The Dark Knight batmobile truck chase continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4997, 159, '01:28:10', 'Errori di scena / Posizione', 'Quando il Joker viene chiuso nella cella della stazione di polizia, i fogli e gli oggetti sparsi sulla scrivania fuori dalla cella cambiano disposizione mentre Gordon parla con lui.', TRUE, '2026-11-02T15:44:22.144474', 'The Dark Knight Joker jail cell scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4998, 159, '01:55:20', 'Errori di scena / Posizione', 'Sul set del traghetto, quando i passeggeri votano per far esplodere l''altra nave, la posizione delle mani e la distanza dei personaggi dai detonatori cambiano ripetutamente tra i primi piani e i campi medi.', TRUE, '2026-11-02T15:44:22.144474', 'The Dark Knight ferry scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5065, 189, '00:15:20', 'Errori di scena / Posizione', 'Durante la scena del ristorante in cui Harry e Sally discutono per la prima volta dopo il viaggio in auto, la tazza da caffè davanti a Sally cambia posizione e orientamento del manico più volte tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:45:49.833272', 'When Harry Met Sally diner scene continuity error coffee cup', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4973, 154, '00:15:40', 'Errori di scena / Posizione', 'Nel cortile durante la vendita nel garage di Andy, la limonata sul bancone della bancarella sparisce improvvisamente da un''inquadratura all''altra quando la madre di Andy parla con il collezionista Al.', TRUE, '2026-11-02T15:44:03.541647', 'Toy Story 2 yard sale lemonade glass continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4974, 154, '00:22:10', 'Errori di scena / Posizione', 'Nell''appartamento di Al, mentre Woody scopre i giocattoli della sua stessa serie nella vetrina, la posizione del cappello di Stinky Pete sul piedistallo si sposta leggermente mentre la telecamera cambia angolo.', TRUE, '2026-11-02T15:44:03.541647', 'Toy Story 2 Al''s apartment Woody display case error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4975, 154, '00:48:30', 'Errori di scena / Posizione', 'Nel negozio Al''s Toy Barn, quando i giocattoli di Andy camminano tra le corsie piene di scatole di Buzz Lightyear, il numero di scatole impilate sullo scaffale di destra diminuisce visibilmente tagliando l''inquadratura.', TRUE, '2026-11-02T15:44:03.541647', 'Toy Story 2 Al''s Toy Barn aisle boxes continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4976, 154, '01:12:00', 'Errori di scena / Posizione', 'Durante la scena sul carrello dei bagagli all''aeroporto, quando il secondo Buzz Lightyear rimane intrappolato nella plastica della confezione, i nastri adesivi sulla scatola cambiano orientamento tra i diversi cambi di inquadratura.', TRUE, '2026-11-02T15:44:03.541647', 'Toy Story 2 airport luggage cart Buzz box error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5031, 170, '01:22:00', 'Errori di scena / Posizione', 'Durante la sequenza in cui il Presidente Whitmore e gli altri ufficiali pianificano la missione nell''Area 51, le cartine e i documenti sparsi sulla console centrale cambiano disposizione e posizione esatta tra i primi piani e le inquadrature a campo largo.', TRUE, '2026-11-02T15:45:01.604758', 'Independence Day briefing Area 51 continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5066, 189, '00:32:45', 'Anacronismi', 'Nel corso della sequenza ambientata nel 1981 in cui Harry e Sally parlano al telefono guardando la televisione, in primo piano si nota un modello di apparecchio telefonico o un dettaglio di arredo che appartiene a una produzione successiva alla metà degli anni ottanta.', TRUE, '2026-11-02T15:45:49.833272', 'When Harry Met Sally 1981 phone scene anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5067, 189, '00:48:10', 'Errori di scena / Posizione', 'Nella scena in libreria in cui Harry e Sally si incontrano casualmente dopo anni, i libri sullo scaffale alle spalle di Harry cambiano titolo e disposizione da un''inquadratura all''altra.', TRUE, '2026-11-02T15:45:49.833272', 'When Harry Met Sally bookstore scene continuity error books', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5068, 189, '01:05:30', 'Audio / Doppiaggio / Sync', 'Durante la conversazione notturna al telefono tra Harry e Sally divisi nei rispettivi appartamenti, in un cambio di inquadratura il movimento delle labbra di Meg Ryan risulta leggermente fuori sincrono rispetto all''audio della battuta pronunciata.', TRUE, '2026-11-02T15:45:49.833272', 'When Harry Met Sally split screen phone call lip sync error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5069, 189, '01:14:15', 'Errori di scena / Posizione', 'Nel corso della festa di compleanno in cui Harry affronta la crisi per i 40 anni, il bicchiere tenuto in mano da Harry passa dall''essere quasi pieno a metà vuoto e viceversa tra tagli di montaggio ravvicinati senza che lui beva.', TRUE, '2026-11-02T15:45:49.833272', 'When Harry Met Sally birthday party scene continuity error glass', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5070, 189, '01:28:40', 'Errori di scena / Posizione', 'Nelle sequenze finali in cui Harry cammina per le strade innevate di New York diretto alla festa di Capodanno, la quantità di neve accumulata sui cappotti dei passanti e sulle auto varia visibilmente tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:45:49.833272', 'When Harry Met Sally new years eve snow continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5126, 204, '00:15:22', 'Errori di scena / Posizione', 'Quando Katniss si trova nei corridoi del Distretto 13 e indossa la sua uniforme grigia, la zip della giacca sale e scende leggermente di livello tra un''inquadratura e l''altra durante il dialogo con Haymitch.', TRUE, '2026-11-02T15:46:44.200944', 'Hunger Games Mockingjay Part 1 Katniss Haymitch corridor continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5127, 204, '00:42:10', 'Errori di scena / Posizione', 'Durante la trasmissione del primo propos nel Distretto 4, i monitor sullo sfondo mostrano sequenze di immagini che cambiano ordine cronologico rispetto alla diretta vista nelle inquadrature precedenti.', TRUE, '2026-11-02T15:46:44.200944', 'Hunger Games Mockingjay Part 1 propos broadcast monitors continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5128, 204, '01:05:45', 'Troupe o microfoni visibili', 'Nella sequenza in cui i ribelli entrano nei tunnel bui per sfuggire ai bombardamenti, per un istante si nota il riflesso di una luce di riempimento della troupe sulla visiera di un casco protettivo.', TRUE, '2026-11-02T15:46:44.200944', 'Hunger Games Mockingjay Part 1 reflection crew light helmet', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5129, 204, '01:28:12', 'Errori di scena / Posizione', 'Nel centro di comando del Distretto 13, la tazza di caffè sulla console di Beetee cambia posizione rispetto al bordo del tavolo e al blocco di appunti digitale tra un primo piano e un campo medio.', TRUE, '2026-11-02T15:46:44.200944', 'Hunger Games Mockingjay Part 1 Beetee control room cup continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5143, 209, '00:12:45', 'Anacronismi', 'Durante la scena in cui i Minions viaggiano in autostrada verso Orlando nel 1968, si vede brevemente un cartello stradale con uno stile di carattere e una segnaletica autostradale statunitense che riflette standard introdotti solo negli anni ''70.', TRUE, '2026-11-02T15:47:02.145315', 'Minions 2015 highway scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5144, 209, '00:25:30', 'Errori di scena / Posizione', 'Quando Scarlet Sterminator entra nel suo laboratorio segreto, i gadget tecnologici sul tavolo cambiano disposizione e numero tra un cambio di inquadratura e l''altro senza che nessun personaggio li tocchi.', TRUE, '2026-11-02T15:47:02.145315', 'Minions Scarlet Overkill lab continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5145, 209, '00:48:10', 'Anacronismi', 'Nel Regno Unito del 1968, in alcune sequenze di fuga per le strade di Londra, si possono notare modelli di automobili e furgoni britannici che riportano targhe con formati e combinazioni alfanumeriche non in uso in quel determinato anno.', TRUE, '2026-11-02T15:47:02.145315', 'Minions London 1968 car license plate error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5146, 209, '01:05:20', 'Errori storici o fattuali', 'La rappresentazione dell''incoronazione della Regina Elisabetta II all''interno della storia mostra elementi di protocollo e dettagli storici della cerimonia alterati rispetto agli eventi reali del 1953, sebbene il film sia ambientato nel 1968 (anno in cui la Regina era già sul trono da quindici anni e non fu incoronata).', TRUE, '2026-11-02T15:47:02.145315', 'Minions Queen Elizabeth coronation historical error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5147, 214, '00:30:15', 'Errori di scena / Posizione', 'Durante la scena in cui il Detective Loki interroga Keller Dover a casa sua dopo la scomparsa delle bambine, la tazza di caffè sul tavolo cambia posizione e livello di liquido tra un''inquadratura e l''altra del controcampo.', TRUE, '2026-11-02T15:47:12.165711', 'Prisoners movie continuity error coffee cup', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4977, 155, '00:15:20', 'Errori di scena / Posizione', 'Quando i giocattoli vengono posizionati sul tavolo nella stanza dei giochi del Sunnyside prima dell''arrivo dei bambini, la scatola con i pastelli cambia posizione e orientamento tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:44:08.365859', 'Toy Story 3 Sunnyside classroom continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4978, 155, '00:42:10', 'Errori di scena / Posizione', 'Durante il reset di Buzz Lightyear in modalità dimostrativa spagnola, il pannello di controllo sul suo braccio sinistro si apre e si chiude in modo non coerente tra i vari cambi di inquadratura.', TRUE, '2026-11-02T15:44:08.365859', 'Toy Story 3 Spanish Buzz reset error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4979, 155, '01:05:45', 'Errori di scena / Posizione', 'Nel momento in cui Rex e gli altri cercano di liberare Buzz, i ganci e le cinghie che lo tengono legato alla sedia cambiano lunghezza e disposizione da un''inquadratura ravvicinata a quella generale.', TRUE, '2026-11-02T15:44:08.365859', 'Toy Story 3 Buzz tied to chair continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4980, 155, '00:15:22', 'Errori di scena / Posizione', 'Quando i giocattoli sono sul marciapiede pronti per essere buttati via nella spazzatura, il sacco nero della spazzatura accanto a Woody cambia posizione e grinze visibilmente tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:44:08.365859', 'Toy Story 3 trash bag continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4981, 155, '00:32:45', 'Errori di scena / Posizione', 'Nel momento in cui i giocattoli entrano per la prima volta nella stanza della classe dei bruchi al Sunnyside, Ken mostra una sciarpa che in un primo piano stringe attorno al collo, mentre nell''inquadratura larga successiva la sciarpa risulta leggermente spostata sulle spalle.', TRUE, '2026-11-02T15:44:08.365859', 'Toy Story 3 Ken scarf continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4982, 155, '01:04:10', 'Errori di scena / Posizione', 'Durante il tentativo di fuga, quando Mr. Potato Head è smembrato nel corpo di una tortilla, i frammenti di verdura e gli altri oggetti sparsi sul tavolo variano la loro disposizione nei cambi di inquadratura.', TRUE, '2026-11-02T15:44:08.365859', 'Toy Story 3 potato head tortilla scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(4983, 155, '01:18:30', 'Errori di scena / Posizione', 'Nella scena in cui Lotso si trova vicino al pannello di controllo dell''inceneritore alla discarica, i pulsanti e le spie luminose cambiano colore e disposizione tra le inquadrature ravvicinate e quelle panoramiche.', TRUE, '2026-11-02T15:44:08.365859', 'Toy Story 3 incinerator control panel continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5014, 164, '01:15:22', 'Troupe o microfoni visibili', 'Durante una delle scene di battaglia nella foresta, in basso a destra nell''inquadratura è possibile intravedere brevemente l''estremità di un microfono a boom che sbuca tra il fogliame.', TRUE, '2026-11-02T15:44:41.555487', 'The Patriot 2000 boom mic visible error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5015, 164, '00:42:10', 'Errori di scena / Posizione', 'Nella scena in cui Benjamin Martin e i suoi figli lavorano il legno nel portico, gli strumenti appoggiati sul tavolo cambiano posizione e orientamento da un''inquadratura all''altra senza che nessuno li tocchi.', TRUE, '2026-11-02T15:44:41.555487', 'The Patriot 2000 continuity error porch scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5016, 164, '02:18:45', 'Errori di scena / Posizione', 'Durante gli scontri della battaglia finale, un soldato britannico cade a terra colpito, ma nell''inquadratura successiva a campo largo lo stesso attore si vede chiaramente rialzarsi e correre via sullo sfondo.', TRUE, '2026-11-02T15:44:41.555487', 'The Patriot 2000 battle scene extra mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5017, 164, '01:15:22', 'Errori di scena / Posizione', 'Durante la drammatica scena in cui Gabriel Martin viene colpito a morte, la posizione del corpo e il modo in cui giace a terra variano sensibilmente tra l''inquadratura iniziale in campo medio e il successivo primo piano sul volto disperato di Benjamin.', TRUE, '2026-11-02T15:44:41.555487', 'The Patriot Gabriel death scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5018, 164, '00:42:10', 'Anacronismi', 'Nel corso di una delle scene all''interno della fattoria, si possono notare alcuni chiodi a testa piatta di fabbricazione industriale moderna utilizzati per assemblare parti del mobilio in legno, anziché i tradizionali chiodi forgiati a mano dell''epoca coloniale.', TRUE, '2026-11-02T15:44:41.555487', 'The Patriot historical mistake props nails', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5019, 164, '02:18:45', 'Errori storici o fattuali', 'Durante la battaglia decisiva, i cannoni dell''esercito britannico sparano con una cadenza di tiro e una gittata notevolmente superiori rispetto alle capacità effettive dell''artiglieria leggera da campagna utilizzata nel 1781 durante la guerra d''indipendenza.', TRUE, '2026-11-02T15:44:41.555487', 'The Patriot battle cannon historical accuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5071, 190, '00:15:20', 'Errori di scena / Posizione', 'Durante la lezione in classe, i gessetti e i libri sulla cattedra del professore cambiano disposizione e numero tra un primo piano e il campo medio.', TRUE, '2026-11-02T15:45:53.944071', 'Il tempo delle mele classroom scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5072, 190, '00:32:45', 'Troupe o microfoni visibili', 'In una sequenza girata per le strade di Parigi, si intravede brevemente il riflesso di un operatore con la macchina da presa nella vetrina di un negozio sullo sfondo.', TRUE, '2026-11-02T15:45:53.944071', 'La Boum crew reflection visible film error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5073, 190, '00:48:10', 'Errori di scena / Posizione', 'Nel corso della discussione tra i genitori di Vic in cucina, la tazza di caffè tenuta da François Brasseur passa da una mano all''altra e il livello del liquido varia improvvisamente tra i cambi di inquadratura.', TRUE, '2026-11-02T15:45:53.944071', 'Il tempo delle mele parent kitchen scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5074, 190, '01:05:30', 'Audio / Doppiaggio / Sync', 'In una conversazione all''aperto tra Vic e Poupette, il movimento delle labbra di Denise Grey non coincide perfettamente con le battute audio in alcune riprese ravvicinate.', TRUE, '2026-11-02T15:45:53.944071', 'La Boum dubbing error sync Vic Poupette', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
