(5107, 200, '00:15:20', 'Errori di scena / Posizione', 'Quando Sonny estrae la scatola con le armi dal sacchetto di carta all''interno della banca, la disposizione delle pistole e delle munizioni all''interno della scatola cambia visibilmente tra il primo piano e l''inquadratura successiva.', TRUE, '2026-11-02T15:46:27.940104', 'Dog Day Afternoon bank robbery gun box continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5108, 200, '00:45:10', 'Errori di scena / Posizione', 'Il telefono usato da Sonny per parlare con la polizia all''interno della banca cambia modello o posizione del filo tra una ripresa e l''altra mentre è sotto forte stress emotivo.', TRUE, '2026-11-02T15:46:27.940104', 'Dog Day Afternoon phone call scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5109, 200, '01:12:30', 'Errori di scena / Posizione', 'Le tapparelle e le finestre della banca, colpite o aperte dai personaggi in vari momenti concitati, mostrano doghe piegate in modo diverso nei tagli di montaggio successivi.', TRUE, '2026-11-02T15:46:27.940104', 'Dog Day Afternoon window blinds continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5000, 160, '00:32:00', 'Errori di scena / Posizione', 'Nel corso della festa di beneficenza a casa Wayne, la posizione della sciarpa di Miranda Tate (Marion Cotillard) varia visibilmente tra i primi piani e le inquadrature a figura intera durante la conversazione con Bruce.', TRUE, '2026-11-02T15:44:26.529551', 'The Dark Knight Rises Wayne manor party continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5001, 160, '00:54:10', 'Errori di scena / Posizione', 'Durante il primo scontro brutale tra Batman e Bane nelle fogne, la neve o l''acqua sui vestiti e sul volto di Batman spariscono e riappaiono misteriosamente a seconda dei cambi di angolazione della telecamera.', TRUE, '2026-11-02T15:44:26.529551', 'The Dark Knight Rises Batman vs Bane sewer fight error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5002, 160, '01:15:30', 'Errori di scena / Posizione', 'Nella sequenza in cui i mercenari di Bane fanno esplodere i ponti di Gotham, il conteggio e la sequenza visiva dei veicoli che cadono o si fermano ai blocchi stradali mostrano incongruenze di posizionamento nei campi larghi successivi.', TRUE, '2026-11-02T15:44:26.529551', 'The Dark Knight Rises bridges blowing up continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
