(5355, 320, '01:22:45', 'Errori storici o fattuali', 'Durante la scena del sacrificio umano sul tempio, il tipo di pietra sacrificale e l''iconografia mostrata mescolano elementi stilistici di epoche differenti della civiltà mesoamericana.', TRUE, '2026-11-02T15:50:55.522512', 'Apocalypto pyramid sacrifice historical error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5356, 320, '01:45:12', 'Troupe o microfoni visibili', 'Nella scena in cui Zampa di Giaguaro salta nel fiume per sfuggire ai cani, per un breve fotogramma sul bordo superiore dello schermo si intravede l''estremità di un''imbarcazione della troupe con attrezzatura moderna.', TRUE, '2026-11-02T15:50:55.522512', 'Apocalypto crew reflection or equipment', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5357, 320, '02:02:30', 'Errori di scena / Posizione', 'Quando Zampa di Giaguaro viene colpito da una freccia nel fianco, la ferita sanguina copiosamente ma, in un''inquadratura successiva subito dopo una capriola, la macchia di sangue sulla pelle e sui pantaloni risulta notevolmente ridotta.', TRUE, '2026-11-02T15:50:55.522512', 'Apocalypto arrow wound continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5414, 338, '00:48:12', 'Errori di scena / Posizione', 'Durante la scena in cui Frank si trova nella camera d''albergo a Miami e riceve la visita di una delle ragazze, il bicchiere di drink sul tavolino si riempie e si svuota parzialmente tra un cambio d''inquadratura e l''altro senza che nessuno lo tocchi.', TRUE, '2026-11-02T15:51:45.614782', 'Catch Me If You Can hotel room scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5415, 338, '01:15:30', 'Anacronismi', 'Nella sequenza in cui l''agente Hanratty è nel suo ufficio dell''FBI e sta esaminando dei documenti, sullo sfondo si nota un modello di temperamatite elettrico che non sarebbe stato commercializzato prima degli anni ''70.', TRUE, '2026-11-02T15:51:45.614782', 'Catch Me If You Can FBI office anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5416, 338, '02:05:40', 'Troupe o microfoni visibili', 'Nella scena finale in cui Frank scende dall''aereo in manette sulla pista innevata, si intraprende per un istante il riflesso dell''attrezzatura di illuminazione e di un operatore nella carlinga lucida dell''aereo.', TRUE, '2026-11-02T15:51:45.614782', 'Catch Me If You Can crew reflection airplane scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5240, 281, '00:15:30', 'Anacronismi', 'Quando Marty arriva nel 1885 a Hill Valley e cammina nel fango, gli stivali che indossa sono modelli moderni con suola in gomma vulcanizzata, non disponibili all''epoca dei cowboy.', TRUE, '2026-11-02T15:49:00.330735', 'Back to the Future Part III Marty 1885 boots mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5241, 281, '00:42:10', 'Errori di scena / Posizione', 'Durante la scena in cui Marty entra nel saloon e affronta Buford Tannen, la bottiglia di whisky che Buford rompe sul banco cambia posizione e livello di liquido tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:49:00.330735', 'Back to the Future III saloon whiskey bottle continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5242, 281, '01:05:15', 'Troupe o microfoni visibili', 'Nella sequenza in cui Doc ed Emmett guardano il modello del treno nel laboratorio improvvisato nella miniera, sulla destra si intravede brevemente l''ombra di un microfono a boom che oscilla sulla parete.', TRUE, '2026-11-02T15:49:00.330735', 'Back to the Future 3 boom mic visible mine scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5243, 281, '01:21:45', 'Anacronismi', 'Quando Marty si trova nel 1885 e indossa le mutande con la fantasia di cavalli stampata, un capo del genere non era storicamente disponibile in quel periodo ed è un chiaro anacronismo stilistico.', TRUE, '2026-11-02T15:49:00.330735', 'Back to the Future Part III underwear scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5244, 281, '00:44:10', 'Errori di scena / Posizione', 'Durante la scena del bacio tra Doc ed Emmett (Clara) al festival della cittadina, la posizione delle mani di Clara sulla spalla di Doc cambia visivamente tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T15:49:00.330735', 'Back to the Future Part III festival kiss continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5245, 281, '01:05:20', 'Errori di scena / Posizione', 'Nella scena in cui Marty si misura i vestiti da cowboy nel negozio di Hill Valley, il cappello che tiene in mano passa ripetutamente da una mano all''altra tra i tagli di montaggio senza che lui compia il movimento per spostarlo.', TRUE, '2026-11-02T15:49:00.330735', 'Back to the Future Part III outfit scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5246, 281, '01:42:15', 'Troupe o microfoni visibili', 'Durante la sequenza in cui la DeLorean viene spinta dalla locomotiva prima del salto temporale, in un''inquadratura di sbieco si intravede brevemente il riflesso di una luce da studio cinematografico sulla carrozzeria lucida dell''auto.', TRUE, '2026-11-02T15:49:00.330735', 'Back to the Future Part III train reflection goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5247, 281, '00:15:30', 'Anacronismi', 'Il fucile puntato da Buford Tannen e dai suoi uomini presentano dettagli e meccaniche di caricamento che appartengono a brevetti successivi al 1885.', TRUE, '2026-11-02T15:49:00.330735', 'Back to the Future Part III guns anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5270, 293, '00:15:20', 'Errori di scena / Posizione', 'Nel camerino dove Arthur si trucca prima dello spettacolo negli ospedali pediatrici, la borsa con gli oggetti di scena cambia posizione sul tavolo tra un''inquadratura e l''altra, passando da vicino allo specchio a più distante.', TRUE, '2026-11-02T15:49:28.238966', 'Joker 2019 dressing room scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5271, 293, '00:32:45', 'Errori di scena / Posizione', 'Durante la scena in cui Arthur parla con Thomas Wayne nel bagno dei bagni turchi/teatro, la disposizione dei fogli di carta igienica e dei dettagli sui lavandini cambia visibilmente nei cambi di inquadratura tra i due personaggi.', TRUE, '2026-11-02T15:49:28.238966', 'Joker 2019 Thomas Wayne bathroom scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5272, 293, '00:48:10', 'Errori di scena / Posizione', 'Nel corridoio del condominio di Arthur, quando bussa alla porta di Sophie (Zazie Beetz) per restituirle la chiave, la borsa che la donna tiene a tracolla cambia spalla in modo incoerente tra un taglio di montaggio e il successivo.', TRUE, '2026-11-02T15:49:28.238966', 'Joker 2019 Arthur and Sophie hallway continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5273, 293, '01:05:30', 'Errori di scena / Posizione', 'Nella sequenza in cui Arthur cammina per le scale di Gotham City con i capelli tinti di verde e il vestito rosso, i sacchi della spazzatura e i detriti sui gradini cambiano posizione e quantità tra l''inquadratura dal basso e quella dall''alto.', TRUE, '2026-11-02T15:49:28.238966', 'Joker 2019 stairs scene garbage continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5274, 293, '01:22:15', 'Anacronismi', 'In alcune inquadrature esterne delle strade di Gotham City sono visibili modelli di automobili e furgoni di servizio di un decennio successivo rispetto al 1981, anno ufficiale in cui è ambientata la storia.', TRUE, '2026-11-02T15:49:28.238966', 'Joker 2019 car anachronisms street scenes', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5289, 300, '00:15:30', 'Errori di scena / Posizione', 'Durante la sequenza in cui William Cage si trova all''interno dell''elicottero diretto a Heathrow, le cinghie del suo equipaggiamento e la posizione dello zaino cambiano leggermente tra i diversi cambi di inquadratura.', TRUE, '2026-11-02T15:49:46.429442', 'Edge of Tomorrow helicopter scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5290, 300, '00:42:15', 'Errori di scena / Posizione', 'Nella scena in cui Cage e Rita si trovano nel pub a Omega, i bicchieri sul tavolo e la quantità di liquido al loro interno variano visibilmente tra un''inquadratura e l''altra mentre dialogano.', TRUE, '2026-11-02T15:49:46.429442', 'Edge of Tomorrow pub scene continuity goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5291, 300, '01:10:05', 'Errori di scena / Posizione', 'Durante il combattimento nella diga, la ferita e il sangue sul volto di Rita Vrataski cambiano intensità e posizione da un primo piano a un campo medio.', TRUE, '2026-11-02T15:49:46.429442', 'Edge of Tomorrow dam fight continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5292, 300, '01:25:40', 'Troupe o microfoni visibili', 'Nelle scene finali all''esterno del Louvre a Parigi, riflettori e attrezzature della troupe si intravedono brevemente riflessi sulla carrozzeria lucida di un veicolo militare.', TRUE, '2026-11-02T15:49:46.429442', 'Edge of Tomorrow reflection crew equipment Louvre', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5324, 313, '00:15:20', 'Errori storici o fattuali', 'Durante la sequenza in cui viene estratta l''antimateria al CERN, il contenitore magnetico viene manipolato in un modo che viola i principi fondamentali della fisica delle particelle e del confinamento magnetico descritti nella stessa scena.', TRUE, '2026-11-02T15:50:28.928862', 'Angeli e demoni antimateria CERN errore fisica', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
