(5340, 317, '00:32:45', 'Errori di scena / Posizione', 'Quando Neville si sposta nella videoteca per cercare film e incontra il manichino ''Fred'', il numero di videoteche e DVD posizionati sugli scaffali cambia in modo evidente tra le inquadrature larghe e i primi piani del personaggio.', TRUE, '2026-11-02T15:50:41.617732', 'I am legend video store scene fred continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5341, 317, '00:48:12', 'Errori di scena / Posizione', 'Durante la scena in cui Neville guida la sua Shelby Mustang rossa lungo la Fifth Avenue deserta, la posizione del fucile M4 appoggiato sul sedile del passeggero cambia angolazione e orientamento a ogni cambio di inquadratura dall''interno dell''abitacolo.', TRUE, '2026-11-02T15:50:41.617732', 'I am legend mustang driving scene gun continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5342, 317, '01:05:20', 'Errori di scena / Posizione', 'Nella sequenza in cui Anna e Ethan arrivano a casa di Neville e cenano insieme, la quantità di cibo e vino nei bicchieri e nei piatti oscilla visibilmente da un taglio di montaggio all''altro durante la conversazione.', TRUE, '2026-11-02T15:50:41.617732', 'I am legend dinner scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5343, 317, '01:22:15', 'Errori di scena / Posizione', 'Nel corso della battaglia finale nel laboratorio sotterraneo, quando il capo dei Darkseekers si lancia contro il vetro blindato lasciando vistose crepe, la forma e l''estensione delle fratture sul vetro variano notevolmente tra un impatto e l''altro.', TRUE, '2026-11-02T15:50:41.617732', 'I am legend glass breaking darkseekers error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5374, 328, '00:15:20', 'Errori di scena / Posizione', 'Quando Ray si reca a casa della sua ex moglie, la posizione della sua automobile parcheggiata varia leggermente rispetto al cordolo del marciapiede e alle auto circostanti tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:51:13.10716', 'War of the Worlds 2005 continuity error car parking', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5375, 328, '00:32:45', 'Errori di scena / Posizione', 'Durante la fuga dalla collina dopo il primo attacco del Tripode, la quantità di polvere e detriti sul parabrezza del furgone cambia drasticamente da un''angolazione all''altra.', TRUE, '2026-11-02T15:51:13.10716', 'War of the Worlds 2005 windshield dust continuity goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5376, 328, '00:48:10', 'Troupe o microfoni visibili', 'Nella sequenza in cui la famiglia attraversa il fiume su un traghetto, in un controcampo ravvicinato si intravede brevemente l''ombra di un microfono boom sulla spalla di un figurante.', TRUE, '2026-11-02T15:51:13.10716', 'War of the Worlds 2005 boom mic shadow visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5377, 328, '01:02:15', 'Errori storici o fattuali', 'Durante l''attacco dei Tripodi al fiume Hudson, i militari sparano con lanciarazzi e artiglieria pesante, ma in realtà l''impulso elettromagnetico (EMP) descritto poco prima avrebbe dovuto disattivare qualsiasi sistema di innesco elettronico o radar avanzato delle armi moderne.', TRUE, '2026-11-02T15:51:13.10716', 'War of the Worlds 2005 military attack emp logic error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5378, 328, '01:22:30', 'Errori di scena / Posizione', 'Nel seminterrato in cui si rifugiano Ray e Robbie insieme a Ogilvy, le assi di legno e gli attrezzi appoggiati contro le pareti cambiano disposizione nei diversi cambi di inquadratura.', TRUE, '2026-11-02T15:51:13.10716', 'War of the Worlds 2005 basement Tim Robbins scene continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5379, 328, '01:38:00', 'Troupe o microfoni visibili', 'Mentre Ray si libera dalla sonda dei marziani nel seminterrato, durante un movimento di macchina concitato si nota per un istante l''attrezzatura della troupe riflessa sulla lente della telecamera.', TRUE, '2026-11-02T15:51:13.10716', 'War of the Worlds 2005 camera crew reflection goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5454, 353, '00:04:15', 'Errori di scena / Posizione', 'Durante la scena in cui Chuck Noland si trova a Memphis all''inizio del film, il pacco della FedEx che apre e riceve da sua madre mostra sigilli e etichette che cambiano posizione tra un primo piano e il campo medio mentre parla al telefono.', TRUE, '2026-11-02T15:52:23.414165', 'Cast Away Memphis FedEx scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5455, 353, '00:15:30', 'Errori storici o fattuali', 'Durante il volo notturno durante la tempesta, l''aereo cargo FedEx (un Airbus A300) subisce la rottura degli strumenti di navigazione e dei sistemi di comunicazione, ma i comportamenti e i comandi manuali dei piloti nella cabina di pilotaggio non corrispondono alle procedure di emergenza standard per quel tipo di velivolo.', TRUE, '2026-11-02T15:52:23.414165', 'Cast Away plane crash cockpit procedure error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5456, 353, '00:22:40', 'Errori di scena / Posizione', 'Quando Chuck si risveglia sulla spiaggia dopo il naufragio, indossa l''orologio da polso che continua a funzionare perfettamente ed è impostato sull''ora di Memphis, nonostante sia stato immerso nell''acqua salata dell''oceano profondo durante l''inabissamento.', TRUE, '2026-11-02T15:52:23.414165', 'Cast Away Chuck watch works after crash', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL);
