(5368, 323, '00:15:20', 'Errori di scena / Posizione', 'Durante la scena del colloquio iniziale tra Billy Costigan e i superiori della polizia, il fascicolo e la tazza di caffè sulla scrivania cambiano posizione tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:51:09.377754', 'The Departed scene continuity error desk', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5369, 323, '00:42:10', 'Anacronismi', 'Il film è ambientato nei primi anni 2000 (presumibilmente intorno al 2003-2004), ma in alcune scene si vedono modelli di automobili e smartphone leggermente successivi o non ancora in commercio in quel preciso anno.', TRUE, '2026-11-02T15:51:09.377754', 'The Departed anachronisms cars technology', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5370, 323, '01:05:40', 'Errori storici o fattuali', 'I riferimenti geografici e topografici di Boston utilizzati dai personaggi durante gli inseguimenti a piedi collegano quartieri e strade in modo topograficamente impossibile nella realtà.', TRUE, '2026-11-02T15:51:09.377754', 'The Departed Boston geography errors', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5371, 323, '01:28:15', 'Errori di scena / Posizione', 'Nella scena in cui Colin Sullivan lavora al computer nel suo ufficio, i fogli e le penne accanto alla tastiera si riorganizzano autonomamente nei tagli di montaggio tra i primi piani e i campi medi.', TRUE, '2026-11-02T15:51:09.377754', 'The Departed Colin Sullivan desk continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5372, 323, '01:52:30', 'Errori storici o fattuali', 'Durante la sparatoria culminante, le modalità di ricarica e il numero di colpi esplosi da alcune pistole superano nettamente la capacità effettiva dei caricatori dei modelli impugnati dai personaggi.', TRUE, '2026-11-02T15:51:09.377754', 'The Departed shootout gun logic error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5373, 323, '02:10:05', 'Errori di scena / Posizione', 'Nel momento in cui Sullivan entra nel suo appartamento verso la fine del film, la porta d''ingresso e gli oggetti sul mobiletto dell''atrio variano la loro disposizione rispetto alle inquadrature esterne.', TRUE, '2026-11-02T15:51:09.377754', 'The Departed final apartment continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5427, 341, '00:15:30', 'Errori di scena / Posizione', 'Durante la sequenza in cui John Anderton usa l''interfaccia gestuale per analizzare i dati dei pre-cog, i guanti che indossa scompaiono e riappaiono rapidamente tra un''inquadratura ravvicinata e il campo medio.', TRUE, '2026-11-02T15:51:59.671623', 'Minority Report gestural interface continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5428, 341, '00:42:15', 'Errori di scena / Posizione', 'Nella scena in cui il dottor Solomon esegue il trapianto di occhi, gli strumenti chirurgici sul vassoio cambiano disposizione e numero tra un taglio e l''altro.', TRUE, '2026-11-02T15:51:59.671623', 'Minority Report eye surgery scene continuity goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5429, 341, '01:05:20', 'Troupe o microfoni visibili', 'Nel momento in cui i robot ragno (spider-drones) perquisiscono il condominio e scansionano i residenti, in un riflesso su una porta blindata è possibile intravedere brevemente l''ombra di un operatore di camera.', TRUE, '2026-11-02T15:51:59.671623', 'Minority Report spider drones reflection camera crew', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5430, 341, '01:28:40', 'Errori di scena / Posizione', 'Quando Agatha e Anderton entrano nel negozio di alimentari, le confezioni sugli scaffali alle loro spalle cambiano posizione e orientamento dopo un cambio di inquadratura.', TRUE, '2026-11-02T15:51:59.671623', 'Minority Report grocery store scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5448, 349, '00:15:22', 'Anacronismi', 'Durante la scena del bar in cui i piloti bevono e festeggiano nel 1941, si nota sullo sfondo un tabellone luminoso con marche di birra o insegne che non esistevano all''epoca o presentano font e loghi moderni.', TRUE, '2026-11-02T15:52:18.965092', 'Pearl Harbor bar scene anachronism', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5449, 349, '00:42:10', 'Troupe o microfoni visibili', 'Nel corso della sequenza in cui i piloti camminano sulla pista d''atterraggio, in un''inquadratura grandangolare è possibile intravedere brevemente l''ombra di un microfono a boom sulla sabbia o sulla carlinga di un aereo.', TRUE, '2026-11-02T15:52:18.965092', 'Pearl Harbor boom mic visible crew', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5450, 349, '01:05:15', 'Errori di scena / Posizione', 'Nella scena in cui Rafe e Danny parlano prima della partenza per l''Inghilterra, la tazza di caffè tenuta da uno dei personaggi passa magicamente dalla mano destra alla sinistra e il livello del liquido varia tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T15:52:18.965092', 'Pearl Harbor continuity error coffee cup', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5451, 349, '01:28:40', 'Errori storici o fattuali', 'Durante il raid aereo su Pearl Harbor, vengono mostrati bombardieri in picchiata che eseguono manovre e tipologie di attacco non corrispondenti alla tattica reale impiegata dalla prima ondata della Marina imperiale giapponese.', TRUE, '2026-11-02T15:52:18.965092', 'Pearl Harbor historical inaccuracies attack sequence', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5452, 349, '02:10:50', 'Errori di scena / Posizione', 'Durante la missione di raid aereo di Tokyo guidata da Doolittle, i boccaporti e gli interni dei bombardieri B-25 cambiano disposizione di cavi e strumenti di volo tra le riprese in studio e le sequenze in volo.', TRUE, '2026-11-02T15:52:18.965092', 'Pearl Harbor Doolittle raid B25 continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5453, 349, '02:35:12', 'Audio / Doppiaggio / Sync', 'In una sequenza drammatica sulla spiaggia dopo l''attacco, il movimento delle labbra di Ben Affleck non coincide perfettamente con l''audio del dialogo pronunciato in primo piano.', TRUE, '2026-11-02T15:52:18.965092', 'Pearl Harbor lip sync error Ben Affleck', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5385, 330, '00:12:45', 'Errori di scena / Posizione', 'Durante la sequenza iniziale nel diner, quando Tom Stall si avvicina al registratore di cassa per estrarre il denaro da consegnare ai rapinatori, la posizione delle banconote e delle monete sul bancone cambia visibilmente tra l''inquadratura larga e il primo piano.', TRUE, '2026-11-02T15:51:20.600701', 'A History of Violence diner scene mistake', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5386, 330, '00:28:10', 'Errori di scena / Posizione', 'Nel momento in cui la famiglia Stall è riunita a colazione, il bicchiere di succo d''arancia davanti al figlio Jack passa dall''essere pieno a quasi vuoto e viceversa nei vari cambi di inquadratura.', TRUE, '2026-11-02T15:51:20.600701', 'A History of Violence breakfast continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5387, 330, '00:45:30', 'Errori di scena / Posizione', 'Quando Carl Fogarty incontra Tom Stall fuori dalla scuola del figlio, la giacca di Fogarty appare completamente abbottonata in un''inquadratura e parzialmente sbottonata nell''inquadratura successiva.', TRUE, '2026-11-02T15:51:20.600701', 'A History of Violence Fogarty school scene goof', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5388, 330, '01:04:20', 'Errori di scena / Posizione', 'Durante la brutale aggressione subita da Tom a casa sua da parte degli uomini di Fogarty, il posizionamento delle lampade e degli oggetti sul tavolino del soggiorno cambia dopo che uno dei criminali vi urta contro.', TRUE, '2026-11-02T15:51:20.600701', 'A History of Violence house fight continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5389, 330, '01:22:15', 'Errori di scena / Posizione', 'Nella sequenza in cui Tom viaggia in auto verso Philadelphia per affrontare Richie, il paesaggio e la luce del sole attraverso i finestrini cambiano repentinamente tra un''inquadratura e l''altra, suggerendo riprese effettuate in momenti della giornata molto diversi.', TRUE, '2026-11-02T15:51:20.600701', 'A History of Violence driving to Philadelphia continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5418, 339, '01:22:15', 'Anacronismi', 'Durante una scena in cui i personaggi discutono per le strade di New York, sullo sfondo si nota chiaramente la pavimentazione stradale con segnaletica orizzontale moderna parzialmente coperta da terra e fango.', TRUE, '2026-11-02T15:51:50.513697', 'Gangs of New York street scene modern error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5419, 339, '00:45:10', 'Errori di scena / Posizione', 'Nella sequenza in cui Bill il Genio (Daniel Day-LuIs) si esibisce nel lancio dei coltelli contro Jenny (Cameron Diaz), il numero e la disposizione dei coltelli conficcati nel pannello di legno cambiano drasticamente tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:51:50.513697', 'Gangs of New York knife throwing scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5420, 339, '02:14:30', 'Troupe o microfoni visibili', 'Durante i disordini della rivolta della leva (Draft Riots), in un campo largo concitato si intravede per un breve fotogramma il braccio di un operatore di ripresa con una moderna giacca tecnica nera ai margini dell''inquadratura.', TRUE, '2026-11-02T15:51:50.513697', 'Gangs of New York draft riots crew visible error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5421, 339, '01:05:40', 'Errori storici o fattuali', 'Viene mostrato l''uso di fiammiferi a frizione moderna (tipo safety matches) che non erano ancora stati inventati o commercializzati nella forma mostrata nel 1863, periodo in cui erano diffusi i fiammiferi a zolfo o i luciferi di John Walker.', TRUE, '2026-11-02T15:51:50.513697', 'Gangs of New York matches historical error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5422, 339, '00:15:20', 'Errori di scena / Posizione', 'Nel flashback iniziale ambientato nel 1846, la neve che cade sui cappotti dei personaggi varia visibilmente di intensità e accumulo tra i cambi di ripresa ravvicinati e i campi lunghi.', TRUE, '2026-11-02T15:51:50.513697', 'Gangs of New York opening battle snow continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5437, 347, '01:15:00', 'Errori di scena / Posizione', 'Durante una delle scene in cui John Nash lavora alla sua scrivania nel suo studio, i fogli di carta e i calcoli sparsi cambiano visibilmente posizione e quantità tra un''inquadratura e l''altra, senza che il personaggio li abbia toccati.', TRUE, '2026-11-02T15:52:11.724504', 'A Beautiful Mind continuity error desk papers', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5438, 347, '00:45:30', 'Anacronismi', 'In una sequenza ambientata negli anni ''50, sullo sfondo si intravedono automobili e modelli di veicoli stradali che sono stati prodotti e immessi sul mercato diversi anni dopo l''anno specifico della scena.', TRUE, '2026-11-02T15:52:11.724504', 'A Beautiful Mind car anachronism error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5439, 347, '01:50:20', 'Errori storici o fattuali', 'Nel film, l''assegnazione del Premio Nobel a John Nash nel 1994 viene mostrata con una cerimonia pubblica in cui Nash tiene un discorso formale e commovente. Nella realtà storica, i vincitori del Nobel non tengono un discorso ufficiale durante la cerimonia di premiazione stessa, ma una conferenza successiva (la Nobel Lecture).', TRUE, '2026-11-02T15:52:11.724504', 'A Beautiful Mind Nobel prize historical inaccuracy', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5440, 347, '00:22:15', 'Errori di scena / Posizione', 'Mentre John Nash beve da una tazza di caffè in una scena all''aperto a Princeton, la quantità di liquido all''interno della tazza e il modo in cui la impugna variano drasticamente da un taglio di montaggio all''altro.', TRUE, '2026-11-02T15:52:11.724504', 'A Beautiful Mind coffee cup continuity', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5441, 347, '01:30:10', 'Troupe o microfoni visibili', 'In un''inquadratura grandangolare all''interno del laboratorio di Wheeler, sul vetro lucido di una finestra e sullo schermo riflettente di alcune apparecchiature è possibile intravedere brevemente il riflesso dell''attrezzatura di illuminazione della troupe.', TRUE, '2026-11-02T15:52:11.724504', 'A Beautiful Mind crew reflection visible', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5390, 331, '00:15:20', 'Errori di scena / Posizione', 'Durante la cena a casa della famiglia Hewett, la bottiglia di vino sul tavolo cambia posizione e livello di liquido tra le inquadrature che ritraggono Chris Wilton e quelle su Chloe.', TRUE, '2026-11-02T15:51:25.5115', 'Match Point dinner continuity error wine bottle', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
