(5392, 331, '01:10:45', 'Errori di scena / Posizione', 'Quando Chris entra nell''appartamento di Nola per compiere il tragico gesto, i libri sul tavolino del soggiorno si trovano prima in un mucchio disordinato e, nell''inquadratura immediatamente successiva, sono allineati.', TRUE, '2026-11-02T15:51:25.5115', 'Match Point apartment scene continuity error books', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5393, 331, '01:25:30', 'Audio / Doppiaggio / Sync', 'Durante la scena della perquisizione della polizia nell''appartamento, il movimento delle labbra di uno degli investigatori non coincide perfettamente con l''audio del dialogo pronunciato in italiano.', TRUE, '2026-11-02T15:51:25.5115', 'Match Point dubbing mismatch police scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5394, 331, '01:38:12', 'Errori di scena / Posizione', 'Nel momento in cui l''anello di Nola rimbalza contro la ringhiera e cade nel fiume, la traiettoria fisica nei diversi stacchi di montaggio appare incoerente rispetto alla posizione iniziale della ringhiera stessa.', TRUE, '2026-11-02T15:51:25.5115', 'Match Point ring falling scene continuity error', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5478, 359, '00:15:40', 'Errori di scena / Posizione', 'Quando Ichabod Crane esamina la testa della prima vittima sul tavolo autoptico, gli strumenti chirurgici accanto al corpo cambiano disposizione e numero tra un''inquadratura e l''altra.', TRUE, '2026-11-02T15:52:42.539074', 'Sleepy Hollow 1999 Ichabod autopsy scene goofs', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5479, 359, '00:42:15', 'Troupe o microfoni visibili', 'Durante la scena in cui i notabili del villaggio discutono animatamente nella chiesa, in alto a sinistra si intravede per un breve fotogramma l''ombra di un microfono a boom che oscilla sulla parete.', TRUE, '2026-11-02T15:52:42.539074', 'Sleepy Hollow 1999 boom mic visible church scene', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
(5480, 359, '01:05:20', 'Anacronismi', 'Nel corso delle indagini nel bosco, vengono utilizzate lanterne e candele con caratteristiche di costruzione e combustibili che anticipano tecnologie e standard produttivi dell''epoca successiva.', TRUE, '2026-11-02T15:52:42.539074', 'Sleepy Hollow 1999 anachronisms historical errors', 0, 0, 'IA (Daily Sync)', 'IA Verificata', NULL),
