(5504, 262, '01:12:40', 'Errori di scena / Posizione', 'Quando Ryland manovra i comandi della navicella Hail Mary, la posizione dei blocchi di appunti e dei piccoli strumenti agganciati con il velcro sulla paratia laterale risulta invertita nel controcampo rispetto all''inquadratura precedente.', TRUE, '2026-11-02T17:18:42.022808', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(5505, 262, '01:45:10', 'Anacronismi', 'Durante una simulazione olografica avanzata delle dinamiche orbitali della stella e della sostanza astrofagica, alcune equazioni matematiche mostrano notazioni moderne introdotte solo recentemente, sebbene la sequenza si collochi in un futuro prossimo in cui tali convenzioni dovrebbero essersi evolute.', TRUE, '2026-11-02T17:18:42.022808', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5506, 262, '02:05:30', 'Errori di scena / Posizione', 'Nel corso della sequenza culminale all''esterno dello scafo, la posizione dei piccoli detriti spaziali fluttuanti sullo sfondo cambia drasticamente da un''inquadratura all''altra, pur trovandosi la telecamera nella stessa prospettiva fissa.', TRUE, '2026-11-02T17:18:42.022808', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5507, 264, '00:14:22', 'Errori di scena / Posizione', 'Durante il colloquio tra i personaggi interpretati da Emily Blunt e Colin Firth, il blocco per appunti sulla scrivania cambia posizione e inclinazione tra un''inquadratura in campo medio e il successivo primo piano.', TRUE, '2026-11-02T17:18:57.303416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5508, 264, '00:32:45', 'Troupe o microfoni visibili', 'In una sequenza notturna all''aperto che coinvolge Josh O''Connor, il riflesso della luce di un pannello riflettente e la sagoma di un operatore della troupe sono chiaramente visibili sulla carrozzeria lucida dell''auto di servizio.', TRUE, '2026-11-02T17:18:57.303416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5509, 264, '01:05:10', 'Errori di scena / Posizione', 'Il bicchiere di caffè tenuto in mano da Colman Domingo passa dall''essere quasi pieno a quasi vuoto e viceversa in tre inquadrature consecutive girate all''interno di una sala riunioni governativa.', TRUE, '2026-11-02T17:18:57.303416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5510, 264, '01:28:55', 'Anacronismi', 'Durante un''analisi su un monitor di controllo ad alta tecnologia, si intravede brevemente l''interfaccia di un software di editing video non commerciale rilasciato diversi anni dopo l''ambientazione temporale della scena.', TRUE, '2026-11-02T17:18:57.303416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5511, 264, '01:51:30', 'Errori di scena / Posizione', 'Nella sequenza finale con Wyatt Russell e Eve Hewson, i documenti sparsi sul tavolo della cucina cambiano disposizione da un''inquadratura all''altra, senza che vi sia alcun movimento dei personaggi che giustifichi lo spostamento.', TRUE, '2026-11-02T17:18:57.303416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5512, 257, '00:24:15', 'Errori di scena / Posizione', 'Durante la tempesta in mare, la brocca di terracotta tenuta da Ulisse (Matt Damon) cambia mano e posizione tra un''inquadratura in primo piano e il successivo campo medio, apparendo prima integra e poi leggermente scheggiata.', TRUE, '2026-11-02T17:19:56.282522', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5513, 257, '01:05:40', 'Troupe o microfoni visibili', 'Nel corso del confronto sulla spiaggia tra Ulisse e i suoi compagni, in basso a destra nell''inquadratura si intravede brevemente l''ombra di un microfono a giraffa proiettata sulla sabbia bagnata.', TRUE, '2026-11-02T17:19:56.282522', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5514, 257, '01:42:10', 'Anacronismi', 'In una scena ambientata nell''interno di una tenda reale, sullo sfondo si nota un supporto metallico moderno per candele rifinito con tecniche di saldatura industriale non coerenti con il periodo storico rappresentato.', TRUE, '2026-11-02T17:19:56.282522', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5515, 257, '02:10:55', 'Errori storici o fattuali', 'L''armatura indossata da un ufficiale acheo presenta decorazioni e una foggia metallica tipica di un periodo storico successivo di circa tre secoli rispetto all''ambientazione mitologica della narrazione.', TRUE, '2026-11-02T17:19:56.282522', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5516, 257, '02:35:20', 'Errori di scena / Posizione', 'Nella sequenza finale del ricongiungimento a Itaca, la posizione della spada conficcata nella roccia alle spalle di Ulisse varia visibilmente nell''inclinazione passando dall''angolazione frontale a quella laterale.', TRUE, '2026-11-02T17:19:56.282522', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5542, 309, '00:24:15', 'Errori di scena / Posizione', 'Durante il confronto tra Jake Sully e i membri del clan in una foresta di cenere, il pugnale impugnato da Jake cambia orientamento della lama tra il campo medio e il primo piano stretto.', TRUE, '2026-11-02T17:21:41.936828', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5543, 309, '00:51:30', 'Troupe o microfoni visibili', 'In una sequenza subacquea notturna con bioluminescenza, sul lato destro del casco di un avatar si nota per un fotogramma il riflesso della luce di un pannello LED della troupe.', TRUE, '2026-11-02T17:21:41.936828', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5544, 309, '01:14:42', 'Errori di scena / Posizione', 'Le ceneri vulcaniche accumulate sulle spalle e sui capelli di Neytiri scompaiono e riappaiono con densità differenti tra un''inquadratura e la successiva durante una corsa concitata.', TRUE, '2026-11-02T17:21:41.936828', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5545, 309, '01:42:05', 'Anacronismi', 'Un terminale di controllo della RDA mostra un''interfaccia con elementi visivi e font tipicamente terrestri moderni che non risultano coerenti con la tecnologia proprietaria avanzata vista nei capitoli precedenti.', TRUE, '2026-11-02T17:21:41.936828', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5546, 309, '02:08:10', 'Errori di scena / Posizione', 'Le ferite e i graffi sul braccio di Varang cambiano visibilmente posizione e lunghezza da un''inquadratura all''altra durante la sequenza dello scontro finale.', TRUE, '2026-11-02T17:21:41.936828', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5519, 270, '00:51:10', 'Anacronismi', 'In primo piano su un''auto parcheggiata sullo sfondo si nota un dettaglio di finitura e componentistica di un modello di automobile uscito sul mercato alla fine degli anni ''60, anacronistico rispetto al 1959.', TRUE, '2026-11-02T17:20:11.82664', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5520, 270, '01:05:30', 'Errori di scena / Posizione', 'Nel corso di una colluttazione, la pistola impugnata da Jack passa ripetutamente dalla mano destra alla sinistra e viceversa tra un taglio di montaggio e l''altro senza che vi sia il tempo logico per il cambio.', TRUE, '2026-11-02T17:20:11.82664', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5521, 270, '01:22:15', 'Errori storici o fattuali', 'I marchi e i modelli di alcune lattine e confezioni di prodotti alimentari americani usati come oggetti di scena nel covo dei gangster presentano grafiche e font tipografici risalenti agli anni ''70 anziché alla fine degli anni ''50.', TRUE, '2026-11-02T17:20:11.82664', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5523, 276, '00:28:10', 'Troupe o microfoni visibili', 'Nella sequenza in cui i nuovi professori entrano per la prima volta nel cortile del liceo Manzoni, si intravede brevemente l''ombra di un microfono boom sul muro di mattoni alla sinistra dell''inquadratura.', TRUE, '2026-11-02T17:20:34.537184', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5524, 276, '00:45:20', 'Errori di scena / Posizione', 'Durante la lezione di prova nell''aula magna, la posizione della tazza di caffè sulla cattedra del professor Cacciintesta oscilla vistosamente tra una ripresa frontale e una laterale, spostandosi di diversi centimetri senza che nessuno la tocchi.', TRUE, '2026-11-02T17:20:34.537184', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5525, 276, '01:04:15', 'Anacronismi', 'Uno degli studenti utilizza uno smartphone chiaramente appartenente a un modello uscito sul mercato diversi anni dopo l''ambientazione dichiarata della scena scolastica.', TRUE, '2026-11-02T17:20:34.537184', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5526, 276, '01:22:50', 'Errori di scena / Posizione', 'Nella scena finale dei festeggiamenti nel cortile della scuola, la sciarpa indossata da uno dei protagonisti scompare e riappare attorno al collo tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-02T17:20:34.537184', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5527, 354, '00:15:22', 'Errori di scena / Posizione', 'Durante la discussione iniziale nella cucina tra Alice e Terry, la tazza di caffè tenuta da Meg Ryan cambia posizione e livello di riempimento tra un''inquadratura in campo medio e il successivo primo piano.', TRUE, '2026-11-02T17:20:54.409545', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5528, 354, '00:42:10', 'Troupe o microfoni visibili', 'In una sequenza dinamica in cui la macchina da presa segue Russell Crowe che cammina per le strade sterrate del villaggio colombiano, si intravede brevemente l''ombra del braccio di un microfono boom proiettata sul muro di fango a sinistra.', TRUE, '2026-11-02T17:20:54.409545', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5529, 354, '01:05:45', 'Errori di scena / Posizione', 'Nel corso della scena in cui il personaggio interpretato da David Morse è tenuto prigioniero nella giungla, i tagli sulle braccia e il fango sul viso variano sensibilmente in spessore e disposizione geografica tra campi e controcampi consecutivi.', TRUE, '2026-11-02T17:20:54.409545', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5530, 354, '01:28:15', 'Anacronismi', 'In alcune scene ambientate nella giungla in cui i guerriglieri comunicano via radio, i modelli di apparati ricetrasmittenti utilizzati mostrano antenne e componenti esteticamente riconducibili a standard tecnologici successivi rispetto all''anno di ambientazione e rilascio del film (2000).', TRUE, '2026-11-02T17:20:54.409545', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5531, 354, '01:50:30', 'Errori storici o fattuali', 'Le procedure tattiche e di negoziazione messe in atto dal personaggio di Russell Crowe in territorio sudamericano presentano diverse inesattezze rispetto ai protocolli reali delle compagnie di assicurazione internazionali e dei reparti speciali per la liberazione di ostaggi.', TRUE, '2026-11-02T17:20:54.409545', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5532, 263, '00:14:22', 'Errori di scena / Posizione', 'Durante una colluttazione nei boschi tra il personaggio interpretato da Hugh Jackman e le guardie, il pugnale impugnato da Robin cambia mano tra un''inquadratura in campo largo e il successivo primo piano ravvicinato.', TRUE, '2026-11-02T17:21:13.926821', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5533, 263, '00:32:45', 'Errori di scena / Posizione', 'Il boccale di birra tenuto da Bill Skarsgård in una taverna si svuota visibilmente e si riempie nuovamente a metà tra un cambio di inquadratura e l''altro, senza che ci sia stata alcuna azione di versamento.', TRUE, '2026-11-02T17:21:13.926821', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5534, 263, '00:51:10', 'Troupe o microfoni visibili', 'In una scena ambientata all''interno di una capanna buia, riflesso nell''elmetto metallico di un soldato sullo sfondo, è chiaramente visibile il braccio di un operatore che sposta un pannello riflettente.', TRUE, '2026-11-02T17:21:13.926821', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5535, 263, '01:08:15', 'Anacronismi', 'Nei dettagli dei ferri utilizzati per la marchiatura a fuoco del bestiame, la forma dei caratteri metallici impiegati utilizza un font tipografico moderno e squadrato, estraneo ai metodi di forgiatura dell''epoca medievale.', TRUE, '2026-11-02T17:21:13.926821', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5536, 263, '01:25:40', 'Errori storici o fattuali', 'Le ferite da taglio sul braccio di Jodie Comer cambiano drasticamente profondità e posizione della fasciatura tra la scena della fuga notturna e il successivo dialogo all''alba, ignorando i tempi biologici di guarigione e medicazione.', TRUE, '2026-11-02T17:21:13.926821', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5537, 263, '01:42:05', 'Troupe o microfoni visibili', 'Durante la sequenza finale dell''assalto al castello, per una frazione di secondo nell''angolo superiore dello schermo compare l''estremità pelosa di un microfono boom mentre la macchina da presa effettua una rapida panoramica verso l''alto.', TRUE, '2026-11-02T17:21:13.926821', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5538, 273, '00:15:20', 'Errori di scena / Posizione', 'Durante una conversazione tra Aldo e Giovanni nel taxi, la tazza di caffè tenuta da Giovanni cambia posizione e livello di liquido tra un''inquadratura in campo medio e il successivo primo piano.', TRUE, '2026-11-02T17:21:28.38745', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5539, 273, '00:32:45', 'Errori di scena / Posizione', 'Nel soggiorno della casa di Giacomo, i libri disposti sul tavolino basso cambiano orientamento e disposizione in modo evidente tra l''inquadratura in cui Giacomo si alza e quella immediatamente successiva.', TRUE, '2026-11-02T17:21:28.38745', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5540, 273, '00:51:10', 'Troupe o microfoni visibili', 'In una scena girata in esterni per strada, riflettendosi nello specchietto retrovisore laterale dell''auto di Aldo, è possibile intravedere brevemente la sagoma di un operatore della troupe con l''attrezzatura di ripresa.', TRUE, '2026-11-02T17:21:28.38745', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5541, 273, '01:08:30', 'Errori di scena / Posizione', 'Durante la sequenza della cena al ristorante, il tovagliolo accanto al piatto di Claudia passa dall''essere piegato a triangolo all''essere completamente spiegato e accartocciato nel cambio inquadratura.', TRUE, '2026-11-02T17:21:28.38745', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5547, 289, '00:15:20', 'Errori di scena / Posizione', 'Durante la discussione iniziale tra Frank Cheyne e il direttore della scuola, i documenti sulla scrivania cambiano posizione e orientamento tra un''inquadratura in primo piano e il controcampo generale.', TRUE, '2026-11-02T17:22:28.332416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5548, 289, '00:32:45', 'Errori di scena / Posizione', 'Quando Harvey cade in mare dal transatlantico, la posizione delle sue mani e il modo in cui i vestiti sono bagnati variano notevolmente nelle successive inquadrature subacquee e al momento della risalita a bordo.', TRUE, '2026-11-02T17:22:28.332416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5549, 289, '01:04:12', 'Errori di scena / Posizione', 'A bordo del peschereccio, il secchio di legno utilizzato da Manuel Fidello cambia di posto accanto alla murata tra un cambio di inquadratura e l''altro, pur non essendoci nessuno che lo sposti.', TRUE, '2026-11-02T17:22:28.332416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5550, 289, '01:42:30', 'Troupe o microfoni visibili', 'In una sequenza ravvicinata sul ponte durante una tempesta, per pochi fotogrammi in alto a destra si intravede l''ombra di un microfono a giraffa proiettata sulla vela principale.', TRUE, '2026-11-02T17:22:28.332416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5551, 289, '02:05:15', 'Errori storici o fattuali', 'Le manovre eseguite dai marinai sul peschereccio per issare le reti in alcune sequenze riflettono tecniche di marineria moderne anziché quelle tradizionali dei pescherecci a vela dei Grand Banks degli anni ''30.', TRUE, '2026-11-02T17:22:28.332416', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5552, 261, '00:14:22', 'Errori di scena / Posizione', 'Durante la colluttazione nella cucina di Hutch, il coltello da cucina sul bancone cambia orientamento e posizione tra un''inquadratura in campo medio e il successivo primo piano ravvicinato.', TRUE, '2026-11-02T17:22:42.689165', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5553, 261, '00:32:10', 'Troupe o microfoni visibili', 'In una rapida panoramica laterale mentre Hutch guida l''auto nel traffico notturno, è possibile intravedere brevemente il riflesso di un pannello riflettente e di parte della troupe sul finestrino posteriore.', TRUE, '2026-11-02T17:22:42.689165', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5554, 261, '01:05:45', 'Errori di scena / Posizione', 'Le ferite e i tagli sul volto di Bob Odenkirk variano in modo evidente per estensione e coagulazione del sangue tra le scene d''azione e i successivi dialoghi in interni, senza che sia trascorso del tempo per una medicazione.', TRUE, '2026-11-02T17:22:42.689165', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5555, 261, '01:21:03', 'Troupe o microfoni visibili', 'Durante il combattimento nel magazzino, in basso a sinistra nell''inquadratura si intravede per un fotogramma il cavo di sicurezza nero utilizzato per facilitare la proiezione aerea di uno stuntman.', TRUE, '2026-11-02T17:22:42.689165', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5556, 267, '00:14:22', 'Errori di scena / Posizione', 'Durante la conversazione tra Benoit Blanc e il giovane prete all''interno della sagrestia, il calice di legno sul tavolo cambia posizione e inclinazione tra il campo e il controcampo, spostandosi di diversi centimetri senza che nessuno lo tocchi.', TRUE, '2026-11-02T17:22:57.185482', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5557, 267, '00:32:45', 'Troupe o microfoni visibili', 'In una panoramica grandangolare all''esterno della chiesa di piccola città, sul lucido finestrino laterale di un''auto d''epoca parcheggiata sulla sinistra è chiaramente riflesso il profilo di un operatore con asta del microfono boom.', TRUE, '2026-11-02T17:22:57.185482', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5558, 267, '01:05:10', 'Errori di scena / Posizione', 'Nella sequenza della confessione notturna, i fogli di appunti sparsi sul banco del prete subiscono variazioni evidenti nell''ordine e nella disposizione dei fascicoli tra un''inquadratura ravvicinata e quella a figura intera.', TRUE, '2026-11-02T17:22:57.185482', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5559, 267, '01:42:18', 'Troupe o microfoni visibili', 'Durante la rivelazione finale del colpevole, mentre la macchina da presa stringe sul volto di Glenn Close, si intrappone per un fotogramma l''ombra netta di un pannello riflettente (riflettore a farfalla) nell''angolo in basso a destra dello schermo.', TRUE, '2026-11-02T17:22:57.185482', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5560, 362, '00:24:15', 'Errori di scena / Posizione', 'Durante la visita in carcere tra John e Lara, il telefono usato per parlare attraverso il vetro cambia leggermente posizione rispetto all''orecchio di Lara tra un''inquadratura e l''altra nel campo/controcampo.', TRUE, '2026-11-02T17:26:31.534673', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5561, 362, '00:48:30', 'Errori di scena / Posizione', 'Quando John si trova nel parcheggio e apre il bagagliaio della sua auto, gli attrezzi e le borse al suo interno cambiano disposizione e orientamento nel taglio successivo.', TRUE, '2026-11-02T17:26:31.534673', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5562, 362, '01:12:10', 'Troupe o microfoni visibili', 'In una delle sequenze in cui John cammina per le strade affollate della città, per un breve fotogramma si intravede il riflesso di un pannello riflettente (flicker) nella vetrina di un negozio sullo sfondo.', TRUE, '2026-11-02T17:26:31.534673', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5563, 362, '01:35:45', 'Errori di scena / Posizione', 'Nella scena dell''ospedale, il monitor che mostra i parametri vitali presenta un tracciato che salta improvvisamente di configurazione tra il primo piano sul display e il campo medio con i personaggi.', TRUE, '2026-11-02T17:26:31.534673', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5564, 362, '01:52:20', 'Errori di scena / Posizione', 'Durante la fuga finale allo zoo, la quantità di pioggia sui capelli e sulla giacca di Russell Crowe varia visibilmente da un''inquadratura all''altra nel giro di pochi secondi.', TRUE, '2026-11-02T17:26:31.534673', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5565, 363, '00:14:22', 'Errori di scena / Posizione', 'Durante la sequenza in cui Mickey 17 si risveglia nella vasca di rigenerazione, la posizione dei tubi di bio-rigenerazione collegati al suo braccio destro varia nettamente tra l''inquadratura larga e il primo piano successivo, passando da piegati verso l''alto a completamente tesi.', TRUE, '2026-11-02T17:29:08.648754', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5566, 363, '00:42:15', 'Troupe o microfoni visibili', 'Nella scena all''interno del laboratorio criogenico su Niflheim, sul lucido casco protettivo di uno dei coloni si intravede chiaramente per pochi fotogrammi il riflesso della telecamera e di un operatore della troupe in abiti moderni.', TRUE, '2026-11-02T17:29:08.648754', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5567, 363, '01:05:40', 'Errori di scena / Posizione', 'Nel confronto teso tra Mickey 17 e Mickey 18 nella mensa della base, il bicchiere di liquido sintetico tenuto da Mickey 17 cambia livello di riempimento e posizione della mano attorno al vetro in modo incoerente tra i campi e controcampi.', TRUE, '2026-11-02T17:29:08.648754', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5568, 363, '01:28:10', 'Anacronismi', 'Durante l''esplorazione della superficie ghiacciata, i monitor digitali portatili utilizzati dai coloni mostrano interfacce grafiche con font e layout tipari dei moderni sistemi operativi terrestri del XXI secolo, anacronistici rispetto all''ambientazione futuristica avanzata.', TRUE, '2026-11-02T17:29:08.648754', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5569, 363, '01:51:05', 'Errori di scena / Posizione', 'Nella sequenza finale dell''attacco delle creature indigene di Niflheim, la tuta spaziale di Mickey presenta una grossa lacerazione da acido sul petto che scompare e riappare invertita di lato nelle riprese da angolazioni differenti.', TRUE, '2026-11-02T17:29:08.648754', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5570, 192, '00:15:20', 'Errori di scena / Posizione', 'Durante la sequenza in cui Valentine studia nella sua stanza, i libri e i fogli sulla scrivania cambiano disposizione e inclinazione tra un''inquadratura e l''altra, senza che il personaggio li tocchi.', TRUE, '2026-11-03T07:53:50.028971', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5571, 192, '00:42:10', 'Troupe o microfoni visibili', 'In una scena girata all''interno di un caffè parigino, si intravede fugacemente il riflesso di un''asta per microfono (boom) sulla vetrata alle spalle di Ned.', TRUE, '2026-11-03T07:53:50.028971', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5572, 192, '01:12:45', 'Errori di scena / Posizione', 'Mentre Valentine cammina per strada con un soprabito, la sciarpa al collo cambia posizione e nodo passando da un primo piano al campo medio successivo.', TRUE, '2026-11-03T07:53:50.028971', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5573, 345, '00:15:20', 'Errori di scena / Posizione', 'Durante una delle sequenze comiche all''interno della stanza, gli oggetti sul tavolo cambiano posizione tra un''inquadratura e l''altra, in particolare una bottiglia e un bicchiere che appaiono e scompaiono o si spostano di diversi centimetri senza che nessuno li tocchi.', TRUE, '2026-11-03T07:54:05.849295', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5574, 345, '00:42:10', 'Troupe o microfoni visibili', 'In un campo medio girato in esterni, durante una battuta di Lino Banfi, è possibile intravedere brevemente l''ombra di un microfono boom proiettata sulla parete alle sue spalle.', TRUE, '2026-11-03T07:54:05.849295', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5575, 345, '01:05:45', 'Errori di scena / Posizione', 'Nei cambi d''inquadratura durante la scena della possessione parodistica, l''acconciatura e la posizione dei capelli di Didi Perego variano visibilmente, passando da ordinati a completamente arruffati tra un primo piano e il controcampo.', TRUE, '2026-11-03T07:54:05.849295', NULL, 0, 0, 'IA (Admin)', 'IA Verificata', NULL),
(5576, 365, '00:12:45', 'Errori di scena / Posizione', 'Quando Eddie Valiant entra nel suo ufficio e si siede alla scrivania, la posizione del bicchiere e della bottiglia di bourbon cambia vistosamente tra un''inquadratura e l''altra, spostandosi da destra a sinistra del bordo del tavolo senza che nessuno li abbia toccati.', TRUE, '2026-11-03T15:42:08.196491', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5577, 365, '00:34:20', 'Troupe o microfoni visibili', 'Durante la sequenza del bar ''Ink and Paint Club'', in un''inquadratura grandangolare che mostra i clienti di Cartoonia, è possibile intravedere brevemente il riflesso di un microfono boom sulla superficie lucida del pianoforte a coda suonato da Daffy Duck.', TRUE, '2026-11-03T15:42:08.196491', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5578, 365, '00:58:10', 'Anacronismi', 'Il film è ambientato nel 1947, ma durante la scena dell''inseguimento in taxi con Benny the Cab, si nota chiaramente sullo sfondo un cartellone pubblicitario con un tipo di carattere e un design tipico degli anni ''50 inoltrati.', TRUE, '2026-11-03T15:42:08.196491', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5579, 365, '01:15:30', 'Errori di scena / Posizione', 'Nella scena in cui il giudice Turpin (Giudice Morton) minaccia Roger Rabbit legato alla sedia, i guanti bianchi di Roger compaiono e scompaiono tra un cambio di inquadratura e il successivo.', TRUE, '2026-11-03T15:42:08.196491', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5580, 366, '00:12:05', 'Errori di scena / Posizione', 'Durante il colloquio tra Clarice Starling e il dottor Hannibal Lecter nel manicomio criminale, la posizione dei fascicoli e dei documenti sulla scrivania e sulle sbarre cambia visibilmente tra un cambio di inquadratura e l''altro.', TRUE, '2026-11-03T15:42:46.714239', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5581, 366, '00:45:30', 'Troupe o microfoni visibili', 'In una delle sequenze all''interno dell''ascensore e nei corridoi della sede dell''FBI, si può intravedere per un istante il riflesso di un microfono boom o di parte dell''attrezzatura della troupe su una superficie lucida o vetrata.', TRUE, '2026-11-03T15:42:46.714239', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5582, 366, '01:14:20', 'Errori di scena / Posizione', 'Quando Clarice entra nel magazzino dell''azienda di vestiti appartenuto a Buffalo Bill, i vestiti appesi intorno a lei cambiano disposizione e distanza tra le inquadrature larghe e i primi piani.', TRUE, '2026-11-03T15:42:46.714239', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5583, 366, '01:32:10', 'Errori di scena / Posizione', 'Nel corso della sparatoria finale al buio con i visori notturni, la posizione dell''arma impugnata da Buffalo Bill e il modo in cui tiene la torcia variano repentinamente tra un''inquadratura e la successiva.', TRUE, '2026-11-03T15:42:46.714239', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5584, 367, '00:24:15', 'Errori di scena / Posizione', 'Durante la sequenza in cucina, il coltello tenuto in mano dalla protagonista cambia impugnatura tra due inquadrature ravvicinate: passa dalla mano destra alla sinistra senza che il personaggio abbia compiuto alcun movimento visibile.', TRUE, '2026-11-03T16:14:25.55169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5585, 367, '00:48:30', 'Troupe o microfoni visibili', 'In un''inquadratura grandangolare nel corridoio del Virgil, è possibile scorgere brevemente l''ombra di un microfono boom proiettata sulla parete di sinistra mentre il personaggio di Zazie Beetz cammina verso la telecamera.', TRUE, '2026-11-03T16:14:25.55169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5586, 367, '01:12:45', 'Errori di scena / Posizione', 'La ferita sul braccio di Myha''la appare e scompare tra diverse inquadrature durante la scena della fuga nel seminterrato; in un taglio è visibile il cerotto, in quello successivo la pelle è pulita.', TRUE, '2026-11-03T16:14:25.55169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5587, 367, '01:35:20', 'Errori di scena / Posizione', 'Il bicchiere di vino sul tavolo accanto a Patricia Arquette è pieno a metà in un''inquadratura e quasi vuoto in quella immediatamente successiva, nonostante non sia stato toccato.', TRUE, '2026-11-03T16:14:25.55169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5588, 367, '01:42:10', 'Troupe o microfoni visibili', 'Nel riflesso della vetrata durante la scena finale, si nota per un istante il riflesso di un operatore di ripresa che indossa una giacca riflettente di colore scuro.', TRUE, '2026-11-03T16:14:25.55169', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5590, 364, '00:45:22', 'Errori di scena / Posizione', 'In un''inquadratura ravvicinata, il bicchiere di carta tenuto in mano da Robert Pattinson è pieno fino all''orlo; nell''inquadratura successiva, ripresa da un''angolazione diversa, il bicchiere appare visibilmente vuoto.', TRUE, '2026-11-03T16:15:04.05848', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5591, 364, '01:12:40', 'Troupe o microfoni visibili', 'Durante una ripresa in esterni, il riflesso di un operatore con una cinepresa digitale è chiaramente visibile sulla superficie lucida di una portiera di un''auto parcheggiata.', TRUE, '2026-11-03T16:15:04.05848', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5592, 364, '01:35:10', 'Errori storici o fattuali', 'Viene mostrato un servizio del telegiornale che cita un evento accaduto nel 2007, ma il contesto narrativo della scena è chiaramente collocato nell''autunno del 2006.', TRUE, '2026-11-03T16:15:04.05848', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5593, 364, '01:52:05', 'Errori di scena / Posizione', 'La posizione della cravatta di Chris Hansen cambia drasticamente tra due inquadrature consecutive durante il confronto finale, passando da perfettamente annodata a leggermente allentata.', TRUE, '2026-11-03T16:15:04.05848', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5594, 366, '00:15:20', 'Errori di scena / Posizione', 'Quando Clarice Starling cammina lungo il corridoio dell''Accademia dell''FBI in Virginia all''inizio del film, porta con sé dei libri e una cartella. Tra un''inquadratura e l''altra, il modo in cui stringe i libri sotto il braccio cambia drasticamente, passando da una mano all''altra senza soluzione di continuità temporale.', TRUE, '2026-11-03T16:16:06.003272', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5595, 366, '00:42:10', 'Errori di scena / Posizione', 'Nella scena in cui il senatore Ruth Martin lancia un appello televisivo per la liberazione di sua figlia Catherine, i microfoni dei giornalisti posti sul podio cambiano inclinazione e posizione esatta tra i campi lunghi e i primi piani stretti.', TRUE, '2026-11-03T16:16:06.003272', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5596, 366, '01:14:50', 'Errori di scena / Posizione', 'Durante l''autopsia sul corpo della prima vittima rinvenuta nel fiume, gli strumenti chirurgici sul carrello metallico accanto al medico legale cambiano disposizione e numero tra un taglio di montaggio e il successivo.', TRUE, '2026-11-03T16:16:06.003272', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5597, 366, '01:32:05', 'Troupe o microfoni visibili', 'Nella sequenza in cui Clarice si reca nella casa di Jame Gumb (Buffalo Bill) a Calumet City, mentre suona il campanello e l''inquadratura inquadra la porta d''ingresso da una prospettiva ravvicinata, è possibile intravedere brevemente il riflesso di un membro della troupe con attrezzatura sul vetro della porta.', TRUE, '2026-11-03T16:16:06.003272', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5598, 344, '00:12:45', 'Errori di scena / Posizione', 'Durante la scena in cui Harriet ascolta il vinile nel suo appartamento, la posizione del braccio del giradischi cambia visibilmente tra le inquadrature ravvicinate e quelle a campo largo, passando da una posizione interna verso il centro del disco a una più esterna.', TRUE, '2026-11-03T17:29:08.946187', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5599, 344, '00:48:20', 'Errori di scena / Posizione', 'In una sequenza di flashback, la tazza di caffè tenuta in mano da Max cambia livello di riempimento in modo incoerente tra due inquadrature consecutive durante la conversazione.', TRUE, '2026-11-03T17:29:08.946187', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5600, 344, '01:05:12', 'Errori di scena / Posizione', 'Quando Harriet cammina per strada, la sua borsa cambia spalla tra un taglio di montaggio e l''altro mentre attraversa l''incrocio.', TRUE, '2026-11-03T17:29:08.946187', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5601, 344, '01:22:30', 'Troupe o microfoni visibili', 'In un''inquadratura riflessa su una vetrina di un negozio, è possibile intravedere brevemente l''ombra di un membro della troupe che si sposta rapidamente per uscire dall''inquadratura.', TRUE, '2026-11-03T17:29:08.946187', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5602, 32, '00:24:15', 'Errori di scena / Posizione', 'Durante una conversazione tra Macrinus e i suoi attendenti, il calice tenuto da Denzel Washington cambia mano e livello di riempimento tra un''inquadratura in primo piano e il controcampo.', TRUE, '2026-11-03T17:30:53.885597', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5603, 32, '01:12:40', 'Anacronismi', 'In una scena ambientata nei sotterranei del Colosseo, si intravede chiaramente l''uso di una lampadina moderna a LED inserita in un supporto scenografico a torcia.', TRUE, '2026-11-03T17:30:53.885597', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5604, 32, '01:45:10', 'Troupe o microfoni visibili', 'Durante la caotica mischia nel combattimento finale nell''arena, per un fotogramma si intraversa l''ombra di un braccio di un microfono boom proiettata sulla sabbia accanto a un gladiatore.', TRUE, '2026-11-03T17:30:53.885597', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5605, 32, '00:28:15', 'Errori di scena / Posizione', 'Durante l''arrivo dei prigionieri a Roma, le catene ai polsi di Lucio scompaiono e riappaiono tra un cambio d''inquadratura e l''altra mentre scende dai carri.', TRUE, '2026-11-03T17:30:53.885597', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5606, 32, '01:12:40', 'Anacronismi', 'In una scena in cui i soldati romani si preparano alla battaglia, uno dei legionari indossa chiaramente stivali con suola in gomma moderna anziché i tradizionali sandali militari romani (caligae).', TRUE, '2026-11-03T17:30:53.885597', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5607, 32, '01:45:20', 'Troupe o microfoni visibili', 'Sul finire del drammatico confronto verbale tra i senatori nei corridoi del palazzo, si intravede per un istante il riflesso di una luce di riempimento e del cavalletto di una telecamera su una colonna di marmo lucido sullo sfondo.', TRUE, '2026-11-03T17:30:53.885597', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5608, 32, '02:04:10', 'Errori storici o fattuali', 'Nel corso del climax finale, i cavalli utilizzati dai pretoriani mostrano bardature con fibbie in metallo nichelato moderno, materiale non disponibile o impiegato con quella foggia nell''antica Roma imperiale.', TRUE, '2026-11-03T17:30:53.885597', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL);
INSERT INTO public.errori ("id", "film_id", "minuto", "categoria", "descrizione", "approvato", "creato_il", "youtube_query", "conferme", "contestazioni", "inserito_da", "provenienza", "screenshot_url") VALUES
(5609, 268, '00:24:15', 'Errori di scena / Posizione', 'Durante la scena del confronto nel diner, il bicchiere di whisky di Leonardo DiCaprio cambia visibilmente livello di riempimento tra un''inquadratura e l''altra, passando da quasi vuoto a metà pieno in un taglio di montaggio ravvicinato.', TRUE, '2026-11-03T17:31:12.373683', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5610, 268, '00:48:30', 'Troupe o microfoni visibili', 'In una ripresa grandangolare all''interno del magazzino, è possibile scorgere brevemente l''ombra di un microfono boom proiettata sulla parete di fondo dietro il personaggio interpretato da Benicio Del Toro.', TRUE, '2026-11-03T17:31:12.373683', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5611, 268, '01:12:45', 'Errori di scena / Posizione', 'Nella sequenza dell''inseguimento in auto, la ferita sulla fronte del personaggio di Sean Penn appare e scompare tra le inquadrature interne ed esterne del veicolo.', TRUE, '2026-11-03T17:31:12.373683', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5612, 268, '01:35:20', 'Anacronismi', 'Il film è ambientato nel 2025, ma in una scena di flashback che dovrebbe risalire a sedici anni prima (2009), si nota un passante che utilizza uno smartphone con un design chiaramente riconducibile a un modello uscito dopo il 2015.', TRUE, '2026-11-03T17:31:12.373683', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5613, 268, '02:05:10', 'Errori di scena / Posizione', 'Durante la sparatoria finale, l''arma impugnata da Chase Infiniti cambia modello tra un''inquadratura e la successiva, passando da una pistola semiautomatica a un revolver in un cambio di campo-controcampo.', TRUE, '2026-11-03T17:31:12.373683', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5614, 368, '00:28:15', 'Errori di scena / Posizione', 'Durante la sequenza di inseguimento nella foresta, la ferita sul braccio sinistro di Thia appare visibilmente pulita e priva di sangue in un''inquadratura ravvicinata, per poi tornare coperta di sangue sporco nell''inquadratura successiva.', TRUE, '2026-11-03T17:36:43.032297', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5615, 368, '00:45:30', 'Troupe o microfoni visibili', 'In un campo lungo che inquadra il terreno roccioso, è possibile intravedere brevemente l''ombra di un braccio meccanico (crane) che si sposta rapidamente fuori campo nell''angolo in basso a sinistra dello schermo.', TRUE, '2026-11-03T17:36:43.032297', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5616, 368, '01:12:45', 'Errori di scena / Posizione', 'Il dispositivo tecnologico indossato dal Predatore cambia posizione sul braccio: in un''inquadratura è fissato sopra il gomito, mentre nel controcampo immediato risulta posizionato sull''avambraccio.', TRUE, '2026-11-03T17:36:43.032297', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5617, 368, '01:35:20', 'Anacronismi', 'Il display olografico utilizzato da Thia mostra un''interfaccia con font tipografici moderni (Sans Serif standard) che risultano incoerenti con l''estetica aliena e futuristica stabilita nelle scene precedenti.', TRUE, '2026-11-03T17:36:43.032297', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5618, 368, '01:52:10', 'Errori di scena / Posizione', 'Durante la battaglia finale, la quantità di detriti e vegetazione bruciata attorno ai personaggi varia drasticamente tra i tagli di montaggio, passando da un terreno quasi pulito a un''area pesantemente devastata.', TRUE, '2026-11-03T17:36:43.032297', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5619, 369, '00:28:45', 'Errori di scena / Posizione', 'Durante la sequenza di preparazione all''immersione, la posizione del tubo dell''ossigeno collegato al casco di Chris cambia visibilmente tra un''inquadratura e l''altra, passando da sopra la spalla destra a sotto il braccio sinistro senza che il personaggio si sia mosso.', TRUE, '2026-11-03T17:42:48.271956', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5620, 369, '00:42:12', 'Errori storici o fattuali', 'La dinamica della decompressione mostrata nel film non rispetta le tabelle standard di immersione per profondità estreme; il tempo di risalita simulato è fisicamente incompatibile con la pressione ambientale descritta nella narrazione.', TRUE, '2026-11-03T17:42:48.271956', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5621, 369, '01:15:30', 'Troupe o microfoni visibili', 'In un primo piano stretto sul volto di Woody Harrelson all''interno della camera iperbarica, è possibile notare per un breve istante il riflesso di una luce LED da set sulla superficie curva del visore del casco.', TRUE, '2026-11-03T17:42:48.271956', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5622, 369, '01:05:20', 'Errori di scena / Posizione', 'La quantità di acqua presente sul pavimento della cabina di controllo varia drasticamente tra due inquadrature consecutive durante la fase di emergenza, passando da una pozza estesa a una superficie quasi asciutta.', TRUE, '2026-11-03T17:42:48.271956', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5623, 369, '01:22:15', 'Errori di scena / Posizione', 'Il segno di una ferita sul volto di uno dei sommozzatori appare meno marcato e con una diversa coagulazione del sangue rispetto alla scena immediatamente precedente, indicando un errore di continuità nel trucco di scena.', TRUE, '2026-11-03T17:42:48.271956', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5624, 370, '00:22:15', 'Errori di scena / Posizione', 'Quando il protagonista tenta di forzare la portiera dall''interno, la posizione della sua mano sulla maniglia cambia visibilmente tra un''inquadratura ravvicinata e il campo lungo successivo.', TRUE, '2026-11-03T17:43:17.319665', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5625, 370, '00:45:30', 'Troupe o microfoni visibili', 'Durante una ripresa ravvicinata del riflesso sul finestrino del SUV, è possibile intravedere brevemente la sagoma di un operatore della troupe e parte dell''attrezzatura di illuminazione.', TRUE, '2026-11-03T17:43:17.319665', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5626, 370, '01:12:40', 'Errori di scena / Posizione', 'La ferita sul volto del protagonista appare e scompare leggermente in termini di intensità del trucco tra due inquadrature consecutive durante il confronto verbale con l''antagonista.', TRUE, '2026-11-03T17:43:17.319665', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5627, 370, '01:28:10', 'Errori di scena / Posizione', 'L''oggetto che il protagonista utilizza per tentare di rompere il vetro cambia posizione sul sedile del passeggero tra l''inquadratura soggettiva e quella esterna.', TRUE, '2026-11-03T17:43:17.319665', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5628, 370, '00:42:15', 'Errori di scena / Posizione', 'Mentre il personaggio interpretato da Bill Skarsgård cerca disperatamente di recuperare lo smartphone sul pavimento del SUV, la posizione del cavo di ricarica collegato alla plancia varia drasticamente tra l''inquadratura dall''alto e il primo piano stretto.', TRUE, '2026-11-03T17:43:25.7434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5629, 370, '01:12:40', 'Troupe o microfoni visibili', 'Durante una rapida panoramica della telecamera intorno al SUV in una scena notturna, per un fotogramma si intravede il riflesso di un pannello LED di illuminazione sulla carrozzeria lucida dello sportello posteriore.', TRUE, '2026-11-03T17:43:25.7434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5630, 370, '00:22:15', 'Errori di scena / Posizione', 'Quando il protagonista tenta di forzare il blocco elettronico, la spia luminosa sul cruscotto passa da rossa a spenta tra due inquadrature ravvicinate, nonostante non sia stata effettuata alcuna interazione con i comandi.', TRUE, '2026-11-03T17:43:25.7434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5631, 370, '00:45:30', 'Errori di scena / Posizione', 'La quantità di pioggia sul parabrezza del SUV cambia drasticamente tra l''inquadratura interna e quella esterna durante la sequenza di tensione, passando da un vetro quasi asciutto a completamente bagnato in un taglio di montaggio di pochi secondi.', TRUE, '2026-11-03T17:43:25.7434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5632, 370, '01:05:12', 'Troupe o microfoni visibili', 'Durante un''inquadratura dal basso verso l''alto che inquadra il finestrino laterale posteriore, è possibile scorgere per un breve istante l''ombra di un microfono boom proiettata sul rivestimento interno in pelle del tettuccio.', TRUE, '2026-11-03T17:43:25.7434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5633, 370, '01:18:45', 'Errori di scena / Posizione', 'Il livello di carburante indicato sul display digitale del cruscotto varia da ''riserva'' a ''metà serbatoio'' tra due inquadrature consecutive, nonostante il motore sia rimasto spento per tutta la durata della scena.', TRUE, '2026-11-03T17:43:25.7434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5634, 370, '01:28:10', 'Errori di scena / Posizione', 'La posizione della giacca del protagonista, che era stata precedentemente strappata sulla spalla destra durante la colluttazione, appare integra in un''inquadratura a campo lungo prima di tornare strappata nell''inquadratura successiva.', TRUE, '2026-11-03T17:43:25.7434', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5635, 371, '00:14:22', 'Errori di scena / Posizione', 'Nella scena del colloquio tra Zsa-zsa Korda e Liesl nel convento, il rosario tenuto in mano da Liesl cambia posizione tra la mano destra e la sinistra in due inquadrature consecutive durante il primo piano.', TRUE, '2026-11-03T17:44:14.772183', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5636, 371, '00:42:15', 'Troupe o microfoni visibili', 'Durante la sequenza del banchetto all''aperto, il riflesso di un operatore con una cinepresa compatta è chiaramente visibile sulla superficie lucida di una teiera d''argento posta al centro del tavolo.', TRUE, '2026-11-03T17:44:14.772183', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5637, 371, '01:08:45', 'Errori di scena / Posizione', 'Il bicchiere di vino di Benicio Del Toro passa da essere mezzo pieno a quasi vuoto nel giro di un singolo taglio di montaggio mentre si trova nel salone dell''aereo privato.', TRUE, '2026-11-03T17:44:14.772183', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5638, 371, '01:22:10', 'Anacronismi', 'Il film è ambientato in un periodo non specificato ma con estetica anni ''60; tuttavia, sul cruscotto dell''auto d''epoca guidata da Michael Cera è visibile un display digitale a cristalli liquidi per il controllo della temperatura, tecnologicamente incompatibile con il contesto scenografico.', TRUE, '2026-11-03T17:44:14.772183', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5639, 371, '01:45:30', 'Errori di scena / Posizione', 'La ferita sulla fronte di Zsa-zsa Korda, causata dall''incidente aereo iniziale, scompare completamente durante la scena del confronto finale sotto la pioggia, per poi riapparire nell''inquadratura successiva.', TRUE, '2026-11-03T17:44:14.772183', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5640, 372, '00:14:22', 'Errori di scena / Posizione', 'Durante la scena dell''interrogatorio, la tazza di caffè sulla scrivania di Frank Drebin Jr. cambia posizione tra un''inquadratura e l''altra: inizialmente è posta a destra del fascicolo, mentre nell''inquadratura successiva appare spostata verso il centro del tavolo.', TRUE, '2026-11-03T17:45:30.448685', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5641, 372, '00:42:15', 'Troupe o microfoni visibili', 'Nella sequenza dell''inseguimento in auto, durante un riflesso ravvicinato sulla carrozzeria cromata della vettura di Frank, è possibile intravedere brevemente l''ombra di un operatore di ripresa e parte dell''attrezzatura di illuminazione.', TRUE, '2026-11-03T17:45:30.448685', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5642, 372, '01:05:30', 'Errori di scena / Posizione', 'Nella scena del gala, la cravatta di Frank Drebin Jr. appare visibilmente storta e annodata in modo diverso in due inquadrature consecutive riprese da angolazioni opposte.', TRUE, '2026-11-03T17:45:30.448685', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5643, 372, '01:18:45', 'Anacronismi', 'In una scena ambientata in un ufficio che dovrebbe riflettere uno stile anni ''90, è visibile sullo sfondo un dispositivo di domotica moderna (smart speaker) non coerente con l''ambientazione temporale della sequenza.', TRUE, '2026-11-03T17:45:30.448685', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5644, 372, '01:25:10', 'Errori di scena / Posizione', 'Durante la sparatoria finale nel magazzino, il caricatore della pistola di Frank appare inserito in un''inquadratura e rimosso in quella immediatamente successiva, nonostante il personaggio non abbia compiuto alcuna azione di ricarica.', TRUE, '2026-11-03T17:45:30.448685', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5645, 373, '00:14:20', 'Errori di scena / Posizione', 'Durante la sequenza dell''incidente stradale, la posizione dell''unicorno sull''asfalto cambia visibilmente tra l''inquadratura larga dell''impatto e il primo piano successivo, con la testa dell''animale che risulta orientata in direzioni opposte rispetto alla linea di mezzeria.', TRUE, '2026-11-03T17:46:08.137002', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5646, 373, '00:42:15', 'Errori di scena / Posizione', 'Nella scena in cui Elliot e Ridley discutono nella cucina della tenuta, il bicchiere d''acqua tenuto da Paul Rudd cambia livello di riempimento in modo incoerente tra un''inquadratura e l''altra, passando da quasi pieno a metà in un singolo taglio di montaggio.', TRUE, '2026-11-03T17:46:08.137002', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5647, 373, '01:05:30', 'Troupe o microfoni visibili', 'Durante una ripresa in esterni nei boschi, il riflesso di un pannello riflettente (usato per la luce di riempimento) è chiaramente visibile per alcuni fotogrammi sulla carrozzeria lucida dell''auto di Elliot.', TRUE, '2026-11-03T17:46:08.137002', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5648, 373, '01:18:45', 'Errori di scena / Posizione', 'Nella scena del confronto finale, la ferita sul braccio di uno dei personaggi Leopold appare e scompare tra inquadrature ravvicinate e campi medi, a causa di una gestione non uniforme del trucco di scena durante le riprese.', TRUE, '2026-11-03T17:46:08.137002', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5649, 373, '01:25:10', 'Errori di scena / Posizione', 'Gli oggetti presenti sul tavolo da laboratorio di Odell Leopold cambiano disposizione in modo netto: alcuni strumenti chirurgici che erano stati spostati a sinistra in un''inquadratura tornano magicamente al centro del tavolo nell''inquadratura successiva.', TRUE, '2026-11-03T17:46:08.137002', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5650, 257, '00:42:15', 'Errori di scena / Posizione', 'Durante il dialogo tra Ulisse e Penelope, la ferita sul braccio destro di Ulisse scompare completamente in un''inquadratura ravvicinata, per poi riapparire sanguinante nel controcampo successivo.', TRUE, '2026-11-03T18:41:52.056036', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5651, 257, '01:18:40', 'Anacronismi', 'In una ripresa aerea della flotta, si nota chiaramente la scia di un aereo di linea moderno che attraversa il cielo azzurro, visibile per alcuni fotogrammi prima di essere tagliata dal montaggio.', TRUE, '2026-11-03T18:41:52.056036', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5652, 257, '01:55:22', 'Troupe o microfoni visibili', 'Nel riflesso dello scudo di bronzo tenuto da un soldato durante la battaglia, è possibile distinguere chiaramente la sagoma di un operatore di ripresa che indossa una giacca tecnica riflettente.', TRUE, '2026-11-03T18:41:52.056036', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5653, 257, '02:12:05', 'Errori di scena / Posizione', 'La posizione della ciotola di legno davanti a Telemaco cambia drasticamente tra due inquadrature consecutive: inizialmente è posta a sinistra del piatto, poi appare improvvisamente a destra senza che il personaggio l''abbia toccata.', TRUE, '2026-11-03T18:41:52.056036', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5654, 257, '02:35:10', 'Errori storici o fattuali', 'Il banchetto finale mostra l''utilizzo di posate in argento con incisioni floreali tipiche dello stile rococò, un anacronismo stilistico di oltre duemila anni rispetto all''epoca micenea rappresentata.', TRUE, '2026-11-03T18:41:52.056036', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5655, 374, '00:12:45', 'Errori di scena / Posizione', 'Durante la scena nell''ufficio di Vincent Ludwig, il posizionamento delle cartelle e dei bicchieri sulla scrivania cambia visivamente tra un''inquadratura e l''altra, senza che nessuno li abbia toccati.', TRUE, '2026-11-04T17:54:59.39643', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5656, 374, '00:34:20', 'Troupe o microfoni visibili', 'In una delle sequenze in esterni in cui Frank Drebin guida la sua auto della polizia, è chiaramente visibile il riflesso di una luce di studio e parte della struttura del rig di montaggio della telecamera sul finestrino laterale.', TRUE, '2026-11-04T17:54:59.39643', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5657, 374, '01:05:10', 'Errori di scena / Posizione', 'Nella sequenza clou dello stadio di baseball, la quantità di birra nel bicchiere tenuto da Frank Drebin varia vistosamente da mezzo pieno a quasi vuoto e viceversa a seconda dell''angolo di ripresa.', TRUE, '2026-11-04T17:54:59.39643', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5658, 374, '00:15:22', 'Errori di scena / Posizione', 'Durante la conferenza stampa, il microfono sul podio cambia inclinazione e posizione tra un''inquadratura frontale e quella di profilo di Frank Drebin.', TRUE, '2026-11-04T17:54:59.39643', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5659, 374, '00:42:10', 'Troupe o microfoni visibili', 'Nel riflesso delle vetrate dell''ospedale mentre Frank entra di corsa, è possibile intravedere brevemente l''ombra di un operatore con la cinepresa.', TRUE, '2026-11-04T17:54:59.39643', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5660, 374, '01:12:45', 'Errori di scena / Posizione', 'Nella scena in cui Frank si trova nell''ufficio del sindaco, i documenti sulla scrivania cambiano disposizione da disordinati a perfettamente impilati a seconda del cambio di inquadratura.', TRUE, '2026-11-04T17:54:59.39643', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5661, 375, '00:45:12', 'Errori di scena / Posizione', 'Durante una conversazione tra i soldati italiani all''aperto, la posizione delle bottiglie di vino sul tavolo cambia visibilmente tra un''inquadratura e l''altra, passando da ritte a inclinate senza che nessuno le abbia toccate.', TRUE, '2026-11-04T19:50:34.334515', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5662, 375, '01:12:30', 'Anacronismi', 'In una scena ambientata nel 1942 nell''isola greca, sullo sfondo si intravede brevemente il passaggio di un''imbarcazione moderna dotata di dotazioni tecnologiche e verniciature non coerenti con il periodo della Seconda Guerra Mondiale.', TRUE, '2026-11-04T19:50:34.334515', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5663, 375, '00:45:12', 'Anacronismi', 'In una sequenza girata nel villaggio dell''isola, si nota chiaramente sullo sfondo un cavo elettrico moderno e isolato con materiali non coerenti con il periodo storico del 1941-1943.', TRUE, '2026-11-04T19:50:34.334515', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5664, 375, '01:12:30', 'Errori di scena / Posizione', 'Durante la scena del pranzo collettivo, il piatto di pasta davanti a Farina (Gigio Alberti) si riempie e si svuota alternativamente tra un primo piano e un campo largo senza che il personaggio tocchi il cibo.', TRUE, '2026-11-04T19:50:34.334515', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5665, 375, '00:35:12', 'Errori di scena / Posizione', 'Durante la scena in cui i soldati giocano a calcio sulla spiaggia, la posizione della maglia di Vassilis (Vasso Kavadadas) cambia visibilmente tra un cambio di inquadratura e l''altra, passando dall''essere indossata correttamente a essere tenuta in mano.', TRUE, '2026-11-04T19:51:10.262188', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5666, 375, '01:12:45', 'Anacronismi', 'In una sequenza girata nella piazza del paese, si nota chiaramente sul muro di una casa un''antenna televisiva moderna a griglia, totalmente anacronistica per gli anni della seconda guerra mondiale (1941-1943).', TRUE, '2026-11-04T19:51:10.262188', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5667, 375, '01:25:30', 'Errori storici o fattuali', 'Il mitragliatore Breda modello 30 utilizzato dai soldati italiani in alcune sequenze presenta caricatori e dettagli visivi che mostrano incongruenze rispetto alla versione effettivamente in dotazione al Regio Esercito nel 1941.', TRUE, '2026-11-04T19:51:10.262188', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5668, 375, '00:28:45', 'Errori di scena / Posizione', 'Durante la scena in cui i soldati arrivano sull''isola, la posizione del fucile a tracolla di uno dei soldati cambia istantaneamente tra un''inquadratura frontale e quella di spalle, passando dalla spalla destra alla sinistra senza che il personaggio si sia mosso.', TRUE, '2026-11-04T19:51:10.262188', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5669, 375, '00:45:12', 'Anacronismi', 'In una ripresa panoramica del villaggio, si nota brevemente un segno di vernice spray moderna su una roccia vicino al sentiero, utilizzata probabilmente dalla produzione per indicare il percorso alla troupe.', TRUE, '2026-11-04T19:51:10.262188', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5670, 375, '01:12:30', 'Errori di scena / Posizione', 'Nella scena in cui il sergente Lo Russo (Diego Abatantuono) scrive sul suo diario, la posizione della penna e del calamaio sul tavolo varia sensibilmente tra i primi piani e i campi medi, nonostante il personaggio non abbia mai interrotto la scrittura.', TRUE, '2026-11-04T19:51:10.262188', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5671, 375, '01:25:15', 'Troupe o microfoni visibili', 'Durante un movimento di macchina che segue i soldati lungo la spiaggia, per un breve fotogramma si intravede l''ombra dell''asta del microfono (boom) proiettata sulla sabbia vicino ai piedi di uno dei protagonisti.', TRUE, '2026-11-04T19:51:10.262188', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5672, 375, '01:38:20', 'Errori storici o fattuali', 'Il velivolo che sorvola l''isola verso la fine del film presenta una marcatura di identificazione che non corrisponde esattamente allo stile grafico e alla posizione regolamentare utilizzata dalla Regia Aeronautica nel 1943.', TRUE, '2026-11-04T19:51:10.262188', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5673, 376, '00:15:22', 'Errori di scena / Posizione', 'Durante la lettura del testamento di Madame D., la posizione delle mani del notaio Kovacs (Jeff Goldblum) sul documento cambia visibilmente tra un''inquadratura e l''altra, passando dall''avere le dita distese ai bordi a tenerlo saldamente ripiegato verso l''interno.', TRUE, '2026-11-04T19:53:29.706366', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5674, 376, '00:42:10', 'Anacronismi', 'Nel corso della fuga in treno, la locomotiva a vapore e i vagoni presentano dettagli strutturali e targhe di identificazione tipiche di restauri museali moderni piuttosto che dell''effettivo periodo storico fittizio in cui è ambientata la vicenda (anni ''30).', TRUE, '2026-11-04T19:53:29.706366', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5675, 376, '01:05:45', 'Errori storici o fattuali', 'I dipinti e le cornici rinascimentali trafugate cambiano leggermente spessore della doratura e dettagli della tela tra le scene girate negli interni dell''hotel e quelle in primo piano durante il trasporto nelle casse di legno.', TRUE, '2026-11-04T19:53:29.706366', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5676, 376, '00:15:20', 'Errori di scena / Posizione', 'Durante la sequenza nella hall dell''hotel, il giornale tenuto in mano da un cliente cambia orientamento e piegatura tra un''inquadratura in campo medio e il successivo primo piano.', TRUE, '2026-11-04T19:53:29.706366', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5677, 376, '00:42:10', 'Anacronismi', 'Nella scena in cui Zero e Gustave viaggiano con i mezzi di trasporto della Repubblica di Zubrowka, alcuni veicoli sullo sfondo montano pneumatici con battistrada e valvole chiaramente riconducibili a standard produttivi successivi all''epoca in cui è ambientata la storia.', TRUE, '2026-11-04T19:53:29.706366', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL),
(5678, 376, '01:05:45', 'Errori di scena / Posizione', 'Nel corso della rissa nel monastero, la tazza di caffè sul tavolo trabocca vistosamente in un''inquadratura e risulta quasi vuota in quella immediatamente successiva senza che nessuno l''abbia toccata.', TRUE, '2026-11-04T19:53:29.706366', NULL, 0, 0, 'mrtrrt67@gmail.com', 'IA Verificata', NULL);
